def _load_env_file():
    """Load credentials from .env file if env vars are missing."""
    env_path = os.path.join(os.path.dirname(__file__) or '.', '.env')
    if not os.path.exists(env_path):
        return
    try:
        with open(env_path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#') or '=' not in line:
                    continue
                key, _, value = line.partition('=')
                key = key.strip()
                value = value.strip().strip('"').strip("'")
                if key and value and not os.environ.get(key):
                    os.environ[key] = value
        logger.debug("Loaded credentials from .env")
    except Exception as e:
        logger.debug(f"Could not load .env: {e}")


def _get_alpaca_config() -> Optional[dict]:
    """Get Alpaca paper trading config from env vars."""
    _load_env_file()
    api_key = os.environ.get('ALPACA_API_KEY', '')
    secret_key = os.environ.get('ALPACA_SECRET_KEY', '')
    if not api_key or not secret_key:
        return None
    # Trade execution key (paper account for orders)
    trade_api_key = os.environ.get('ALPACA_TRADE_API_KEY', '')
    trade_secret_key = os.environ.get('ALPACA_TRADE_SECRET_KEY', '')
    return {
        'api_key': api_key,              # Live key — used for SIP data
        'secret_key': secret_key,
        'trade_api_key': trade_api_key or api_key,   # Paper key — used for orders
        'trade_secret_key': trade_secret_key or secret_key,
        'base_url': 'https://paper-api.alpaca.markets',  # Orders go to paper
        'data_url': 'https://data.alpaca.markets',       # Data from SIP (live key)
    }


def _alpaca_headers(cfg: dict) -> dict:
    """Headers for DATA requests (live key with SIP access)."""
    return {
        'APCA-API-KEY-ID': cfg['api_key'],
        'APCA-API-SECRET-KEY': cfg['secret_key'],
    }


def _alpaca_trade_headers(cfg: dict) -> dict:
    """Headers for ORDER/ACCOUNT requests (paper key)."""
    return {
        'APCA-API-KEY-ID': cfg['trade_api_key'],
        'APCA-API-SECRET-KEY': cfg['trade_secret_key'],
    }


def _log_api_call(endpoint: str, method: str = 'GET', symbols: str = '',
                  status_code: int = 0, response_time_ms: float = 0,
                  error: str = '', rate_limit_remaining: int = -1,
                  params_json: str = '{}'):
    """Fire-and-forget API call logger (safe to call from any thread)."""
    try:
        db = get_price_db()
        db.insert_api_call(endpoint=endpoint, method=method, symbols=symbols,
                           params_json=params_json, status_code=status_code,
                           response_time_ms=response_time_ms, error=error,
                           rate_limit_remaining=rate_limit_remaining)
    except Exception:
        pass


def _log_rejected_candidate(candidate, stage: str, reason: str,
                             strategy_id: str = ''):
    """Fire-and-forget rejected candidate logger."""
    try:
        db = get_price_db()
        if isinstance(candidate, dict):
            c = candidate
        else:
            c = asdict(candidate) if hasattr(candidate, '__dataclass_fields__') else {}
        db.insert_rejected_candidate(
            symbol=c.get('symbol', ''),
            gap_pct=c.get('gap_pct', 0),
            vol_ratio=c.get('vol_ratio', 0),
            score=c.get('score', 0),
            direction=c.get('direction', ''),
            rejection_stage=stage,
            rejection_reason=reason,
            catalyst=c.get('catalyst', ''),
            prev_close=c.get('prev_close', 0),
            open_price=c.get('open_price', 0),
            strategy_id=strategy_id,
        )
    except Exception:
        pass


# ---------------------------------------------------------------------------
# Multi-key API pool for parallel data fetching
# ---------------------------------------------------------------------------

@dataclass
class AlpacaKeySlot:
    """One Alpaca API key pair with per-minute rate tracking."""
    api_key: str
    secret_key: str
    slot_id: int = 0
    is_primary: bool = False  # Only primary key is used for order placement
    _calls_this_minute: int = field(default=0, repr=False)
    _minute_start: float = field(default=0.0, repr=False)
    _lock: threading.Lock = field(default_factory=threading.Lock, repr=False)

    # Alpaca free tier: 200 requests/min per key
    RATE_LIMIT = 180  # stay under limit

    def can_use(self) -> bool:
        """Check if this key has rate budget remaining."""
        with self._lock:
            now = _time.time()
            if now - self._minute_start >= 60:
                self._calls_this_minute = 0
                self._minute_start = now
            return self._calls_this_minute < self.RATE_LIMIT

    def record_use(self, n: int = 1):
        """Record N API calls against this key's rate budget."""
        with self._lock:
            now = _time.time()
            if now - self._minute_start >= 60:
                self._calls_this_minute = 0
                self._minute_start = now
            self._calls_this_minute += n

    def headers(self) -> dict:
        return {
            'APCA-API-KEY-ID': self.api_key,
            'APCA-API-SECRET-KEY': self.secret_key,
        }


class AlpacaKeyPool:
    """Pool of Alpaca API keys for parallel data fetching.

    Reads env vars:
      ALPACA_API_KEY / ALPACA_SECRET_KEY          — primary (slot 0)
      ALPACA_DATA_KEY_1..9 / ALPACA_DATA_SECRET_1..9 — additional data-only keys

    Primary key is the only one used for order placement.
    All keys are available for data fetching.
    """

    def __init__(self):
        self._slots: List[AlpacaKeySlot] = []
        self._robin_idx = 0
        self._lock = threading.Lock()
        self._load_keys()

    def _load_keys(self):
        _load_env_file()
        # Slot 0: primary trading key
        pk = os.environ.get('ALPACA_API_KEY', '')
        sk = os.environ.get('ALPACA_SECRET_KEY', '')
        if pk and sk:
            self._slots.append(AlpacaKeySlot(
                api_key=pk, secret_key=sk, slot_id=0, is_primary=True))

        # Slots 1-9: additional data-only keys
        for i in range(1, 10):
            dk = os.environ.get(f'ALPACA_DATA_KEY_{i}', '')
            ds = os.environ.get(f'ALPACA_DATA_SECRET_{i}', '')
            if dk and ds:
                self._slots.append(AlpacaKeySlot(
                    api_key=dk, secret_key=ds, slot_id=i, is_primary=False))

        if self._slots:
            logger.info(f"AlpacaKeyPool: {len(self._slots)} API key(s) loaded"
                        f" ({sum(1 for s in self._slots if not s.is_primary)} data-only)")

    @property
    def size(self) -> int:
        return len(self._slots)

    @property
    def primary(self) -> Optional[AlpacaKeySlot]:
        return self._slots[0] if self._slots else None

    def get_all(self) -> List[AlpacaKeySlot]:
        """Return all key slots (for parallel dispatching)."""
        return list(self._slots)

    def next_available(self) -> Optional[AlpacaKeySlot]:
        """Round-robin to next key that has rate budget."""
        if not self._slots:
            return None
        with self._lock:
            n = len(self._slots)
            for _ in range(n):
                slot = self._slots[self._robin_idx % n]
                self._robin_idx += 1
                if slot.can_use():
                    return slot
        # All slots exhausted — return first anyway (will 429)
        return self._slots[0]


# Module-level singleton — lazy-initialized on first access
_key_pool: Optional[AlpacaKeyPool] = None


def _get_key_pool() -> AlpacaKeyPool:
    global _key_pool
    if _key_pool is None:
        _key_pool = AlpacaKeyPool()
    return _key_pool


def fetch_alpaca_bars(symbol: str, start_date: str, end_date: str,
                      interval: str = '1Day', feed: str = 'sip') -> Optional[pd.DataFrame]:
    """Fetch historical bars from Alpaca Data API v2 with pagination."""
    cfg = _get_alpaca_config()
    if cfg is None:
        return None

    interval_map = {
        '1m': '1Min', '5m': '5Min', '10m': '10Min', '15m': '15Min',
        '30m': '30Min', '1h': '1Hour', '1d': '1Day', '1Day': '1Day',
        '1Min': '1Min',
    }
    timeframe = interval_map.get(interval, interval)
    headers = _alpaca_headers(cfg)

    start_rfc = datetime.strptime(start_date, '%Y-%m-%d').strftime('%Y-%m-%dT00:00:00Z')
    end_rfc = (datetime.strptime(end_date, '%Y-%m-%d') + timedelta(days=1)).strftime('%Y-%m-%dT00:00:00Z')

    all_bars = []
    page_token = None
    url = f'{cfg["data_url"]}/v2/stocks/{symbol}/bars'

    retries_429 = 0
    _t0 = _time.monotonic()
    _last_status = 0
    try:
        while True:
            params = {
                'timeframe': timeframe,
                'start': start_rfc,
                'end': end_rfc,
                'limit': 10000,
                'feed': feed,
                'adjustment': 'split',
            }
            if page_token:
                params['page_token'] = page_token

            resp = requests.get(url, headers=headers, params=params, timeout=15)
            _last_status = resp.status_code
            if resp.status_code == 429:
                retries_429 += 1
                if retries_429 > 5:
                    logger.warning(f"Alpaca rate limit exceeded for {symbol} after 5 retries")
                    _log_api_call('/v2/stocks/bars', 'GET', symbol, 429,
                                  (_time.monotonic() - _t0) * 1000, 'rate_limit_exceeded')
                    return None
                _time.sleep(min(2 ** retries_429, 30))
                continue
            retries_429 = 0
            if resp.status_code != 200:
                logger.error(f"Alpaca API returned {resp.status_code}: {resp.text[:200]}")
                _log_api_call('/v2/stocks/bars', 'GET', symbol, resp.status_code,
                              (_time.monotonic() - _t0) * 1000, resp.text[:200])
                return None

            data = resp.json()
            bars = data.get('bars') or []
            all_bars.extend(bars)

            page_token = data.get('next_page_token')
            if not page_token:
                break

        _log_api_call('/v2/stocks/bars', 'GET', symbol, _last_status,
                      (_time.monotonic() - _t0) * 1000)

        if not all_bars:
            return None

        df = pd.DataFrame(all_bars)
        df['datetime'] = pd.to_datetime(df['t'])
        df.rename(columns={'o': 'open', 'h': 'high', 'l': 'low', 'c': 'close', 'v': 'volume'}, inplace=True)
        df = df[['datetime', 'open', 'high', 'low', 'close', 'volume']].dropna()
        for col in ['open', 'high', 'low', 'close', 'volume']:
            df[col] = pd.to_numeric(df[col], errors='coerce').astype(np.float64)
        df.set_index('datetime', inplace=True)
        df.sort_index(inplace=True)
        if df.index.tz is not None:
            df.index = df.index.tz_convert(None)
        df.index.name = symbol
        return df

    except Exception as e:
        logger.error(f"Alpaca data fetch failed for {symbol}: {e}")
        _log_api_call('/v2/stocks/bars', 'GET', symbol, _last_status,
                      (_time.monotonic() - _t0) * 1000, str(e))
        return None


def fetch_alpaca_bars_multi(symbols: List[str], start_date: str, end_date: str,
                            interval: str = '1Day', feed: str = 'sip',
                            batch_size: int = 100) -> Dict[str, pd.DataFrame]:
    """Fetch daily bars for many symbols at once using Alpaca multi-stock bars endpoint.

    Returns {symbol: DataFrame} dict.  Much faster than per-symbol fetching.
    Batches `batch_size` symbols per request (Alpaca limit).
    """
    cfg = _get_alpaca_config()
    if cfg is None:
        return {}

    interval_map = {
        '1m': '1Min', '5m': '5Min', '10m': '10Min', '15m': '15Min',
        '30m': '30Min', '1h': '1Hour', '1d': '1Day', '1Day': '1Day',
    }
    timeframe = interval_map.get(interval, interval)
    headers = _alpaca_headers(cfg)
    start_rfc = datetime.strptime(start_date, '%Y-%m-%d').strftime('%Y-%m-%dT00:00:00Z')
    end_rfc = (datetime.strptime(end_date, '%Y-%m-%d') + timedelta(days=1)).strftime('%Y-%m-%dT00:00:00Z')

    url = f'{cfg["data_url"]}/v2/stocks/bars'
    results: Dict[str, pd.DataFrame] = {}
    total_batches = (len(symbols) + batch_size - 1) // batch_size

    for i in range(0, len(symbols), batch_size):
        batch = symbols[i:i + batch_size]
        batch_num = i // batch_size
        batch_bars: Dict[str, list] = defaultdict(list)

        # Retry loop for timeouts
        for attempt in range(3):
            page_token = None
            if attempt > 0:
                batch_bars.clear()
                _time.sleep(2 ** attempt)

            try:
                while True:
                    params = {
                        'symbols': ','.join(batch),
                        'timeframe': timeframe,
                        'start': start_rfc,
                        'end': end_rfc,
                        'limit': 10000,
                        'feed': feed,
                        'adjustment': 'split',
                    }
                    if page_token:
                        params['page_token'] = page_token

                    resp = requests.get(url, headers=headers, params=params, timeout=45)
                    if resp.status_code == 429:
                        _time.sleep(min(2 ** (attempt + 1), 30))
                        continue
                    if resp.status_code != 200:
                        logger.warning(f"Multi-bar batch {batch_num} failed ({resp.status_code})")
                        break

                    data = resp.json()
                    bars_dict = data.get('bars') or {}
                    for sym, bars in bars_dict.items():
                        batch_bars[sym].extend(bars)

                    page_token = data.get('next_page_token')
                    if not page_token:
                        break

                # If we got data, don't retry
                if batch_bars:
                    break

            except requests.exceptions.Timeout:
                logger.warning(f"Multi-bar batch {batch_num}/{total_batches} timed out (attempt {attempt+1}/3)")
            except Exception as e:
                logger.warning(f"Multi-bar batch {batch_num} error: {e}")
                break  # Don't retry on non-timeout errors

        # Convert each symbol's bars to DataFrame
        for sym, bars in batch_bars.items():
            if not bars:
                continue
            try:
                df = pd.DataFrame(bars)
                df['datetime'] = pd.to_datetime(df['t'])
                df.rename(columns={'o': 'open', 'h': 'high', 'l': 'low',
                                   'c': 'close', 'v': 'volume'}, inplace=True)
                df = df[['datetime', 'open', 'high', 'low', 'close', 'volume']].dropna()
                for col in ['open', 'high', 'low', 'close', 'volume']:
                    df[col] = pd.to_numeric(df[col], errors='coerce').astype(np.float64)
                df.set_index('datetime', inplace=True)
                df.sort_index(inplace=True)
                if df.index.tz is not None:
                    df.index = df.index.tz_convert(None)
                df.index.name = sym
                results[sym] = df
            except Exception:
                pass

        # Rate limit between batches
        if i + batch_size < len(symbols):
            _time.sleep(0.3)

        # Log progress every 20 batches
        if batch_num % 20 == 0 and batch_num > 0:
            logger.info(f"Multi-bar progress: batch {batch_num}/{total_batches}, {len(results)} symbols so far")

    logger.info(f"Multi-bar fetch: {len(results)} symbols with data out of {len(symbols)} requested")
    _log_api_call('/v2/stocks/bars (multi)', 'GET',
                  f'{len(symbols)} symbols', 200, 0)
    return results


def _fetch_bars_multi_parallel(symbols: List[str], start_date: str, end_date: str,
                                interval: str = '1Day', feed: str = 'sip',
                                batch_size: int = 100) -> Dict[str, pd.DataFrame]:
    """Parallel multi-key version of fetch_alpaca_bars_multi.

    Splits symbol batches across available API keys using ThreadPoolExecutor.
    Falls back to single-key fetch_alpaca_bars_multi if only 1 key.
    Safe to call from asyncio.to_thread (scanner already does this).
    """
    pool = _get_key_pool()
    keys = pool.get_all()

    # Single key or no keys: use original function
    if len(keys) <= 1:
        return fetch_alpaca_bars_multi(symbols, start_date, end_date, interval, feed, batch_size)

    # Split symbols into chunks, one per key (round-robin)
    key_batches: Dict[int, List[str]] = defaultdict(list)
    for i, sym in enumerate(symbols):
        slot_idx = i % len(keys)
        key_batches[slot_idx].append(sym)

    results: Dict[str, pd.DataFrame] = {}
    max_workers = min(len(keys) * 2, 8)

    def _fetch_with_key(slot: AlpacaKeySlot, syms: List[str]) -> Dict[str, pd.DataFrame]:
        """Fetch bars using a specific API key slot."""
        cfg = {
            'api_key': slot.api_key,
            'secret_key': slot.secret_key,
            'data_url': 'https://data.alpaca.markets',
        }
        interval_map = {
            '1m': '1Min', '5m': '5Min', '10m': '10Min', '15m': '15Min',
            '30m': '30Min', '1h': '1Hour', '1d': '1Day', '1Day': '1Day',
        }
        timeframe = interval_map.get(interval, interval)
        headers = slot.headers()
        start_rfc = datetime.strptime(start_date, '%Y-%m-%d').strftime('%Y-%m-%dT00:00:00Z')
        end_rfc = (datetime.strptime(end_date, '%Y-%m-%d') + timedelta(days=1)).strftime('%Y-%m-%dT00:00:00Z')
        url = f'{cfg["data_url"]}/v2/stocks/bars'
        local_results: Dict[str, pd.DataFrame] = {}

        for bi in range(0, len(syms), batch_size):
            batch = syms[bi:bi + batch_size]
            slot.record_use()
            batch_bars: Dict[str, list] = defaultdict(list)

            try:
                page_token = None
                while True:
                    params = {
                        'symbols': ','.join(batch),
                        'timeframe': timeframe,
                        'start': start_rfc,
                        'end': end_rfc,
                        'limit': 10000,
                        'feed': feed,
                        'adjustment': 'split',
                    }
                    if page_token:
                        params['page_token'] = page_token

                    resp = requests.get(url, headers=headers, params=params, timeout=45)
                    if resp.status_code == 429:
                        _time.sleep(2)
                        continue
                    if resp.status_code != 200:
                        break

                    data = resp.json()
                    for sym, bars in (data.get('bars') or {}).items():
                        batch_bars[sym].extend(bars)

                    page_token = data.get('next_page_token')
                    if not page_token:
                        break

            except Exception as e:
                logger.warning(f"Parallel fetch (key {slot.slot_id}) batch error: {e}")

            # Convert to DataFrames
            for sym, bars in batch_bars.items():
                if not bars:
                    continue
                try:
                    df = pd.DataFrame(bars)
                    df['datetime'] = pd.to_datetime(df['t'])
                    df.rename(columns={'o': 'open', 'h': 'high', 'l': 'low',
                                       'c': 'close', 'v': 'volume'}, inplace=True)
                    df = df[['datetime', 'open', 'high', 'low', 'close', 'volume']].dropna()
                    for col in ['open', 'high', 'low', 'close', 'volume']:
                        df[col] = pd.to_numeric(df[col], errors='coerce').astype(np.float64)
                    df.set_index('datetime', inplace=True)
                    df.sort_index(inplace=True)
                    if df.index.tz is not None:
                        df.index = df.index.tz_convert(None)
                    df.index.name = sym
                    local_results[sym] = df
                except Exception:
                    pass

            # Rate limit between batches
            if bi + batch_size < len(syms):
                _time.sleep(0.2)

        return local_results

    logger.info(f"Parallel bars fetch: {len(symbols)} symbols across {len(keys)} keys "
                f"({max_workers} workers)")

    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {}
        for slot_idx, syms in key_batches.items():
            if syms:
                f = executor.submit(_fetch_with_key, keys[slot_idx], syms)
                futures[f] = slot_idx

        for future in as_completed(futures):
            try:
                results.update(future.result())
            except Exception as e:
                logger.warning(f"Parallel fetch thread error: {e}")

    logger.info(f"Parallel bars fetch complete: {len(results)}/{len(symbols)} symbols")
    return results


def fetch_alpaca_snapshots(symbols: List[str]) -> dict:
    """Batch fetch latest quotes/trades via Alpaca snapshots endpoint.
    Returns {symbol: {latestTrade: {p, s, t}, dailyBar: {o,h,l,c,v}, prevDailyBar: {o,h,l,c,v}}}
    """
    cfg = _get_alpaca_config()
    if cfg is None:
        return {}

    headers = _alpaca_headers(cfg)
    results = {}

    # Batch 1500 symbols per request (Alpaca supports ~2000 per URL)
    batch_size = 1500
    for i in range(0, len(symbols), batch_size):
        batch = symbols[i:i+batch_size]
        params = {
            'symbols': ','.join(batch),
            'feed': 'sip',
        }
        _t0 = _time.monotonic()
        try:
            resp = requests.get(
                f'{cfg["data_url"]}/v2/stocks/snapshots',
                headers=headers, params=params, timeout=15
            )
            _log_api_call('/v2/stocks/snapshots', 'GET', f'{len(batch)} symbols',
                          resp.status_code, (_time.monotonic() - _t0) * 1000)
            if resp.status_code == 200:
                results.update(resp.json())
            else:
                logger.warning(f"Snapshot batch failed ({resp.status_code}): {resp.text[:200]}")
        except Exception as e:
            logger.warning(f"Snapshot fetch error: {e}")
            _log_api_call('/v2/stocks/snapshots', 'GET', f'{len(batch)} symbols',
                          0, (_time.monotonic() - _t0) * 1000, str(e))

        if i + batch_size < len(symbols):
            _time.sleep(0.1)

    return results


# --- Alpaca Screener: Most Active & Top Movers ---

_movers_cache: Dict[str, Any] = {
    'symbols': [],
    'timestamp': 0.0,
}


def fetch_alpaca_movers(top_n: int = 20) -> List[str]:
    """Fetch today's most active stocks + top movers via Alpaca screener API.

    Combines most-actives (by volume) and top movers (gainers + losers)
    into a deduplicated list. Cached for 5 minutes.
    Returns list of symbols.
    """
    now = _time.time()
    if _movers_cache['symbols'] and (now - _movers_cache['timestamp']) < 300:
        return _movers_cache['symbols']

    cfg = _get_alpaca_config()
    if cfg is None:
        return []

    headers = _alpaca_headers(cfg)
    data_url = cfg['data_url']
    symbols = []

    # 1) Most active by volume
    _t0 = _time.monotonic()
    try:
        resp = requests.get(
            f'{data_url}/v1beta1/screener/stocks/most-actives',
            headers=headers,
            params={'by': 'volume', 'top': top_n},
            timeout=10
        )
        _log_api_call('/v1beta1/screener/stocks/most-actives', 'GET', '',
                      resp.status_code, (_time.monotonic() - _t0) * 1000)
        if resp.status_code == 200:
            data = resp.json()
            for item in data.get('most_actives', []):
                sym = item.get('symbol', '')
                if sym:
                    symbols.append(sym)
        else:
            logger.warning(f"Alpaca most-actives returned {resp.status_code}: {resp.text[:200]}")
    except Exception as e:
        logger.warning(f"Alpaca most-actives fetch error: {e}")
        _log_api_call('/v1beta1/screener/stocks/most-actives', 'GET', '',
                      0, (_time.monotonic() - _t0) * 1000, str(e))

    # 2) Top movers (gainers + losers)
    _t0 = _time.monotonic()
    try:
        resp = requests.get(
            f'{data_url}/v1beta1/screener/stocks/movers',
            headers=headers,
            params={'top': top_n},
            timeout=10
        )
        _log_api_call('/v1beta1/screener/stocks/movers', 'GET', '',
                      resp.status_code, (_time.monotonic() - _t0) * 1000)
        if resp.status_code == 200:
            data = resp.json()
            for item in data.get('gainers', []):
                sym = item.get('symbol', '')
                if sym:
                    symbols.append(sym)
            for item in data.get('losers', []):
                sym = item.get('symbol', '')
                if sym:
                    symbols.append(sym)
        else:
            logger.warning(f"Alpaca movers returned {resp.status_code}: {resp.text[:200]}")
    except Exception as e:
        logger.warning(f"Alpaca movers fetch error: {e}")
        _log_api_call('/v1beta1/screener/stocks/movers', 'GET', '',
                      0, (_time.monotonic() - _t0) * 1000, str(e))

    # Deduplicate, filter bad symbols and penny stocks
    seen = set()
    clean = []
    for s in symbols:
        if s not in seen and '/' not in s and '.' not in s and len(s) <= 5:
            seen.add(s)
            clean.append(s)

    # Filter out penny stocks (price < $5) using snapshot API
    if clean:
        try:
            snap_url = f'{data_url}/v2/stocks/snapshots'
            resp = requests.get(snap_url, headers=headers,
                                params={'symbols': ','.join(clean), 'feed': 'sip'},
                                timeout=10)
            if resp.status_code == 200:
                snaps = resp.json()
                filtered = []
                for s in clean:
                    snap = snaps.get(s, {})
                    price = snap.get('latestTrade', {}).get('p', 0) or \
                            snap.get('minuteBar', {}).get('c', 0) or \
                            snap.get('dailyBar', {}).get('c', 0)
                    if price >= 5.0:
                        filtered.append(s)
                _removed = len(clean) - len(filtered)
                if _removed:
                    logger.info(f"Alpaca movers: filtered {_removed} penny stocks (price < $5)")
                clean = filtered
        except Exception as e:
            logger.warning(f"Alpaca movers price filter failed (keeping all): {e}")

    _movers_cache['symbols'] = clean
    _movers_cache['timestamp'] = now
    logger.info(f"Alpaca screener: fetched {len(clean)} unique movers/most-active symbols")
    return clean


# Module-level cache for Alpaca assets list (includes shortability data)
_assets_cache: Dict[str, Any] = {
    'symbols': [],
    'shortable': {},    # {symbol: (shortable, easy_to_borrow)}
    'timestamp': 0.0,
}


def fetch_alpaca_assets(min_price: float = 1.0,
                        asset_class: str = 'us_equity') -> List[str]:
    """Fetch all active, tradeable symbols from Alpaca.

    Filters: active, tradeable, major exchanges (NYSE, NASDAQ, ARCA, AMEX, BATS).
    Cached for 24 hours. Also caches shortable/easy_to_borrow per symbol.
    """
    now = _time.time()
    if _assets_cache['symbols'] and (now - _assets_cache['timestamp']) < 86400:
        return _assets_cache['symbols']

    cfg = _get_alpaca_config()
    if cfg is None:
        logger.warning("fetch_alpaca_assets: Alpaca not configured")
        return []

    headers = _alpaca_headers(cfg)
    valid_exchanges = {'NYSE', 'NASDAQ', 'ARCA', 'AMEX', 'BATS', 'NYSEARCA'}

    _t0 = _time.monotonic()
    try:
        resp = requests.get(
            'https://api.alpaca.markets/v2/assets',
            headers=headers,
            params={'status': 'active', 'asset_class': asset_class},
            timeout=60
        )
        _log_api_call('/v2/assets', 'GET', '', resp.status_code,
                      (_time.monotonic() - _t0) * 1000)
        if resp.status_code != 200:
            logger.error(f"Alpaca assets API returned {resp.status_code}: {resp.text[:200]}")
            return []

        assets = resp.json()
        symbols = []
        shortable_map = {}
        for a in assets:
            if not a.get('tradable', False):
                continue
            if a.get('status') != 'active':
                continue
            exchange = a.get('exchange', '')
            if exchange not in valid_exchanges:
                continue
            sym = a.get('symbol', '')
            # Skip symbols with special characters (warrants, units, etc.)
            if not sym or '/' in sym or '.' in sym or '-' in sym or len(sym) > 5:
                continue
            symbols.append(sym)
            shortable_map[sym] = (
                bool(a.get('shortable', False)),
                bool(a.get('easy_to_borrow', False)),
            )

        symbols = sorted(set(symbols))
        _assets_cache['symbols'] = symbols
        _assets_cache['shortable'] = shortable_map
        _assets_cache['timestamp'] = now
        logger.info(f"Fetched {len(symbols)} tradeable assets from Alpaca "
                    f"({sum(1 for v in shortable_map.values() if v[0])} shortable)")
        return symbols

    except Exception as e:
        logger.error(f"fetch_alpaca_assets failed: {e}")
        _log_api_call('/v2/assets', 'GET', '', 0,
                      (_time.monotonic() - _t0) * 1000, str(e))
        return []


def alpaca_check_shortable(symbol: str) -> Tuple[bool, bool]:
    """Check if symbol is shortable on Alpaca. Returns (shortable, easy_to_borrow).
    Uses cached data from fetch_alpaca_assets() if available, else falls back to API.
    """
    # Try cache first (zero API calls)
    cached = _assets_cache.get('shortable', {}).get(symbol)
    if cached is not None:
        return cached

    cfg = _get_alpaca_config()
    if cfg is None:
        return False, False

    headers = {**_alpaca_headers(cfg), 'Content-Type': 'application/json'}
    try:
        resp = requests.get(
            f'https://api.alpaca.markets/v2/assets/{symbol}',
            headers=headers, timeout=10
        )
        if resp.status_code == 200:
            data = resp.json()
            result = (data.get('shortable', False), data.get('easy_to_borrow', False))
            # Cache for future use
            _assets_cache.setdefault('shortable', {})[symbol] = result
            return result
    except Exception as e:
        logger.warning(f"Shortable check failed for {symbol}: {e}")
    return False, False


def alpaca_check_shortable_batch(symbols: List[str]) -> Dict[str, Tuple[bool, bool]]:
    """Batch shortability lookup — pure cache, zero API calls.
    Returns {symbol: (shortable, easy_to_borrow)} for all symbols.
    Falls back to (False, False) for symbols not in cache.
    """
    shortable_map = _assets_cache.get('shortable', {})
    return {sym: shortable_map.get(sym, (False, False)) for sym in symbols}


@dataclass
class OrderResult:
    """Structured result from order submission + fill verification."""
    order_id: str = ''
    status: str = ''               # 'filled', 'partially_filled', 'pending', 'rejected', 'cancelled', 'error', 'timeout'
    filled_qty: int = 0
    filled_avg_price: float = 0.0
    symbol: str = ''
    side: str = ''
    error: str = ''

    @property
    def is_filled(self) -> bool:
        return self.status == 'filled'

    @property
    def is_error(self) -> bool:
        return self.status in ('error', 'rejected', 'cancelled', 'timeout')


def alpaca_place_order(symbol: str, qty: int, side: str, order_type: str = 'market',
                       limit_price: float = None, stop_price: float = None,
                       time_in_force: str = 'day') -> dict:
    """Place an order on Alpaca paper account (sync, for backward compat).
    side: 'sell' for short entry, 'buy' for cover (buy-to-cover).
    """
    cfg = _get_alpaca_config()
    if cfg is None:
        return {'error': 'Alpaca not configured'}

    headers = {**_alpaca_trade_headers(cfg), 'Content-Type': 'application/json'}
    payload = {
        'symbol': symbol,
        'qty': str(qty),
        'side': side,
        'type': order_type,
        'time_in_force': time_in_force,
    }
    if limit_price is not None:
        payload['limit_price'] = str(round(limit_price, 2))
    if stop_price is not None:
        payload['stop_price'] = str(round(stop_price, 2))

    _t0 = _time.monotonic()
    try:
        resp = requests.post(
            f'{cfg["base_url"]}/v2/orders',
            headers=headers, json=payload, timeout=10
        )
        _log_api_call('/v2/orders', 'POST', symbol, resp.status_code,
                      (_time.monotonic() - _t0) * 1000)
        if resp.status_code in (200, 201):
            data = resp.json()
            logger.info(f"Alpaca order placed: {side} {qty} {symbol} -> {data.get('id', '?')}")
            return {'id': data.get('id'), 'status': data.get('status'),
                    'symbol': symbol, 'qty': qty, 'side': side}
        else:
            err = resp.text[:200]
            logger.warning(f"Alpaca order failed ({resp.status_code}): {err}")
            return {'error': f"HTTP {resp.status_code}: {err}"}
    except Exception as e:
        logger.warning(f"Alpaca order error: {e}")
        _log_api_call('/v2/orders', 'POST', symbol, 0,
                      (_time.monotonic() - _t0) * 1000, str(e))
        return {'error': str(e)}


def alpaca_get_order(order_id: str) -> Optional[dict]:
    """Get order status from Alpaca by order ID."""
    cfg = _get_alpaca_config()
    if cfg is None:
        return None
    try:
        resp = requests.get(
            f'{cfg["base_url"]}/v2/orders/{order_id}',
            headers=_alpaca_trade_headers(cfg), timeout=10
        )
        if resp.status_code == 200:
            return resp.json()
        logger.warning(f"Get order {order_id} failed: HTTP {resp.status_code}")
    except Exception as e:
        logger.warning(f"Get order {order_id} error: {e}")
    return None


def alpaca_cancel_open_orders_for_symbol(symbol: str) -> int:
    """Cancel all open orders for a specific symbol. Returns count of orders cancelled."""
    cfg = _get_alpaca_config()
    if cfg is None:
        return 0
    _t0 = _time.monotonic()
    try:
        resp = requests.get(
            f'{cfg["base_url"]}/v2/orders',
            headers=_alpaca_trade_headers(cfg),
            params={'status': 'open', 'symbols': symbol, 'limit': 50},
            timeout=10,
        )
        if resp.status_code != 200:
            _log_api_call('/v2/orders (cancel-list)', 'GET', symbol, resp.status_code,
                          (_time.monotonic() - _t0) * 1000)
            return 0
        orders = resp.json()
        cancelled = 0
        for order in orders:
            oid = order.get('id', '')
            if oid:
                try:
                    r = requests.delete(
                        f'{cfg["base_url"]}/v2/orders/{oid}',
                        headers=_alpaca_trade_headers(cfg), timeout=10,
                    )
                    if r.status_code in (200, 204):
                        cancelled += 1
                except Exception:
                    pass
        _log_api_call('/v2/orders (cancel-batch)', 'DELETE', symbol, 200,
                      (_time.monotonic() - _t0) * 1000)
        return cancelled
    except Exception as e:
        logger.warning(f"Cancel open orders for {symbol} error: {e}")
        _log_api_call('/v2/orders (cancel-batch)', 'DELETE', symbol, 0,
                      (_time.monotonic() - _t0) * 1000, str(e))
        return 0


def alpaca_get_filled_orders(symbol: str, after: str, limit: int = 10) -> List[dict]:
    """Get recent filled orders for a symbol from Alpaca.

    Used by reconciliation to reconstruct entry context for adopted positions.
    Returns list of order dicts sorted by filled_at descending.
    """
    cfg = _get_alpaca_config()
    if cfg is None:
        return []
    headers = _alpaca_trade_headers(cfg)
    try:
        resp = requests.get(
            f'{cfg["base_url"]}/v2/orders',
            headers=headers,
            params={
                'status': 'filled',
                'symbols': symbol,
                'after': after,
                'limit': str(limit),
                'direction': 'desc',
            },
            timeout=10,
        )
        if resp.status_code == 200:
            return resp.json()
        logger.warning(f"alpaca_get_filled_orders({symbol}): {resp.status_code}")
    except Exception as e:
        logger.warning(f"alpaca_get_filled_orders({symbol}) error: {e}")
    return []


def alpaca_close_position_api(symbol: str) -> dict:
    """Close a position using Alpaca's DELETE /v2/positions/{symbol} endpoint.

    This is a last-resort method that tells Alpaca to liquidate the position
    directly, bypassing order submission. Works even when shares are held for orders.
    """
    cfg = _get_alpaca_config()
    if cfg is None:
        return {'error': 'no config'}
    _t0 = _time.monotonic()
    try:
        resp = requests.delete(
            f'{cfg["base_url"]}/v2/positions/{symbol}',
            headers=_alpaca_trade_headers(cfg), timeout=15,
        )
        _log_api_call('/v2/positions (close)', 'DELETE', symbol, resp.status_code,
                      (_time.monotonic() - _t0) * 1000)
        if resp.status_code in (200, 204):
            data = resp.json() if resp.text else {}
            logger.info(f"Alpaca close position API: {symbol} -> {resp.status_code}")
            return data
        return {'error': f'HTTP {resp.status_code}: {resp.text[:200]}'}
    except Exception as e:
        logger.warning(f"Alpaca close position API {symbol} error: {e}")
        _log_api_call('/v2/positions (close)', 'DELETE', symbol, 0,
                      (_time.monotonic() - _t0) * 1000, str(e))
        return {'error': str(e)}


def _alpaca_open_order_count(symbol: str) -> int:
    """Check how many open orders exist for a symbol on Alpaca."""
    cfg = _get_alpaca_config()
    if cfg is None:
        return 0
    _t0 = _time.monotonic()
    try:
        resp = requests.get(
            f'{cfg["base_url"]}/v2/orders',
            headers=_alpaca_trade_headers(cfg),
            params={'status': 'open', 'symbols': symbol, 'limit': 50},
            timeout=10,
        )
        _log_api_call('/v2/orders (count)', 'GET', symbol, resp.status_code,
                      (_time.monotonic() - _t0) * 1000)
        if resp.status_code == 200:
            return len(resp.json())
    except Exception:
        pass
    return 0


def alpaca_cancel_order(order_id: str) -> bool:
    """Cancel an open order on Alpaca. Returns True if successfully cancelled."""
    cfg = _get_alpaca_config()
    if cfg is None:
        return False
    _t0 = _time.monotonic()
    try:
        resp = requests.delete(
            f'{cfg["base_url"]}/v2/orders/{order_id}',
            headers=_alpaca_trade_headers(cfg), timeout=10
        )
        _log_api_call('/v2/orders (cancel)', 'DELETE', order_id, resp.status_code,
                      (_time.monotonic() - _t0) * 1000)
        return resp.status_code in (200, 204)
    except Exception as e:
        logger.warning(f"Cancel order {order_id} error: {e}")
        return False


async def alpaca_submit_and_confirm(
    symbol: str, qty: int, side: str,
    order_type: str = 'market', limit_price: float = None,
    timeout_sec: float = 30.0, poll_interval: float = 0.5,
    cancel_on_timeout: bool = False,
) -> OrderResult:
    """Submit order and poll until filled, rejected, or timeout.

    For limit orders: polls until filled or timeout. By default does NOT
    cancel on timeout — the order stays open on the broker and may fill later.
    The caller should track the order_id for later reconciliation.

    For market orders: polls until filled or timeout. Market orders that don't
    fill within the timeout are cancelled (something is wrong).

    Set cancel_on_timeout=True to force cancellation on timeout (used for
    exit orders where we need certainty).
    """
    result = OrderResult(symbol=symbol, side=side)

    # Submit order (runs sync HTTP in thread to not block event loop)
    order_resp = await asyncio.to_thread(
        alpaca_place_order, symbol, qty, side, order_type, limit_price
    )
    if 'error' in order_resp:
        result.status = 'error'
        result.error = order_resp['error']
        logger.error(f"Order submit failed: {side} {qty} {symbol}: {result.error}")
        return result

    order_id = order_resp.get('id', '')
    result.order_id = order_id
    logger.info(f"Order submitted: {side} {qty} {symbol} ({order_type}) "
                f"id={order_id}" +
                (f" limit=${limit_price:.2f}" if limit_price else ""))

    # Poll for fill
    deadline = _time.monotonic() + timeout_sec
    while _time.monotonic() < deadline:
        await asyncio.sleep(poll_interval)
        order_data = await asyncio.to_thread(alpaca_get_order, order_id)
        if order_data is None:
            continue

        status = order_data.get('status', '')

        if status == 'filled':
            result.status = 'filled'
            result.filled_qty = int(order_data.get('filled_qty', qty))
            result.filled_avg_price = float(order_data.get('filled_avg_price', 0))
            logger.info(f"Order FILLED: {side} {result.filled_qty} {symbol} "
                       f"@ ${result.filled_avg_price:.2f} (id={order_id})")
            return result

        if status in ('cancelled', 'canceled', 'expired', 'suspended'):
            result.status = 'cancelled'
            result.error = f"Order {status} (by broker, not by us)"
            logger.warning(f"Order {status}: {side} {qty} {symbol} (id={order_id})")
            return result

        if status == 'rejected':
            result.status = 'rejected'
            result.error = f"Rejected: {order_data.get('reject_reason', 'unknown')}"
            logger.warning(f"Order REJECTED: {side} {qty} {symbol}: {result.error}")
            return result

        if status == 'partially_filled':
            result.filled_qty = int(order_data.get('filled_qty', 0))
            result.filled_avg_price = float(order_data.get('filled_avg_price', 0))
            # Keep polling — may fully fill

    # ── Timeout reached ──
    # One final check in case it filled during the last sleep
    order_data = await asyncio.to_thread(alpaca_get_order, order_id)
    if order_data and order_data.get('status') == 'filled':
        result.status = 'filled'
        result.filled_qty = int(order_data.get('filled_qty', qty))
        result.filled_avg_price = float(order_data.get('filled_avg_price', 0))
        logger.info(f"Order FILLED (on final check): {side} {result.filled_qty} {symbol} "
                   f"@ ${result.filled_avg_price:.2f}")
        return result

    filled_qty = int(order_data.get('filled_qty', 0)) if order_data else 0

    # Decide whether to cancel or hold
    should_cancel = cancel_on_timeout or order_type == 'market'

    if should_cancel:
        logger.warning(f"Order TIMEOUT after {timeout_sec}s, CANCELLING: "
                      f"{side} {qty} {symbol} ({order_type}) id={order_id}")
        await asyncio.to_thread(alpaca_cancel_order, order_id)
        if filled_qty > 0:
            result.status = 'partially_filled'
            result.filled_qty = filled_qty
            result.filled_avg_price = float(order_data.get('filled_avg_price', 0))
            result.error = f"Partial fill: {filled_qty}/{qty} shares, rest cancelled"
        else:
            result.status = 'timeout'
            result.error = f"No fill after {timeout_sec}s, order cancelled"
    else:
        # Limit order: DON'T cancel — let it work on the broker
        logger.info(f"Order still PENDING after {timeout_sec}s, HOLDING: "
                    f"{side} {qty} {symbol} limit=${limit_price} id={order_id} "
                    f"(order stays open on broker)")
        if filled_qty > 0:
            result.status = 'partially_filled'
            result.filled_qty = filled_qty
            result.filled_avg_price = float(order_data.get('filled_avg_price', 0))
            result.error = f"Partial fill: {filled_qty}/{qty} shares, order still open"
        else:
            result.status = 'pending'
            result.error = f"Still pending after {timeout_sec}s, order held open"

    return result


def alpaca_get_positions() -> List[dict]:
    """Get current positions on Alpaca paper account."""
    cfg = _get_alpaca_config()
    if cfg is None:
        return []

    headers = _alpaca_trade_headers(cfg)
    _t0 = _time.monotonic()
    try:
        resp = requests.get(
            f'{cfg["base_url"]}/v2/positions',
            headers=headers, timeout=10
        )
        _log_api_call('/v2/positions', 'GET', '', resp.status_code,
                      (_time.monotonic() - _t0) * 1000)
        if resp.status_code == 200:
            return resp.json()
    except Exception as e:
        logger.warning(f"Get positions error: {e}")
    return []


def alpaca_place_stop_order(symbol: str, qty: int, stop_price: float,
                            limit_offset_pct: float = 0.003,
                            direction: str = 'short') -> dict:
    """Place a broker-side stop-limit order.

    For shorts: buy-to-cover stop (side='buy', limit above stop).
    For longs: sell stop (side='sell', limit below stop).

    Alpaca holds this order server-side and triggers it the instant price
    hits the stop — no polling delay.

    Returns {'id': order_id, ...} or {'error': ...}.
    """
    cfg = _get_alpaca_config()
    if cfg is None:
        return {'error': 'Alpaca not configured'}

    if direction == 'long':
        side = 'sell'
        limit_price = round(stop_price * (1 - limit_offset_pct), 2)
    else:
        side = 'buy'
        limit_price = round(stop_price * (1 + limit_offset_pct), 2)
    headers = {**_alpaca_trade_headers(cfg), 'Content-Type': 'application/json'}
    payload = {
        'symbol': symbol,
        'qty': str(qty),
        'side': side,
        'type': 'stop_limit',
        'stop_price': str(round(stop_price, 2)),
        'limit_price': str(limit_price),
        'time_in_force': 'gtc',
    }

    _t0 = _time.monotonic()
    try:
        resp = requests.post(
            f'{cfg["base_url"]}/v2/orders',
            headers=headers, json=payload, timeout=10
        )
        _log_api_call('/v2/orders (stop)', 'POST', symbol, resp.status_code,
                      (_time.monotonic() - _t0) * 1000)
        if resp.status_code in (200, 201):
            data = resp.json()
            logger.info(f"Broker stop placed: {side.upper()} {qty} {symbol} stop=${stop_price:.2f} "
                       f"limit=${limit_price:.2f} -> id={data.get('id', '?')}")
            return {'id': data.get('id'), 'status': data.get('status'),
                    'symbol': symbol, 'stop_price': stop_price, 'limit_price': limit_price}
        else:
            err = resp.text[:200]
            logger.warning(f"Broker stop failed ({resp.status_code}): {err}")
            return {'error': f"HTTP {resp.status_code}: {err}"}
    except Exception as e:
        logger.warning(f"Broker stop error: {e}")
        _log_api_call('/v2/orders (stop)', 'POST', symbol, 0,
                      (_time.monotonic() - _t0) * 1000, str(e))
        return {'error': str(e)}


async def alpaca_replace_stop_order(old_order_id: str, symbol: str, qty: int,
                                     new_stop_price: float,
                                     limit_offset_pct: float = 0.003) -> dict:
    """Cancel old stop order and place a new one at a different price.

    Used when stop moves to breakeven after partial fill.
    Returns the new order result dict.
    """
    # Cancel old
    if old_order_id:
        await asyncio.to_thread(alpaca_cancel_order, old_order_id)

    # Place new
    result = await asyncio.to_thread(
        alpaca_place_stop_order, symbol, qty, new_stop_price, limit_offset_pct
    )
    return result


