class AlpacaTickStreamer:
    """Real-time trade stream via Alpaca WebSocket."""

    WS_URL = 'wss://stream.data.alpaca.markets/v2/sip'
    THROTTLE_SEC = 0.25

    def __init__(self, symbols, on_tick=None):
        if isinstance(symbols, str):
            symbols = [symbols]
        self.symbols = list(symbols)
        self.on_tick = on_tick
        self.latest_prices: Dict[str, float] = {}
        self.connected = False
        self._task: Optional[asyncio.Task] = None
        self._session: Optional[aiohttp.ClientSession] = None
        self._last_push: Dict[str, float] = {}
        self._ws = None  # reference to live websocket for dynamic subscriptions

    _MAX_SYMBOLS = 25  # Alpaca free tier WebSocket limit

    async def add_symbols(self, symbols: List[str],
                          priority_symbols: Optional[set] = None):
        """Dynamically subscribe to additional symbols on the live connection.

        If at the 25-symbol limit, non-priority symbols are removed to make room.
        priority_symbols: set of symbols that must not be evicted (e.g. open positions).
        """
        new_syms = [s for s in symbols if s not in self.symbols]
        if not new_syms:
            return

        # Evict non-priority symbols if at the limit
        if len(self.symbols) + len(new_syms) > self._MAX_SYMBOLS and priority_symbols:
            needed = len(self.symbols) + len(new_syms) - self._MAX_SYMBOLS
            evict = [s for s in self.symbols if s not in priority_symbols and s != 'SPY']
            evict = evict[-needed:]  # evict from the end (lowest priority)
            if evict:
                await self.remove_symbols(evict)
                logger.info(f"Alpaca stream: evicted {evict} to make room for {new_syms}")

        # Respect limit — only subscribe what fits
        room = max(0, self._MAX_SYMBOLS - len(self.symbols))
        if room == 0:
            logger.warning(f"Alpaca stream: at {self._MAX_SYMBOLS} symbol limit, "
                           f"cannot add {new_syms}")
            return
        new_syms = new_syms[:room]

        self.symbols.extend(new_syms)
        if self._ws and not self._ws.closed:
            await self._ws.send_json({'action': 'subscribe', 'trades': new_syms})
            logger.info(f"Alpaca stream: subscribed to {new_syms} "
                        f"({len(self.symbols)}/{self._MAX_SYMBOLS})")

    async def remove_symbols(self, symbols: List[str]):
        """Dynamically unsubscribe from symbols on the live connection."""
        rm_syms = [s for s in symbols if s in self.symbols]
        if not rm_syms:
            return
        self.symbols = [s for s in self.symbols if s not in rm_syms]
        if self._ws and not self._ws.closed:
            await self._ws.send_json({'action': 'unsubscribe', 'trades': rm_syms})
            logger.info(f"Alpaca stream: dynamically unsubscribed from {rm_syms}")

    async def start(self):
        cfg = _get_alpaca_config()
        if cfg is None:
            logger.warning("AlpacaTickStreamer: no Alpaca credentials")
            return
        self._task = asyncio.create_task(self._run(cfg))

    async def stop(self):
        if self._task and not self._task.done():
            self._task.cancel()
            try:
                await self._task
            except asyncio.CancelledError:
                pass
        if self._session and not self._session.closed:
            await self._session.close()
        self._ws = None
        self.connected = False

    async def _run(self, cfg: dict):
        while True:
            try:
                self._session = aiohttp.ClientSession()
                async with self._session.ws_connect(self.WS_URL) as ws:
                    self._ws = ws
                    await ws.receive_json()
                    await ws.send_json({
                        'action': 'auth',
                        'key': cfg['api_key'],
                        'secret': cfg['secret_key'],
                    })
                    auth_resp = await ws.receive_json()
                    if not any(m.get('msg') == 'authenticated' for m in auth_resp):
                        is_limit = any(m.get('code') == 406 for m in auth_resp)
                        wait = 60 if is_limit else 5
                        logger.error(f"Alpaca stream auth failed: {auth_resp} — retry in {wait}s")
                        self._ws = None
                        await self._session.close()
                        await asyncio.sleep(wait)
                        continue

                    # Subscribe in batches (Alpaca free tier limits ~30 symbols)
                    _sub_batch = 25
                    _sub_ok = 0
                    for _si in range(0, len(self.symbols), _sub_batch):
                        _batch = self.symbols[_si:_si + _sub_batch]
                        await ws.send_json({
                            'action': 'subscribe',
                            'trades': _batch,
                        })
                        sub_resp = await ws.receive_json()
                        _has_err = any(m.get('T') == 'error' for m in sub_resp)
                        if _has_err:
                            logger.warning(f"Alpaca stream: subscribe batch {_si//25} "
                                           f"error: {sub_resp}")
                            break
                        _sub_ok += len(_batch)
                    logger.info(f"Alpaca stream: subscribed to {_sub_ok}/{len(self.symbols)} symbols")
                    self.connected = True
                    _tick_count = 0
                    _last_tick_log = _time.monotonic()

                    async for msg in ws:
                        if msg.type == aiohttp.WSMsgType.TEXT:
                            for item in json.loads(msg.data):
                                if item.get('T') == 't':
                                    _tick_count += 1
                                    sym = item.get('S', '')
                                    price = float(item['p'])
                                    size = int(item.get('s', 0))
                                    self.latest_prices[sym] = price
                                    if self.on_tick:
                                        now = _time.monotonic()
                                        last = self._last_push.get(sym, 0.0)
                                        if now - last >= self.THROTTLE_SEC:
                                            self._last_push[sym] = now
                                            await self.on_tick(sym, price, size)
                        elif msg.type in (aiohttp.WSMsgType.CLOSED, aiohttp.WSMsgType.ERROR):
                            break
                        # Periodic health log — detect silent connection death
                        now_mono = _time.monotonic()
                        if now_mono - _last_tick_log >= 60:
                            if _tick_count == 0:
                                logger.warning(
                                    f"Alpaca stream: 0 ticks in last 60s "
                                    f"({len(self.symbols)} symbols subscribed, "
                                    f"{len(self.latest_prices)} with prices). "
                                    f"Check: only 1 IEX stream allowed per API key.")
                            else:
                                logger.info(f"Alpaca stream: {_tick_count} ticks in last 60s, "
                                            f"{len(self.latest_prices)} symbols with prices")
                            _tick_count = 0
                            _last_tick_log = now_mono

            except asyncio.CancelledError:
                raise
            except Exception as e:
                logger.warning(f"Alpaca stream error: {e}, reconnecting in 3s...")
            finally:
                self.connected = False
                self._ws = None
                if self._session and not self._session.closed:
                    await self._session.close()
            await asyncio.sleep(3)


