class AlertNotifier:
    """Lightweight Telegram alerter for trading events."""

    def __init__(self, config: GapFadeConfig):
        self.enabled = config.alert_telegram_enabled
        self.token = config.alert_telegram_token or os.environ.get('TELEGRAM_BOT_TOKEN', '')
        self.chat_id = config.alert_telegram_chat_id or os.environ.get('TELEGRAM_CHAT_ID', '')
        self._throttle: Dict[str, float] = {}
        self._THROTTLE_SECONDS = 60

    async def send(self, title: str, message: str, level: str = 'info', throttle_key: str = ''):
        """Send a Telegram alert. Levels: info, trade, warning, error, summary."""
        if not self.enabled or not self.token or not self.chat_id:
            return
        if throttle_key:
            last = self._throttle.get(throttle_key, 0)
            if _time.time() - last < self._THROTTLE_SECONDS:
                return
            self._throttle[throttle_key] = _time.time()
        emoji = {'info': '\u2139\ufe0f', 'trade': '\U0001f4b0', 'warning': '\u26a0\ufe0f',
                 'error': '\U0001f6a8', 'summary': '\U0001f4ca'}.get(level, '')
        text = f"<b>{emoji} {title}</b>\n{message}"
        try:
            async with aiohttp.ClientSession() as session:
                await session.post(
                    f'https://api.telegram.org/bot{self.token}/sendMessage',
                    json={'chat_id': self.chat_id, 'text': text, 'parse_mode': 'HTML'},
                    timeout=aiohttp.ClientTimeout(total=5))
        except Exception as e:
            logger.warning(f"Telegram alert failed: {e}")


def _build_execution_broker(config: GapFadeConfig):
    """Factory: return execution broker based on config.execution_broker."""
    broker_type = config.execution_broker.lower()
    if broker_type == 'ibkr':
        try:
            from brokers.ibkr_adapter import IBKRBrokerAdapter
            adapter = IBKRBrokerAdapter()
            if adapter.is_configured():
                logger.info("Execution broker: IBKR (IB Gateway)")
                return adapter
            logger.warning("IBKR requested but not configured — falling back to Alpaca")
        except ImportError:
            logger.warning("ib_insync not installed — falling back to Alpaca")
    # Default: Alpaca (uses existing module-level functions)
    logger.info("Execution broker: Alpaca")
    return None  # None = use legacy Alpaca functions directly


class GapFadeLiveTrader:
    """Async live trading loop for gap fade strategy.

    Production-grade design:
    - asyncio.Lock serializes all position mutations (no race conditions)
    - Orders are verified filled before updating internal state
    - Broker reconciliation on startup and periodic
    - Atomic state file writes (write-fsync-rename)
    - EOD close with retry loop and broker verification
    """

    STATE_KEY = 'gap_fade_state'
    RECONCILE_INTERVAL = 300  # seconds between broker reconciliation checks

    def __init__(self, config: GapFadeConfig = None):
        self.config = config or GapFadeConfig()
        self.engine = GapFadeEngine(self.config)
        self.scanner = GapScanner(self.config)
        self._execution_broker = _build_execution_broker(self.config)
        self.streamer = None  # AlpacaTickStreamer or IBKRTickStreamer
        self.status = 'stopped'        # stopped, scanning, trading, paused, waiting
        self.candidates: List[GapCandidate] = []
        self._task: Optional[asyncio.Task] = None
        self._monitor_task: Optional[asyncio.Task] = None
        self.last_scan_time = ''
        self.messages: List[dict] = []  # decision feed
        self._position_lock = asyncio.Lock()  # P0-2: serializes ALL position mutations
        self._last_reconcile = 0.0  # monotonic time of last broker reconciliation
        self._last_autonomous_review = 0.0  # monotonic time of last LLM review
        self._AUTONOMOUS_REVIEW_INTERVAL = 900  # seconds (15 min, event trigger can fire sooner)
        self._last_llm_decide = 0.0  # monotonic time of last decide_action call
        self._LLM_DECIDE_INTERVAL = 120  # seconds — don't re-ask Rudra unless state changed
        self._last_llm_state_hash = ''  # detect meaningful state changes
        self._last_loop_heartbeat = _time.monotonic()  # watchdog: trading loop health
        self._last_state_save_time = _time.monotonic()  # state persistence heartbeat
        # Exhaustion entry tracking (per-symbol Opening Range and signal state)
        self._opening_ranges: Dict[str, dict] = {}     # sym -> {high, low, built}
        self._exhaustion_signals: Dict[str, dict] = {} # sym -> {triggered, time, vwap, rsi}
        self._exhaustion_entered: set = set()           # symbols already entered via exhaustion
        # Sweep detector state (tracks liquidity sweeps above OR high)
        self._sweep_data: Dict[str, dict] = {}          # sym -> {sweep_high, sweep_time, bars_since, recovered, entry_triggered}
        # Pyramiding state
        self._last_pyramid_check: float = 0.0           # monotonic time of last pyramid scan
        self._last_model_rebuild = ''  # ISO date of last model rebuild
        self._trading_halted: bool = False  # EOD circuit breaker — set by watchdog, blocks new entries
        self._eod_watchdog_task: Optional[asyncio.Task] = None  # independent EOD guardian

        # SQLite database for persistent storage
        _db = get_price_db()

        # Event bus for LLM conversation (replaces flat _event_queue)
        self._event_bus = EventBus(db=_db)
        self._event_queue = self._event_bus  # backward compat alias
        self._urgent_llm_event: bool = False  # Tier 3 flag for immediate LLM call
        self._morning_briefing_done: str = ''  # date string, prevents re-triggering

        # Trading journal (append-only decision audit trail, SQLite-backed)
        self.journal = TradingJournal(db=_db)

        # Market event detector (zero-LLM, pure arithmetic)
        self.event_detector = MarketEventDetector()

        # Telegram alerts
        # Use RudraAlerter (Telegram + Email) if available, fallback to built-in
        try:
            from alerter import RudraAlerter
            self.alerter = RudraAlerter()
            logger.info("RudraAlerter loaded (Telegram + Email)")
        except Exception as e:
            self.alerter = AlertNotifier(self.config)
            logger.info(f"Using built-in AlertNotifier ({e})")

        # Load persisted state (before LLM init so config overrides apply)
        self.llm_supervisor = None
        self._load_state()

        # Strategy plugin system
        self.strategy = None
        self.indicator_engine = None
        self._strategy_config = {}  # strategy-specific config from state
        self._load_strategy(self.config.active_strategy)

        # Intraday strategy system
        self._intraday_strategies: Dict[str, 'IntradayStrategy'] = {}
        self._strategy_selector = None  # StrategySelector instance
        self._intraday_watchlist: List[str] = []
        self._intraday_entries_today: int = 0
        self._intraday_pnl_today: float = 0.0
        self._last_intraday_scan: float = 0.0
        self._last_intraday_watchlist_refresh: float = 0.0
        self._intraday_date: str = ''  # for daily reset

        # Swing engine state
        self._swing_kill_switch = WeeklyKillSwitch()
        self._swing_classifier = StageClassifier()
        self._swing_base_detector = TightBaseDetector()
        self._swing_volume = VolumeEngine()
        self._swing_bias = MultiTimeframeBias(self._swing_kill_switch)
        self._swing_candidates: List[dict] = []       # Current Stage 2 + tight base candidates
        self._swing_last_scan: str = ''                # Date of last weekly scan
        self._swing_enabled: bool = self.config.swing_enabled
        self._swing_watchlist: List[dict] = []         # Top 15 candidates
        self._swing_weekly_trades: int = 0             # Entries this week
        self._swing_week_key: str = ''                 # ISO week key for weekly trade counter reset
        self._swing_kill_switch_status: dict = {'active': False, 'reason': 'Not scanned yet'}
        self._swing_last_entry_check: float = 0.0     # Monotonic time of last entry check

        # Signal log ring buffer for intraday page
        self._signal_log: deque = deque(maxlen=200)
        self._signal_log_counter: int = 0
        self._last_perf_snapshot_hour: int = -1
        self._last_sse_tick: Dict[str, float] = {}  # throttle SSE ticks per symbol
        self._last_pos_broadcast: float = 0.0  # throttle WS position updates
        if self.config.intraday_enabled:
            self._init_intraday_strategies()

        # LLM Supervisor (after state load so llm_enabled from saved config takes effect)
        if self.config.llm_enabled:
            self.llm_supervisor = LLMSupervisor(self.config)
            # Restore conversation history from saved state (same-day only)
            saved_conv = getattr(self, '_saved_conversation', {})
            if saved_conv:
                self.llm_supervisor.memory = ConversationMemory.from_dict(saved_conv)
                if self.llm_supervisor.memory.history:
                    logger.info(f"Restored {len(self.llm_supervisor.memory.history)} conversation messages")
            # Apply strategy-specific LLM prompts
            if self.strategy:
                sys_prompt = self.strategy.get_llm_system_prompt()
                if sys_prompt:
                    self.llm_supervisor._SYSTEM_PROMPT = sys_prompt
                profit_prompt = self.strategy.get_llm_profit_prompt()
                if profit_prompt:
                    self.llm_supervisor._PROFIT_SYSTEM_PROMPT = profit_prompt
            logger.info(f"Rudra enabled: {self.config.llm_model} @ {self.config.llm_url}")
        else:
            logger.info("Rudra disabled (llm_enabled=false)")

    # -- Broker bridge methods -----------------------------------------------
    # These route all broker interactions to IBKR or Alpaca based on config.
    # Historical DB data (PostgreSQL) is shared across both brokers.

    @property
    def _use_ibkr(self) -> bool:
        return self._execution_broker is not None

    async def _broker_submit(self, symbol: str, qty: int, side: str, *,
                             order_type: str = 'market', limit_price: float = None,
                             timeout_sec: float = 30.0,
                             cancel_on_timeout: bool = False) -> 'OrderResult':
        """Submit order via configured broker."""
        if self._use_ibkr:
            return await self._execution_broker.submit_order(
                symbol, qty, side, order_type=order_type,
                limit_price=limit_price, timeout_sec=timeout_sec)
        return await alpaca_submit_and_confirm(
            symbol, qty, side, order_type=order_type,
            limit_price=limit_price, timeout_sec=timeout_sec,
            cancel_on_timeout=cancel_on_timeout)

    async def _broker_place_stop(self, symbol: str, qty: int, stop_price: float,
                                 limit_offset_pct: float = 0.003,
                                 direction: str = 'short') -> dict:
        """Place stop order via configured broker."""
        if self._use_ibkr:
            return await self._execution_broker.place_stop_order(
                symbol, qty, stop_price, limit_offset_pct, direction)
        return await asyncio.to_thread(
            alpaca_place_stop_order, symbol, qty, stop_price,
            limit_offset_pct, direction)

    async def _broker_cancel(self, order_id: str) -> bool:
        """Cancel order via configured broker."""
        if self._use_ibkr:
            return await self._execution_broker.cancel_order(order_id)
        return await asyncio.to_thread(alpaca_cancel_order, order_id)

    async def _broker_get_positions(self) -> List[dict]:
        """Get positions via configured broker."""
        if self._use_ibkr:
            return await self._execution_broker.get_positions()
        return await asyncio.to_thread(alpaca_get_positions)

    async def _broker_get_account(self) -> Optional[dict]:
        """Get account info via configured broker."""
        if self._use_ibkr:
            return await self._execution_broker.get_account()
        return await asyncio.to_thread(alpaca_get_account)

    async def _broker_close_position(self, symbol: str) -> dict:
        """Force-close position via configured broker."""
        if self._use_ibkr:
            # IBKR: submit market order to flatten
            positions = await self._broker_get_positions()
            for pos in positions:
                if pos['symbol'] == symbol:
                    close_side = 'sell' if pos['side'] == 'long' else 'buy'
                    result = await self._execution_broker.submit_order(
                        symbol, int(pos['qty']), close_side, order_type='market')
                    return {'status': result.status, 'order_id': result.order_id}
            return {'error': f'{symbol} not found in IBKR positions'}
        return await asyncio.to_thread(alpaca_close_position_api, symbol)

    def _broker_make_streamer(self, symbols: List[str], on_tick=None):
        """Create tick streamer via configured broker."""
        if self._use_ibkr:
            return self._execution_broker.create_tick_streamer(symbols, on_tick=on_tick)
        return AlpacaTickStreamer(symbols, on_tick=on_tick)

    async def _broker_ensure_connected(self) -> bool:
        """Ensure IBKR is connected (no-op for Alpaca)."""
        if self._use_ibkr:
            connected = await self._execution_broker.conn.ensure_connected()
            if not connected:
                logger.error("IBKR connection failed — halting trading")
                self._trading_halted = True
                return False
        return True

    async def _broker_get_order(self, order_id: str) -> Optional[dict]:
        """Get order status via configured broker."""
        if self._use_ibkr:
            return await self._execution_broker.get_order(order_id)
        return await asyncio.to_thread(alpaca_get_order, order_id)

    async def _broker_get_prices(self, symbols: List[str]) -> Dict[str, float]:
        """Get current prices for symbols via configured broker.

        Returns {symbol: price} regardless of broker.
        IBKR: uses reqMktData snapshots.
        Alpaca: uses /v2/stocks/snapshots, extracts latestTrade.p.
        """
        if self._use_ibkr:
            return await self._execution_broker.get_snapshot_prices(symbols)
        snaps = await asyncio.to_thread(fetch_alpaca_snapshots, symbols)
        prices = {}
        for sym, snap in snaps.items():
            p = snap.get('latestTrade', {}).get('p', 0.0)
            if p and p > 0:
                prices[sym] = float(p)
        return prices

    def _lookup_gap_context(self, symbol: str, entry_price: float,
                            direction: str) -> dict:
        """Look up gap context from daily_bars for an adopted position.

        Returns dict with prev_close, gap_pct, atr, open_price.
        Empty dict on failure.
        """
        try:
            db = get_price_db()
            cur = db._conn.cursor()
            # Get last 21 bars for ATR calculation + gap detection
            cur.execute(
                "SELECT date, open, high, low, close FROM daily_bars "
                "WHERE symbol = %s ORDER BY date DESC LIMIT 21",
                (symbol,))
            rows = cur.fetchall()
            if len(rows) < 2:
                return {}

            today_bar = rows[0]  # most recent
            prev_bar = rows[1]   # previous day
            open_price = float(today_bar[1])
            prev_close = float(prev_bar[4])

            if prev_close <= 0:
                return {}

            gap_pct = (open_price - prev_close) / prev_close

            # Compute ATR(14) from available bars
            atr = 0.0
            if len(rows) >= 15:
                tr_vals = []
                for i in range(len(rows) - 1):
                    h, l, pc = float(rows[i][2]), float(rows[i][3]), float(rows[i + 1][4])
                    tr_vals.append(max(h - l, abs(h - pc), abs(l - pc)))
                atr = sum(tr_vals[:14]) / min(14, len(tr_vals[:14]))

            return {
                'prev_close': prev_close,
                'gap_pct': gap_pct,
                'atr': atr,
                'open_price': open_price,
            }
        except Exception as e:
            logger.warning(f"Gap context lookup failed for {symbol}: {e}")
            return {}

    def _add_message(self, msg_type: str, text: str, data: dict = None):
        """Add a message to the decision feed."""
        msg = {
            'type': msg_type,
            'text': text,
            'time': datetime.now(ET).strftime('%H:%M:%S'),
            'data': data or {},
        }
        self.messages.append(msg)
        if len(self.messages) > 200:
            self.messages = self.messages[-100:]

    def _record_performance_snapshot(self, interval_type: str = 'hourly'):
        """Record a performance snapshot to the database."""
        try:
            db = get_price_db()
            # Gather stats from engine
            eng = self.engine
            today = datetime.now(ET).strftime('%Y-%m-%d')
            wins = eng.daily_stats.wins if hasattr(eng, 'daily_stats') else 0
            losses = eng.daily_stats.losses if hasattr(eng, 'daily_stats') else 0
            total = wins + losses
            win_rate = wins / total if total > 0 else 0
            realized_pnl = eng.daily_stats.pnl if hasattr(eng, 'daily_stats') else 0
            trades_today = eng.daily_stats.trade_count if hasattr(eng, 'daily_stats') else 0

            # Unrealized P&L from open positions
            unrealized = 0.0
            for sym, pos in eng.positions.items():
                if hasattr(pos, 'current_price') and pos.current_price > 0:
                    if pos.direction == 'long':
                        unrealized += (pos.current_price - pos.entry_price) * pos.remaining_shares
                    else:
                        unrealized += (pos.entry_price - pos.current_price) * pos.remaining_shares

            # Max drawdown
            dd = 0.0
            if eng.peak_equity > 0 and eng.equity < eng.peak_equity:
                dd = (eng.peak_equity - eng.equity) / eng.peak_equity

            # Top symbols by P&L today
            top_symbols = []
            if hasattr(eng, 'trade_history') and eng.trade_history:
                sym_pnl: dict = {}
                for t in eng.trade_history:
                    if hasattr(t, 'exit_time') and t.exit_time and today in str(t.exit_time):
                        sym_pnl[t.symbol] = sym_pnl.get(t.symbol, 0) + t.pnl
                top_symbols = sorted(sym_pnl.items(), key=lambda x: abs(x[1]), reverse=True)[:5]

            db.insert_performance_snapshot(
                interval_type=interval_type,
                equity=eng.equity,
                cash=getattr(eng, 'cash', eng.equity),
                open_positions=len(eng.positions),
                unrealized_pnl=unrealized,
                realized_pnl_today=realized_pnl,
                trades_today=trades_today,
                wins=wins, losses=losses, win_rate=win_rate,
                max_drawdown=dd,
                strategy_breakdown_json=json.dumps({'active': self.config.active_strategy}),
                top_symbols_json=json.dumps(top_symbols, default=str),
            )
            logger.info(f"Performance snapshot ({interval_type}): equity=${eng.equity:,.0f}, "
                       f"pnl=${realized_pnl:+,.2f}, positions={len(eng.positions)}")
        except Exception as e:
            logger.debug(f"Performance snapshot failed: {e}")

    def _log_signal(self, symbol: str, strategy_id: str, signal: str,
                    direction: str = '', confidence: float = 0.0,
                    entry: float = 0.0, stop: float = 0.0, target: float = 0.0,
                    risk_reward: float = 0.0, reason: str = '', action: str = 'pending',
                    market_condition: str = '', indicators: dict = None):
        """Log an intraday signal to the ring buffer, broadcast via SSE, and persist to DB."""
        self._signal_log_counter += 1
        now_ts = datetime.now(ET)
        entry_obj = {
            'id': self._signal_log_counter,
            'timestamp': now_ts.strftime('%H:%M:%S'),
            'symbol': symbol,
            'strategy_id': strategy_id,
            'signal': signal,
            'direction': direction,
            'confidence': round(confidence, 4),
            'entry_price': round(entry, 2),
            'stop_price': round(stop, 2),
            'target_price': round(target, 2),
            'risk_reward': round(risk_reward, 2),
            'reason': reason,
            'action': action,
            'market_condition': market_condition,
            'indicators': indicators or {},
        }
        self._signal_log.append(entry_obj)
        # Persist signal to database
        try:
            db_id = get_price_db().insert_signal(
                timestamp=now_ts.isoformat(),
                symbol=symbol, strategy_id=strategy_id,
                signal=signal, direction=direction, confidence=confidence,
                entry_price=entry, stop_price=stop, target_price=target,
                risk_reward=risk_reward, reason=reason, action=action,
                market_condition=market_condition,
                indicators_json=json.dumps(indicators or {}, default=str),
            )
            entry_obj['_db_id'] = db_id
        except Exception:
            pass
        # Fire-and-forget SSE broadcast
        try:
            _intraday_sse_broadcast({'type': 'intraday_signal', 'signal': entry_obj})
        except Exception:
            pass

    def _add_event(self, text: str, tier: int = 2):
        """Add an event to the LLM conversation queue.

        Tiers:
            1 = Silent: injected into memory as a brief note
            2 = Batched: queued for next scheduled LLM call
            3 = Triggered: immediate LLM conversation call (stop-outs, loss limits)
            4 = Human escalation: Telegram alert + urgent LLM + auto-standdown
        """
        self._event_bus.push_text(text, tier)
        # Tier 1: also inject directly into conversation memory
        if tier == 1 and self.llm_supervisor:
            self.llm_supervisor.memory.add_event(text)
        # Tier 3+: flag for immediate processing (checked by trading loop)
        if tier >= 3:
            self._urgent_llm_event = True

    def _load_strategy(self, strategy_id: str):
        """Load a strategy by ID, creating indicator engine if needed."""
        try:
            from gap_fade_strategies import GapFadeStrategyRegistry, TickIndicatorEngine
            if not GapFadeStrategyRegistry.has_strategy(strategy_id):
                logger.warning(f"Strategy '{strategy_id}' not found, falling back to classic_gap_fade")
                strategy_id = 'classic_gap_fade'
            self.strategy = GapFadeStrategyRegistry.create_strategy(
                strategy_id, config=self._strategy_config.get(strategy_id))
            self.config.active_strategy = strategy_id

            # Create indicator engine if strategy needs it
            required = self.strategy.get_required_indicators()
            if required:
                ema_period = self.strategy.config.get('ema_trailing_period', 9)
                or_minutes = self.strategy.config.get('opening_range_minutes', 5)
                ema_buffer = self.strategy.config.get('ema_trailing_buffer_pct', 0.001)
                self.indicator_engine = TickIndicatorEngine(
                    indicators=required,
                    ema_period=ema_period,
                    or_minutes=or_minutes,
                    ema_buffer_pct=ema_buffer,
                )
                logger.info(f"Indicator engine created: {required}")
            else:
                # Exhaustion entry always needs VWAP + RSI — create minimal engine
                self.indicator_engine = TickIndicatorEngine(
                    indicators=['vwap', 'rsi', 'ema', 'day_high', 'day_low'],
                    ema_period=9,
                    or_minutes=15,
                )
                logger.info("Indicator engine created (exhaustion entry defaults)")

            logger.info(f"Strategy loaded: {self.strategy.name} ({strategy_id})")
        except Exception as e:
            logger.error(f"Failed to load strategy '{strategy_id}': {e}")
            self.strategy = None
            # Still create indicator engine for exhaustion entry
            self.indicator_engine = TickIndicatorEngine(
                indicators=['vwap', 'rsi', 'ema', 'day_high', 'day_low'],
                ema_period=9,
                or_minutes=15,
            )
            logger.info("Indicator engine created (fallback for exhaustion entry)")

    def switch_strategy(self, strategy_id: str, strategy_config: dict = None):
        """Hot-swap the active strategy (no restart needed).

        Existing positions continue with engine defaults.
        """
        if strategy_config:
            self._strategy_config[strategy_id] = strategy_config
        self._load_strategy(strategy_id)

        # Update LLM prompts if supervisor is active
        if self.llm_supervisor and self.strategy:
            sys_prompt = self.strategy.get_llm_system_prompt()
            if sys_prompt:
                self.llm_supervisor._SYSTEM_PROMPT = sys_prompt
            profit_prompt = self.strategy.get_llm_profit_prompt()
            if profit_prompt:
                self.llm_supervisor._PROFIT_SYSTEM_PROMPT = profit_prompt

        self._save_state()
        self._add_message('strategy', f'Switched to: {self.strategy.name if self.strategy else strategy_id}')

    # ── Intraday Strategy Methods ────────────────────────────────────

    def _init_intraday_strategies(self):
        """Initialize enabled intraday strategies from config."""
        try:
            from gap_fade_strategies import IntradayStrategyRegistry
        except ImportError:
            logger.warning("Intraday strategy module not available")
            return

        strategy_ids = [s.strip() for s in self.config.intraday_strategies.split(',')
                        if s.strip()]
        if not strategy_ids:
            logger.info("Intraday enabled but no strategies specified")
            return

        for sid in strategy_ids:
            if IntradayStrategyRegistry.has_strategy(sid):
                strat = IntradayStrategyRegistry.create_strategy(sid)
                self._intraday_strategies[sid] = strat
                logger.info(f"Loaded intraday strategy: {strat.name} ({sid})")
            else:
                logger.warning(f"Intraday strategy '{sid}' not found in registry")

        # Ensure indicator engine covers intraday strategy requirements
        if self._intraday_strategies:
            self._expand_indicator_engine_for_intraday()

        # Create strategy selector for condition-based routing
        if self._intraday_strategies:
            try:
                from gap_fade_strategies import StrategySelector
                self._strategy_selector = StrategySelector(self._intraday_strategies)
                logger.info("Strategy selector initialized for condition-based routing")
            except Exception as e:
                logger.warning(f"Failed to create strategy selector: {e}")

        logger.info(f"Intraday system initialized: {len(self._intraday_strategies)} strategies")

    def _expand_indicator_engine_for_intraday(self):
        """Expand indicator engine to cover intraday strategy requirements."""
        from gap_fade_strategies import TickIndicatorEngine

        all_indicators = set()
        all_ema_periods = set()

        # Collect from gap fade strategy
        if self.strategy:
            all_indicators.update(self.strategy.get_required_indicators())

        # Collect from all intraday strategies
        for strat in self._intraday_strategies.values():
            all_indicators.update(strat.get_required_indicators())
            all_ema_periods.update(strat.get_ema_periods())

        if not all_indicators:
            return

        # Rebuild indicator engine with expanded requirements
        ema_period = 9  # primary period
        or_minutes = 15  # intraday strategies need 15-min OR
        for strat in self._intraday_strategies.values():
            cfg_or = strat.config.get('or_minutes', 15)
            or_minutes = max(or_minutes, cfg_or)

        self.indicator_engine = TickIndicatorEngine(
            indicators=list(all_indicators),
            ema_period=ema_period,
            or_minutes=or_minutes,
            ema_periods=list(all_ema_periods),
        )
        logger.info(f"Indicator engine expanded: {all_indicators}, "
                     f"EMA periods: {sorted(all_ema_periods)}, OR: {or_minutes}min")

    def _reset_intraday_daily(self):
        """Reset intraday daily state."""
        self._intraday_entries_today = 0
        self._intraday_pnl_today = 0.0
        self._last_intraday_scan = 0.0
        self._last_intraday_watchlist_refresh = 0.0
        self._intraday_watchlist.clear()
        for strat in self._intraday_strategies.values():
            strat.on_day_start()
        # Reset indicator engine accumulated state for clean new day
        if self.indicator_engine:
            self.indicator_engine.reset()
        self._intraday_date = datetime.now(ET).strftime('%Y-%m-%d')
        logger.info("Intraday daily reset complete")

    async def _intraday_scan_and_enter(self):
        """Scan watchlist for intraday setups and enter qualifying ones.

        Called from _trading_loop after gap entry window closes.
        Throttled to config.intraday_scan_interval.
        Uses StrategySelector to pick strategies based on SPY market condition.
        """
        # Circuit breaker: EOD watchdog has halted trading
        if self._trading_halted:
            return

        now_mono = _time.monotonic()
        now = datetime.now(ET)
        today = now.strftime('%Y-%m-%d')

        # Daily reset
        if today != self._intraday_date:
            self._reset_intraday_daily()
            if self._strategy_selector:
                self._strategy_selector.reset_daily()

        # Throttle scans
        if now_mono - self._last_intraday_scan < self.config.intraday_scan_interval:
            return
        self._last_intraday_scan = now_mono

        # Wait for streamer to connect and accumulate some tick data
        if self.streamer and not self.streamer.connected:
            return  # WS not connected yet, skip this scan

        # Check daily limits
        if self._intraday_entries_today >= self.config.intraday_max_entries:
            return

        # Check daily loss limit for intraday trades
        if self.engine.equity > 0:
            intraday_loss_pct = abs(self._intraday_pnl_today) / self.engine.equity
            if self._intraday_pnl_today < 0 and intraday_loss_pct >= self.config.intraday_daily_loss_limit:
                return

        # Refresh watchlist periodically (every 5 minutes)
        if now_mono - self._last_intraday_watchlist_refresh > 300:
            await self._build_intraday_watchlist()
            self._last_intraday_watchlist_refresh = now_mono

        if not self._intraday_watchlist:
            return

        # Use strategy selector to pick strategies based on market condition
        active_strategies = self._intraday_strategies  # fallback: all strategies
        size_multiplier = 1.0

        if self._strategy_selector and self.indicator_engine:
            spy_data = self.indicator_engine.get_data('SPY')
            if spy_data and spy_data.get('rsi_initialized'):
                try:
                    active_strategies = self._strategy_selector.update(spy_data, now)
                    size_multiplier = self._strategy_selector.size_multiplier
                except Exception as e:
                    logger.warning(f"Strategy selector error: {e}")

        if not active_strategies:
            return

        # Scan each watchlist symbol with each active strategy
        setups: List['IntradaySetup'] = []
        _symbols_with_data = 0
        _symbols_no_data = 0
        for symbol in self._intraday_watchlist:
            if symbol == 'SPY':
                continue  # SPY is for condition detection, not trading

            tick_data = self.indicator_engine.get_data(symbol) if self.indicator_engine else {}
            if not tick_data:
                _symbols_no_data += 1
                continue

            _symbols_with_data += 1

            # Build snapshot dict from streamer prices
            snapshot = None
            if self.streamer and self.streamer.latest_prices.get(symbol):
                snapshot = {'price': self.streamer.latest_prices[symbol]}

            for sid, strat in active_strategies.items():
                # Check active window
                h1, m1, h2, m2 = strat.get_active_window()
                if (now.hour, now.minute) < (h1, m1):
                    continue
                if (now.hour, now.minute) > (h2, m2):
                    continue

                try:
                    setup = strat.scan_for_setups(symbol, tick_data, snapshot, now)
                    if setup is not None:
                        # Validate
                        valid, reason = strat.validate_setup(setup, tick_data, now)
                        _mkt_cond = ''
                        if self._strategy_selector and self._strategy_selector.current_condition:
                            _mkt_cond = self._strategy_selector.current_condition.condition
                        _ind_snap = {k: round(v, 4) if isinstance(v, float) else v
                                     for k, v in (tick_data or {}).items()
                                     if k in ('rsi', 'vwap', 'atr', 'volume_surge', 'ema9', 'ema21')}
                        if valid:
                            setups.append(setup)
                            self._log_signal(symbol, sid, signal=setup.direction.upper(),
                                             direction=setup.direction,
                                             confidence=setup.confidence,
                                             entry=setup.entry_price, stop=setup.stop_price,
                                             target=setup.target_price, risk_reward=setup.risk_reward,
                                             action='pending', market_condition=_mkt_cond,
                                             indicators=_ind_snap)
                        else:
                            logger.debug(f"Intraday setup rejected {symbol}/{sid}: {reason}")
                            self._log_signal(symbol, sid, signal='REJECTED',
                                             direction=setup.direction,
                                             confidence=setup.confidence,
                                             entry=setup.entry_price, stop=setup.stop_price,
                                             target=setup.target_price, risk_reward=setup.risk_reward,
                                             reason=reason, action='rejected',
                                             market_condition=_mkt_cond, indicators=_ind_snap)
                except Exception as e:
                    logger.warning(f"Intraday scan error {symbol}/{sid}: {e}")

        # Diagnostic logging (periodic, not every scan)
        if _symbols_no_data > 0 and _symbols_with_data == 0:
            logger.info(f"Intraday scan: {_symbols_no_data} symbols have no indicator data yet "
                         f"(streamer warming up) — {len(active_strategies)} strategies active")
        elif _symbols_with_data > 0:
            logger.debug(f"Intraday scan: {_symbols_with_data} symbols scanned, "
                          f"{_symbols_no_data} no data, {len(setups)} setups found")

        if not setups:
            return

        # Rank setups by confidence (descending)
        setups.sort(key=lambda s: s.confidence, reverse=True)

        # Enter the best setups (up to remaining capacity)
        remaining = self.config.intraday_max_entries - self._intraday_entries_today
        if self.config.capital_partition:
            intraday_count = self.engine.count_positions_by_source('intraday')
            max_positions = self.config.intraday_max_positions - intraday_count
        else:
            max_positions = self.config.max_positions - len(self.engine.positions)
        entries_allowed = min(remaining, max_positions)

        for setup in setups[:entries_allowed]:
            entered = await self._enter_intraday_position(setup, size_multiplier)
            if entered:
                self._intraday_entries_today += 1
                condition_str = ''
                if self._strategy_selector and self._strategy_selector.current_condition:
                    condition_str = f' [{self._strategy_selector.current_condition.condition}]'
                self._add_message('intraday',
                    f'Intraday {setup.direction.upper()} {setup.symbol} '
                    f'[{setup.setup_type}] @ ${setup.entry_price:.2f} '
                    f'(conf={setup.confidence:.0%}, R:R={setup.risk_reward:.1f}){condition_str}')
                # Update the most recent pending signal for this symbol to 'entered'
                for sig in reversed(self._signal_log):
                    if sig['symbol'] == setup.symbol and sig['action'] == 'pending':
                        sig['action'] = 'entered'
                        if sig.get('_db_id'):
                            get_price_db().update_signal_action(sig['_db_id'], 'entered')
                        break
            else:
                # Mark as skipped (capacity or entry failure)
                for sig in reversed(self._signal_log):
                    if sig['symbol'] == setup.symbol and sig['action'] == 'pending':
                        sig['action'] = 'skipped'
                        sig['reason'] = 'entry_failed_or_capacity'
                        if sig.get('_db_id'):
                            get_price_db().update_signal_action(
                                sig['_db_id'], 'skipped', 'entry_failed_or_capacity')
                        break
        # Mark remaining pending setups beyond entries_allowed as skipped_capacity
        for setup in setups[entries_allowed:]:
            for sig in reversed(self._signal_log):
                if sig['symbol'] == setup.symbol and sig['action'] == 'pending':
                    sig['action'] = 'skipped_capacity'
                    sig['reason'] = 'max_entries_reached'
                    if sig.get('_db_id'):
                        get_price_db().update_signal_action(
                            sig['_db_id'], 'skipped_capacity', 'max_entries_reached')
                    break

    async def _enter_intraday_position(self, setup: 'IntradaySetup',
                                        size_multiplier: float = 1.0) -> bool:
        """Enter a position from an intraday setup.

        Uses the setup's stop/target directly (not gap-based).
        Position sizing: equity * intraday_risk_pct * size_multiplier / risk_per_share.
        """
        # Don't enter if already in this symbol
        if setup.symbol in self.engine.positions:
            return False

        # Position sizing based on allocated equity
        alloc_equity = self.engine.allocated_equity('intraday')
        risk_per_share = abs(setup.entry_price - setup.stop_price)
        if risk_per_share <= 0:
            return False

        risk_amount = alloc_equity * self.config.intraday_risk_pct * size_multiplier
        shares = int(risk_amount / risk_per_share)
        shares = max(1, shares)

        # Cap at max % of allocated equity per position (prevents over-concentration)
        max_position_value = alloc_equity * self.config.intraday_max_position_pct
        if shares * setup.entry_price > max_position_value:
            shares = max(1, int(max_position_value / setup.entry_price))

        # Apply notional cap
        notional = shares * setup.entry_price
        if notional > self.config.max_notional:
            shares = max(1, int(self.config.max_notional / setup.entry_price))

        # Create position
        async with self._position_lock:
            # Re-check capacity under lock (partitioned)
            if self.config.capital_partition:
                intraday_count = self.engine.count_positions_by_source('intraday')
                if intraday_count >= self.config.intraday_max_positions:
                    return False
            else:
                if len(self.engine.positions) >= self.config.max_positions:
                    return False
            if setup.symbol in self.engine.positions:
                return False

            pos = GapPosition(
                symbol=setup.symbol,
                shares=shares,
                entry_price=setup.entry_price,
                stop_price=setup.stop_price,
                half_target=(setup.entry_price + setup.target_price) / 2,
                full_target=setup.target_price,
                prev_close=setup.entry_price,  # no gap concept for intraday
                entry_time=setup.timestamp.strftime('%Y-%m-%d %H:%M') if setup.timestamp else '',
                direction=setup.direction,
                strategy_id=setup.strategy_id,
                source='intraday',
            )
            self.engine.positions[setup.symbol] = pos

        # Submit order
        entry_side = 'buy' if setup.direction == 'long' else 'sell'
        if self.config.limit_orders_only:
            if setup.direction == 'long':
                limit_px = round(setup.entry_price * (1 + self.config.limit_offset_pct), 2)
            else:
                limit_px = round(setup.entry_price * (1 - self.config.limit_offset_pct), 2)
            order_type = 'limit'
        else:
            limit_px = None
            order_type = 'market'

        fill = await self._broker_submit(
            setup.symbol, shares, entry_side,
            order_type=order_type, limit_price=limit_px,
            timeout_sec=120.0 if order_type == 'limit' else 30.0,
        )

        async with self._position_lock:
            pos = self.engine.positions.get(setup.symbol)
            if not pos:
                return False

            if fill.is_filled:
                pos.entry_fill_price = fill.filled_avg_price
                pos.entry_order_id = fill.order_id
                if fill.filled_avg_price > 0:
                    pos.entry_price = fill.filled_avg_price

                # Place broker-side stop order
                try:
                    stop_result = await self._broker_place_stop(
                        setup.symbol, pos.remaining_shares, setup.stop_price,
                        0.003, setup.direction)
                    if 'error' not in stop_result:
                        pos.stop_order_id = stop_result.get('id', '')
                except Exception as e:
                    logger.warning(f"Broker stop order failed for intraday {setup.symbol}: {e}")

                # Subscribe to tick stream (evict watchlist symbols if at limit)
                if self.streamer:
                    await self.streamer.add_symbols(
                        [setup.symbol],
                        priority_symbols=set(self.engine.positions.keys()))

                # Record entry in strategy
                strat = self._intraday_strategies.get(setup.strategy_id)
                if strat and hasattr(strat, 'record_entry'):
                    strat.record_entry(setup.symbol)

                self.journal.log('action', f'intraday:{setup.strategy_id}',
                    f'Entered {setup.direction} {shares} {setup.symbol} @ '
                    f'${fill.filled_avg_price:.2f} (stop ${setup.stop_price:.2f}, '
                    f'target ${setup.target_price:.2f})',
                    symbol=setup.symbol)

                self._save_state()
                return True
            elif fill.status == 'pending' and order_type == 'limit':
                # Limit order still open — keep position, track order_id
                pos.entry_order_id = fill.order_id
                self._add_message('info',
                    f'{setup.symbol} intraday limit order still open, holding '
                    f'(id={fill.order_id})')
                self._save_state()
                return True
            else:
                # Fill failed — remove position
                self.engine.positions.pop(setup.symbol, None)
                logger.warning(f"Intraday order fill failed for {setup.symbol}: {fill.status}")
                return False

    async def _build_intraday_watchlist(self):
        """Build the intraday watchlist from multiple sources.

        Priority order (earlier sources get slots first):
        1. SPY (always, for market condition detection)
        2. Existing positions (must always watch)
        3. Morning gap candidates
        4. Alpaca screener: most-active + top movers (dynamic, refreshed every 5 min)
        5. Static liquid symbols (always included as baseline)
        """
        # Use ordered list to preserve priority — earlier sources get priority
        priority_syms: List[str] = ['SPY']

        # Source 1: Existing positions (always watch)
        for sym in self.engine.positions:
            if sym not in priority_syms:
                priority_syms.append(sym)

        # Source 2: Morning gap candidates
        for c in self.candidates:
            if c.symbol not in priority_syms:
                priority_syms.append(c.symbol)

        # Source 3: Dynamic movers from Alpaca screener API
        try:
            movers = await asyncio.to_thread(fetch_alpaca_movers, 20)
            _added_movers = 0
            for sym in movers:
                if sym not in priority_syms:
                    priority_syms.append(sym)
                    _added_movers += 1
            if _added_movers:
                logger.info(f"Intraday watchlist: added {_added_movers} symbols from Alpaca screener")
        except Exception as e:
            logger.warning(f"Intraday watchlist: screener fetch failed: {e}")

        # Source 4: Static liquid symbols (always included as baseline)
        _liquid_syms = [
            'AAPL', 'MSFT', 'NVDA', 'AMZN', 'META', 'GOOGL', 'TSLA',
            'AMD', 'NFLX', 'QQQ', 'IWM', 'SOFI', 'PLTR', 'COIN',
            'MARA', 'RIVN', 'SNAP', 'UBER', 'SQ', 'SHOP',
        ]
        for sym in _liquid_syms:
            if sym not in priority_syms:
                priority_syms.append(sym)

        # Cap at config limit
        max_size = self.config.intraday_watchlist_size
        self._intraday_watchlist = priority_syms[:max_size]

        # Subscribe new symbols to tick streamer
        if self.streamer and self._intraday_watchlist:
            await self.streamer.add_symbols(self._intraday_watchlist)
            logger.info(f"Subscribed {len(self._intraday_watchlist)} watchlist symbols to streamer")
        elif not self.streamer:
            logger.warning("Intraday watchlist built but no streamer — symbols won't receive ticks")

        logger.info(f"Intraday watchlist: {len(self._intraday_watchlist)} symbols: "
                     f"{self._intraday_watchlist[:10]}{'...' if len(self._intraday_watchlist) > 10 else ''}")

    async def _seed_indicator_engine(self):
        """Fetch today's 5-min bars from Alpaca and seed the indicator engine.

        This eliminates the ~75-minute cold-start wait for RSI initialization
        when the app starts (or restarts) mid-day.
        """
        if not self.indicator_engine:
            return
        symbols = list(self._intraday_watchlist) if self._intraday_watchlist else []
        if not symbols:
            return

        today_str = datetime.now(ET).strftime('%Y-%m-%d')
        try:
            bars_dict = await asyncio.to_thread(
                fetch_alpaca_bars_multi, symbols, today_str, today_str,
                '5Min', 'sip',
            )
            total_bars = 0
            seeded = 0
            for sym, df in bars_dict.items():
                if df is None or df.empty:
                    continue
                bars_list = []
                for _, row in df.iterrows():
                    ts = row.get('timestamp') or row.name
                    ts_et = None
                    if hasattr(ts, 'astimezone'):
                        try:
                            ts_et = ts.astimezone(ET)
                        except TypeError:
                            # tz-naive timestamp (IEX feed) — assume UTC
                            ts_et = ts.tz_localize('UTC').astimezone(ET)
                    bar_time = ''
                    if ts_et is not None:
                        bar_min = (ts_et.minute // 5) * 5
                        bar_time = f'{ts_et.hour}:{bar_min:02d}'
                    bars_list.append({
                        'open': float(row['open']),
                        'high': float(row['high']),
                        'low': float(row['low']),
                        'close': float(row['close']),
                        'volume': int(row.get('volume', 0)),
                        'bar_time': bar_time,
                    })
                if bars_list:
                    self.indicator_engine.seed_bars(sym, bars_list, today_str)
                    total_bars += len(bars_list)
                    seeded += 1
            logger.info(f"Indicator engine seeded: {seeded} symbols, {total_bars} total bars")
            # Immediately classify market condition so dashboard doesn't show "Waiting for data"
            if seeded > 0 and self._strategy_selector and self.indicator_engine:
                spy_data = self.indicator_engine.get_data('SPY')
                if spy_data and spy_data.get('rsi_initialized'):
                    now = datetime.now(ET)
                    self._strategy_selector.update(spy_data, now)
                    cond = self._strategy_selector.current_condition
                    logger.info(f"Market condition after seed: {cond.condition if cond else 'unknown'}")
        except Exception as e:
            logger.warning(f"Indicator engine seeding failed (non-fatal): {e}")

    async def start(self):
        """Start the live trading loop."""
        if self.status in ('trading', 'scanning'):
            logger.info(f"Start called but already {self.status}, skipping")
            return
        self.status = 'scanning'
        # Only reset daily stats on a genuinely new day (not mid-day restart)
        today_str = datetime.now(ET).strftime('%Y-%m-%d')
        if self.engine.daily_stats.date != today_str:
            self.engine.reset_daily()
            self.event_detector.reset_daily()
        # Ensure IBKR connected before anything else
        if not await self._broker_ensure_connected():
            return
        # P0-4: reconcile with broker on startup
        await self._reconcile_with_broker()
        # Build intraday watchlist before creating streamer so we can include
        # all symbols in the initial WS subscription (avoids add_symbols race)
        if self.config.intraday_enabled and self._intraday_strategies:
            await self._build_intraday_watchlist()
            self._last_intraday_watchlist_refresh = _time.monotonic()
            # Seed indicator engine with today's historical bars so RSI/EMA are warm
            await self._seed_indicator_engine()
            # Set intraday date so the daily-reset check in _intraday_scan_and_enter
            # doesn't immediately wipe the seeded data on its first call
            self._intraday_date = datetime.now(ET).strftime('%Y-%m-%d')

        # Start tick streamer — combine existing positions + intraday watchlist
        _stream_syms = set()
        if self.engine.positions:
            _stream_syms.update(self.engine.positions.keys())
        if self.config.intraday_enabled and self._intraday_watchlist:
            _stream_syms.update(self._intraday_watchlist)

        if _stream_syms and not self.streamer:
            self.streamer = self._broker_make_streamer(
                list(_stream_syms), on_tick=self._on_tick)
            await self.streamer.start()
            logger.info(f"Tick streamer started for {len(_stream_syms)} symbols "
                         f"(positions + intraday watchlist)")

        if self.config.intraday_enabled and self._intraday_strategies:
            logger.info(f"Intraday system bootstrapped: {len(self._intraday_strategies)} "
                         f"strategies, {len(self._intraday_watchlist)} watchlist symbols")

        self._task = asyncio.create_task(self._trading_loop())
        # Start independent EOD watchdog (if not already running)
        if (self._eod_watchdog_task is None or self._eod_watchdog_task.done()):
            self._eod_watchdog_task = asyncio.create_task(self._eod_watchdog())
            logger.info("EOD watchdog task started (independent of trading loop)")
        logger.info("Live trader started")
        self._add_message('system', 'Live trader started')
        await broadcast({'type': 'live_status', 'status': self.status})

    async def stop(self):
        """Stop the live trader and close all positions."""
        self.status = 'stopped'
        # Cancel all broker-side stop orders
        for sym, pos in list(self.engine.positions.items()):
            if pos.stop_order_id:
                try:
                    await self._broker_cancel(pos.stop_order_id)
                    pos.stop_order_id = ''
                except Exception:
                    pass
        if self.streamer:
            await self.streamer.stop()
            self.streamer = None
        if self._task and not self._task.done():
            self._task.cancel()
            try:
                await self._task
            except asyncio.CancelledError:
                pass
        if self._monitor_task and not self._monitor_task.done():
            self._monitor_task.cancel()
            try:
                await self._monitor_task
            except asyncio.CancelledError:
                pass
        if self._eod_watchdog_task and not self._eod_watchdog_task.done():
            self._eod_watchdog_task.cancel()
            try:
                await self._eod_watchdog_task
            except asyncio.CancelledError:
                pass
        # Disconnect IBKR if connected
        if self._use_ibkr:
            await self._execution_broker.conn.disconnect()
        self._trading_halted = False
        self._add_message('system', 'Live trader stopped')
        self._save_state()
        await broadcast({'type': 'live_status', 'status': self.status})

    async def pause(self):
        self.status = 'paused'
        self._add_message('system', 'Live trader paused')
        await broadcast({'type': 'live_status', 'status': self.status})

    async def resume(self):
        if self.status == 'paused':
            self.status = 'trading'
            self._add_message('system', 'Live trader resumed')
            await broadcast({'type': 'live_status', 'status': self.status})

    # -------------------------------------------------------------------------
    # P0-4: Broker Reconciliation
    # -------------------------------------------------------------------------

    async def _reconcile_with_broker(self):
        """Compare internal positions with Alpaca broker positions.

        On startup and periodically during trading hours. Broker is source of
        truth — if we have a position internally that doesn't exist on broker,
        we remove it. If broker has a position we don't know about, we adopt it.
        """
        try:
            broker_positions = await self._broker_get_positions()
        except Exception as e:
            logger.warning(f"Reconciliation failed (could not reach broker): {e}")
            await self.alerter.send('Broker API Failure',
                f'Could not reach broker: {e}',
                level='error', throttle_key='broker_api')
            return

        broker_map = {}  # symbol -> {qty, avg_entry_price, side}
        for bp in broker_positions:
            sym = bp.get('symbol', '')
            qty = abs(int(bp.get('qty', 0)))
            side = bp.get('side', '')
            avg_price = float(bp.get('avg_entry_price', 0))
            if sym and qty > 0:
                broker_map[sym] = {'qty': qty, 'avg_entry_price': avg_price, 'side': side}

        internal_syms = set(self.engine.positions.keys())
        broker_syms = set(broker_map.keys())

        # Positions we think we have but broker doesn't
        orphaned = internal_syms - broker_syms
        for sym in orphaned:
            pos = self.engine.positions[sym]
            # Check if this is a pending entry order (not filled yet)
            if pos.entry_fill_price == 0.0 and pos.entry_order_id:
                # Pending limit order — check if it filled or was cancelled
                try:
                    order_data = await self._broker_get_order(pos.entry_order_id)
                    if order_data:
                        ost = order_data.get('status', '')
                        if ost == 'filled':
                            # Order filled! Update position with fill data
                            pos.entry_fill_price = float(order_data.get('filled_avg_price', 0))
                            pos.entry_price = pos.entry_fill_price
                            pos.remaining_shares = int(order_data.get('filled_qty', pos.shares))
                            logger.info(f"RECONCILE: Pending order for {sym} FILLED "
                                       f"@ ${pos.entry_fill_price:.2f}")
                            self._add_message('entry',
                                f'RECONCILE: {sym} limit order filled @ ${pos.entry_fill_price:.2f}')
                            continue  # Don't remove — it's now a real position
                        elif ost in ('cancelled', 'canceled', 'expired', 'rejected'):
                            logger.info(f"RECONCILE: Pending order for {sym} {ost} — removing")
                            self._add_message('info',
                                f'RECONCILE: {sym} pending order {ost} — removed')
                        elif ost in ('new', 'accepted', 'pending_new', 'partially_filled'):
                            logger.info(f"RECONCILE: {sym} entry order still {ost}, keeping")
                            continue  # Order still live — don't remove
                        else:
                            logger.warning(f"RECONCILE: {sym} entry order status={ost}, removing")
                except Exception as e:
                    logger.warning(f"RECONCILE: Could not check pending order for {sym}: {e}")
                    continue  # Don't remove if we can't verify

            logger.warning(f"RECONCILE: Internal position {sym} ({pos.remaining_shares} shares) "
                          f"NOT found on broker — removing from internal state")
            self._add_message('warning', f'RECONCILE: {sym} not on broker — removed internally')
            del self.engine.positions[sym]

        # Positions broker has that we don't know about — adopt with context
        unknown = broker_syms - internal_syms
        for sym in unknown:
            bp = broker_map[sym]
            direction = bp['side']  # 'long' or 'short'
            if direction not in ('long', 'short'):
                logger.warning(f"RECONCILE: Unknown side '{direction}' for {sym} — skipping")
                continue

            entry_price = bp['avg_entry_price']
            entry_time_str = datetime.now(ET).strftime('%Y-%m-%d %H:%M')

            # Step 1: Try to find actual entry from order history
            try:
                yesterday = (datetime.now(ET) - timedelta(days=2)).strftime('%Y-%m-%dT00:00:00Z')
                filled_orders = await asyncio.to_thread(
                    alpaca_get_filled_orders, sym, yesterday, 5)
                for order in filled_orders:
                    if order.get('filled_avg_price'):
                        entry_price = float(order['filled_avg_price'])
                        if order.get('filled_at'):
                            entry_time_str = order['filled_at'][:16].replace('T', ' ')
                        logger.info(f"RECONCILE: Found entry order for {sym} "
                                   f"@ ${entry_price:.2f} at {entry_time_str}")
                        break
            except Exception as e:
                logger.warning(f"RECONCILE: Order history lookup failed for {sym}: {e}")

            # Step 2: Look up gap context from daily_bars
            gap_ctx = self._lookup_gap_context(sym, entry_price, direction)

            if gap_ctx and gap_ctx.get('prev_close', 0) > 0:
                prev_close = gap_ctx['prev_close']
                gap_pct = abs(gap_ctx.get('gap_pct', 0))
                atr = gap_ctx.get('atr', 0)
                # Use adaptive stop logic if gap context available
                eff_stop_pct = compute_adaptive_stop_pct(self.config, gap_pct) if gap_pct > 0 else self.config.stop_pct
                if direction == 'short':
                    stop_price = entry_price * (1 + eff_stop_pct)
                    half_target = (entry_price + prev_close) / 2
                    full_target = prev_close
                else:
                    stop_price = entry_price * (1 - eff_stop_pct)
                    half_target = (entry_price + prev_close) / 2
                    full_target = prev_close
                logger.info(f"RECONCILE: {sym} gap context — gap {gap_pct:.1%}, "
                           f"prev_close ${prev_close:.2f}, ATR ${atr:.2f}, "
                           f"stop ${stop_price:.2f}")
            elif gap_ctx and gap_ctx.get('atr', 0) > 0:
                # No gap but have ATR — use 1.5x ATR safety stop
                atr = gap_ctx['atr']
                prev_close = gap_ctx.get('prev_close', entry_price)
                if direction == 'short':
                    stop_price = entry_price + (1.5 * atr)
                    half_target = entry_price - atr
                    full_target = entry_price - (2 * atr)
                else:
                    stop_price = entry_price - (1.5 * atr)
                    half_target = entry_price + atr
                    full_target = entry_price + (2 * atr)
                logger.warning(f"RECONCILE: {sym} no gap context — using 1.5x ATR "
                              f"safety stop @ ${stop_price:.2f} (ATR=${atr:.2f})")
            else:
                # Last resort — fixed percentage
                if direction == 'short':
                    stop_price = entry_price * (1 + self.config.stop_pct)
                    half_target = entry_price * 0.99
                    full_target = entry_price * 0.97
                    prev_close = entry_price * 0.97
                else:
                    stop_price = entry_price * (1 - self.config.stop_pct)
                    half_target = entry_price * 1.01
                    full_target = entry_price * 1.03
                    prev_close = entry_price * 1.03
                logger.warning(f"RECONCILE: {sym} NO context available — "
                              f"using fallback {self.config.stop_pct:.1%} stop")

            logger.warning(f"RECONCILE: Adopting broker {direction} {sym} "
                          f"({bp['qty']} shares @ ${entry_price:.2f})")
            self._add_message('warning',
                f'RECONCILE: Adopting {direction} {sym} ({bp["qty"]} shares) '
                f'stop=${stop_price:.2f}')

            pos = GapPosition(
                symbol=sym, shares=bp['qty'], entry_price=entry_price,
                stop_price=stop_price,
                half_target=half_target,
                full_target=full_target,
                prev_close=prev_close,
                entry_time=entry_time_str,
                remaining_shares=bp['qty'],
                entry_fill_price=entry_price,
                direction=direction,
                source='reconcile',
            )
            self.engine.positions[sym] = pos

            # Step 3: Place GTC broker-side stop immediately
            try:
                stop_result = await self._broker_place_stop(
                    sym, bp['qty'], stop_price, 0.003, direction)
                if 'error' not in stop_result:
                    pos.stop_order_id = stop_result.get('id', '')
                    logger.info(f"RECONCILE: GTC stop placed for {sym} @ ${stop_price:.2f}")
                else:
                    logger.warning(f"RECONCILE: Stop placement failed for {sym}: {stop_result}")
            except Exception as e:
                logger.warning(f"RECONCILE: Stop placement error for {sym}: {e}")

        # Quantity mismatches on shared positions
        shared = internal_syms & broker_syms
        for sym in shared:
            bp = broker_map[sym]
            pos = self.engine.positions[sym]
            if bp['qty'] != pos.remaining_shares:
                logger.warning(f"RECONCILE: {sym} qty mismatch — internal={pos.remaining_shares}, "
                              f"broker={bp['qty']}. Adopting broker qty.")
                self._add_message('warning',
                    f'RECONCILE: {sym} qty adjusted {pos.remaining_shares} → {bp["qty"]}')
                pos.remaining_shares = bp['qty']
                pos.shares = bp['qty']

        # Verify all positions have broker-side stops (safety net)
        for sym, pos in self.engine.positions.items():
            if not pos.stop_order_id:
                logger.warning(f"RECONCILE: {sym} has NO broker-side stop — placing safety stop")
                try:
                    stop_result = await self._broker_place_stop(
                        sym, pos.remaining_shares, pos.stop_price,
                        0.003, pos.direction)
                    if 'error' not in stop_result:
                        pos.stop_order_id = stop_result.get('id', '')
                        logger.info(f"RECONCILE: Safety stop placed for {sym} @ ${pos.stop_price:.2f}")
                except Exception as e:
                    logger.error(f"RECONCILE: CRITICAL — could not place stop for {sym}: {e}")
            else:
                # Verify existing stop order is still active on broker
                try:
                    order_data = await self._broker_get_order(pos.stop_order_id)
                    if order_data:
                        ost = order_data.get('status', '')
                        if ost in ('cancelled', 'canceled', 'expired', 'filled', 'rejected'):
                            logger.warning(f"RECONCILE: {sym} stop order {ost} — replacing")
                            stop_result = await self._broker_place_stop(
                                sym, pos.remaining_shares, pos.stop_price,
                                0.003, pos.direction)
                            if 'error' not in stop_result:
                                pos.stop_order_id = stop_result.get('id', '')
                except Exception as e:
                    logger.warning(f"RECONCILE: Could not verify stop for {sym}: {e}")

        # Sync equity with broker (ground truth)
        try:
            acct = await self._broker_get_account()
            if acct and acct.get('equity'):
                broker_equity = float(acct['equity'])
                if abs(broker_equity - self.engine.equity) > 1.0:
                    logger.info(f"RECONCILE: Equity sync ${self.engine.equity:,.2f} → ${broker_equity:,.2f} (broker)")
                    self.engine.equity = broker_equity
                    self.engine.peak_equity = max(self.engine.peak_equity, broker_equity)
        except Exception as e:
            logger.debug(f"RECONCILE: Equity sync failed: {e}")

        self._last_reconcile = _time.monotonic()
        if orphaned or unknown or any(
            broker_map.get(s, {}).get('qty', 0) != self.engine.positions.get(s, GapPosition(
                symbol='', shares=0, entry_price=0, stop_price=0,
                half_target=0, full_target=0, prev_close=0)).remaining_shares
            for s in shared
        ):
            self._save_state()

        logger.info(f"Reconciliation complete: {len(self.engine.positions)} positions, "
                   f"{len(orphaned)} orphaned, {len(unknown)} adopted")

    # -------------------------------------------------------------------------
    # Main Trading Loop
    # -------------------------------------------------------------------------

    def _build_llm_state(self, now: datetime) -> dict:
        """Build state dict for LLM supervisor context."""
        state = {
            'time_et': now.strftime('%H:%M:%S'),
            'day_of_week': now.strftime('%A'),
            'equity': self.engine.equity,
            'daily_pnl': self.engine.daily_stats.pnl,
            'daily_trades': self.engine.daily_stats.trades,
            'wins': self.engine.daily_stats.wins,
            'losses': self.engine.daily_stats.losses,
            'consecutive_losses': self.engine.daily_stats.consecutive_losses,
            'positions': {s: asdict(p) for s, p in self.engine.positions.items()},
            'candidates_count': len(self.candidates),
            'top_candidates': [asdict(c) for c in self.candidates[:10]],
            'last_scan_time': self.last_scan_time,
            'stopped_today': list(self.engine._stopped_today.keys()),
            'status': self.status,
            'recent_messages': [m['text'] for m in self.messages[-10:]],
            'recent_trades': [asdict(t) for t in self.engine.all_trade_log[-5:]],
            'peak_equity': self.engine.peak_equity,
            'config': {
                'stop_pct': self.config.stop_pct,
                'max_positions': self.config.max_positions,
                'gap_threshold': self.config.gap_threshold,
                'adaptive_stops': self.config.adaptive_stops,
                'reentry_enabled': self.config.reentry_enabled,
                'dd_circuit_breaker': self.config.dd_circuit_breaker,
                'dd_tier1_threshold': self.config.dd_tier1_threshold,
                'dd_tier2_threshold': self.config.dd_tier2_threshold,
                'dd_hard_stop': self.config.dd_hard_stop,
                'capital_partition': self.config.capital_partition,
                'gap_fade_capital_pct': self.config.gap_fade_capital_pct,
                'intraday_capital_pct': self.config.intraday_capital_pct,
                'gap_fade_max_positions': self.config.gap_fade_max_positions,
                'intraday_max_positions': self.config.intraday_max_positions,
            },
            'capital_partition': {
                'gap_fade_equity': round(self.engine.allocated_equity('gap_fade'), 2),
                'intraday_equity': round(self.engine.allocated_equity('intraday'), 2),
                'gap_fade_positions': self.engine.count_positions_by_source('gap_fade'),
                'intraday_positions': self.engine.count_positions_by_source('intraday'),
            } if self.config.capital_partition else None,
        }
        # Enrich with journal summary and indicator snapshot
        state['journal_summary'] = self.journal.get_summary(minutes=20)
        if self.indicator_engine and self.engine.positions:
            indicators = {}
            for sym in self.engine.positions:
                td = self.indicator_engine.get_data(sym)
                if td:
                    indicators[sym] = {k: round(v, 2) if isinstance(v, float) else v
                                       for k, v in td.items()}
            if indicators:
                state['indicators'] = indicators
        return state

    def _build_lessons_learned(self) -> str:
        """Analyze trade history and build a concise lessons-learned summary for LLM context.

        Returns a 5-10 line string summarizing patterns from all_trade_log.
        Cached for 5 minutes via _lessons_cache.
        """
        now_mono = _time.monotonic()
        if hasattr(self, '_lessons_cache') and self._lessons_cache:
            cached_time, cached_text = self._lessons_cache
            if now_mono - cached_time < 300:  # 5 min cache
                return cached_text

        trades = self.engine.all_trade_log
        if len(trades) < 3:
            return ''

        lines = ['## LESSONS FROM TRADE HISTORY']

        # Win rate by entry hour
        hour_wins = {}
        hour_total = {}
        for t in trades:
            try:
                h = int(t.entry_time.split(' ')[1].split(':')[0])
            except (IndexError, ValueError):
                continue
            hour_total[h] = hour_total.get(h, 0) + 1
            if t.pnl > 0:
                hour_wins[h] = hour_wins.get(h, 0) + 1
        if hour_total:
            parts = []
            for h in sorted(hour_total.keys()):
                wr = hour_wins.get(h, 0) / hour_total[h] * 100
                parts.append(f'{h}:00={wr:.0f}%({hour_total[h]})')
            lines.append(f'- Win rate by hour: {", ".join(parts)}')

        # Avg holding time: winners vs losers
        winner_mins = [t.holding_minutes for t in trades if t.pnl > 0 and t.holding_minutes > 0]
        loser_mins = [t.holding_minutes for t in trades if t.pnl <= 0 and t.holding_minutes > 0]
        if winner_mins and loser_mins:
            avg_w = sum(winner_mins) / len(winner_mins)
            avg_l = sum(loser_mins) / len(loser_mins)
            lines.append(f'- Avg hold: winners {avg_w:.0f} min, losers {avg_l:.0f} min')

        # P&L by exit reason
        reason_pnl = {}
        reason_cnt = {}
        for t in trades:
            r = t.exit_reason
            reason_pnl[r] = reason_pnl.get(r, 0) + t.pnl
            reason_cnt[r] = reason_cnt.get(r, 0) + 1
        if reason_pnl:
            parts = []
            for r in sorted(reason_pnl.keys(), key=lambda x: reason_pnl[x]):
                parts.append(f'{r}=${reason_pnl[r]:+,.0f}({reason_cnt[r]})')
            lines.append(f'- P&L by exit: {", ".join(parts)}')

        # Churning symbols (traded 3+ times with net loss)
        sym_pnl = {}
        sym_cnt = {}
        for t in trades:
            sym_pnl[t.symbol] = sym_pnl.get(t.symbol, 0) + t.pnl
            sym_cnt[t.symbol] = sym_cnt.get(t.symbol, 0) + 1
        churners = [(s, sym_cnt[s], sym_pnl[s]) for s in sym_pnl
                     if sym_cnt[s] >= 3 and sym_pnl[s] < 0]
        if churners:
            churners.sort(key=lambda x: x[2])
            parts = [f'{s}({cnt}x, ${pnl:+,.0f})' for s, cnt, pnl in churners[:5]]
            lines.append(f'- Churning symbols (net loss): {", ".join(parts)}')

        # Overall stats
        total = len(trades)
        wins = sum(1 for t in trades if t.pnl > 0)
        total_pnl = sum(t.pnl for t in trades)
        lines.append(f'- Overall: {total} trades, {wins/total*100:.0f}% win rate, ${total_pnl:+,.0f} total P&L')

        result = '\n'.join(lines)
        self._lessons_cache = (now_mono, result)
        return result

    async def _weekly_model_maintenance(self):
        """Rebuild LLM training data and model weekly (Friday after hours).

        Only runs if >= 20 new trades since last rebuild.
        """
        try:
            # Check if already rebuilt this week
            today_str = datetime.now(ET).strftime('%Y-%m-%d')
            if self._last_model_rebuild == today_str:
                return

            # Need enough trades to make rebuilding worthwhile
            total_trades = len(self.engine.all_trade_log)
            if total_trades < 20:
                logger.info(f"Model rebuild skipped: only {total_trades} trades (need 20+)")
                return

            logger.info(f"Starting weekly model maintenance ({total_trades} trades)")
            self._add_message('system', f'Weekly model rebuild starting ({total_trades} trades)')

            # Save state first
            self._save_state()

            # Generate training data
            import subprocess
            script_dir = os.path.dirname(os.path.abspath(__file__))
            gen_script = os.path.join(script_dir, 'generate_training_data.py')
            if os.path.exists(gen_script):
                result = await asyncio.to_thread(
                    subprocess.run,
                    ['python', gen_script],
                    cwd=script_dir,
                    capture_output=True, text=True, timeout=120)
                if result.returncode != 0:
                    logger.error(f"Training data generation failed: {result.stderr[:500]}")
                    await self.alerter.send('Model Rebuild Failed',
                        f'generate_training_data.py failed:\n{result.stderr[:200]}',
                        level='error')
                    return
                logger.info(f"Training data generated: {result.stdout[:200]}")

            # Rebuild Ollama model
            modelfile = os.path.join(script_dir, 'Modelfile.gapfade')
            if os.path.exists(modelfile):
                result = await asyncio.to_thread(
                    subprocess.run,
                    ['ollama', 'create', 'rudra', '-f', modelfile],
                    cwd=script_dir,
                    capture_output=True, text=True, timeout=300)
                if result.returncode != 0:
                    logger.error(f"Ollama model rebuild failed: {result.stderr[:500]}")
                    await self.alerter.send('Model Rebuild Failed',
                        f'ollama create failed:\n{result.stderr[:200]}',
                        level='error')
                    return
                logger.info(f"Ollama model rebuilt: {result.stdout[:200]}")

            self._last_model_rebuild = today_str
            self._add_message('system', f'Weekly model rebuild complete ({total_trades} trades)')
            await self.alerter.send('Model Rebuilt',
                f'Training data regenerated and model rebuilt\nTrades: {total_trades}',
                level='info')
            logger.info("Weekly model maintenance complete")

        except Exception as e:
            logger.error(f"Weekly model maintenance failed: {e}\n{traceback.format_exc()}")
            await self.alerter.send('Model Maintenance Error',
                f'{type(e).__name__}: {e}', level='error')

    def _is_market_day(self, now: datetime) -> tuple:
        """Check if today is a market trading day.

        Returns (is_market_day: bool, next_open: datetime).
        """
        # Weekend check
        if now.weekday() >= 5:
            days_until_monday = 7 - now.weekday()
            next_open = (now + timedelta(days=days_until_monday)).replace(
                hour=7, minute=0, second=0, microsecond=0)
            return False, next_open

        # US market holidays (fixed + observed)
        year = now.year
        holidays = set()

        # Fixed-date holidays
        fixed = [
            (1, 1),   # New Year's Day
            (6, 19),  # Juneteenth
            (7, 4),   # Independence Day
            (12, 25), # Christmas
        ]
        for m, d in fixed:
            dt = date(year, m, d)
            if dt.weekday() == 5:    # Saturday → observe Friday
                holidays.add(date(year, m, d - 1))
            elif dt.weekday() == 6:  # Sunday → observe Monday
                holidays.add(date(year, m, d + 1))
            else:
                holidays.add(dt)

        # MLK Day: 3rd Monday of January
        holidays.add(self._nth_weekday(year, 1, 0, 3))
        # Presidents' Day: 3rd Monday of February
        holidays.add(self._nth_weekday(year, 2, 0, 3))
        # Memorial Day: last Monday of May
        holidays.add(self._last_weekday(year, 5, 0))
        # Labor Day: 1st Monday of September
        holidays.add(self._nth_weekday(year, 9, 0, 1))
        # Thanksgiving: 4th Thursday of November
        holidays.add(self._nth_weekday(year, 11, 3, 4))

        # Good Friday (Easter - 2 days)
        holidays.add(self._good_friday(year))

        today = now.date()
        if today in holidays:
            # Find next non-holiday weekday
            next_day = now + timedelta(days=1)
            while next_day.weekday() >= 5 or next_day.date() in holidays:
                next_day += timedelta(days=1)
            next_open = next_day.replace(hour=7, minute=0, second=0, microsecond=0)
            return False, next_open

        return True, now

    @staticmethod
    def _nth_weekday(year: int, month: int, weekday: int, n: int) -> date:
        """Get the nth occurrence of a weekday in a month (weekday: 0=Mon, 3=Thu)."""
        first = date(year, month, 1)
        day_of_week = first.weekday()
        diff = (weekday - day_of_week) % 7
        return first + timedelta(days=diff + 7 * (n - 1))

    @staticmethod
    def _last_weekday(year: int, month: int, weekday: int) -> date:
        """Get the last occurrence of a weekday in a month."""
        if month == 12:
            last_day = date(year + 1, 1, 1) - timedelta(days=1)
        else:
            last_day = date(year, month + 1, 1) - timedelta(days=1)
        diff = (last_day.weekday() - weekday) % 7
        return last_day - timedelta(days=diff)

    @staticmethod
    def _good_friday(year: int) -> date:
        """Compute Good Friday using anonymous Gregorian algorithm for Easter."""
        a = year % 19
        b, c = divmod(year, 100)
        d, e = divmod(b, 4)
        f = (b + 8) // 25
        g = (b - f + 1) // 3
        h = (19 * a + b - d - g + 15) % 30
        i, k = divmod(c, 4)
        l = (32 + 2 * e + 2 * i - h - k) % 7
        m = (a + 11 * h + 22 * l) // 451
        month, day = divmod(h + l - 7 * m + 114, 31)
        easter = date(year, month, day + 1)
        return easter - timedelta(days=2)

    async def _trading_loop(self):
        """Main trading loop — LLM-driven when enabled, schedule-based fallback.

        When LLM supervisor is active, it decides every action (scan, enter,
        monitor, standdown). EOD close is handled by independent _eod_watchdog
        task — this loop only respects the circuit breaker flag.
        """
        # Track what has been done today (reset on new date) — used by fallback schedule
        _done_date = ''
        _did_scan_7am = False
        _did_scan_925 = False
        _did_enter = False
        _did_close_on_open = False

        try:
            while self.status != 'stopped':
              try:
                self._last_loop_heartbeat = _time.monotonic()
                now = datetime.now(ET)
                today = now.strftime('%Y-%m-%d')

                # State persistence heartbeat: force save if stale >5 min
                if (_time.monotonic() - self._last_state_save_time > 300
                        and self.status in ('trading', 'scanning')):
                    logger.warning("State persistence stale (>5 min) — forcing save")
                    self._save_state()

                # Reset flags on new day
                if today != _done_date:
                    _done_date = today
                    _did_scan_7am = False
                    _did_scan_925 = False
                    _did_enter = False
                    _did_close_on_open = False
                    # Reset exhaustion entry state for new day
                    self._opening_ranges.clear()
                    self._exhaustion_signals.clear()
                    self._exhaustion_entered.clear()
                    self._last_perf_snapshot_hour = -1

                # Hourly performance snapshot (9:30-16:00, once per hour)
                if (now.hour >= 10 and now.hour <= 15
                        and now.hour != self._last_perf_snapshot_hour):
                    _market_hours = (now.hour > 9 or (now.hour == 9 and now.minute >= 30))
                    if _market_hours:
                        self._last_perf_snapshot_hour = now.hour
                        self._record_performance_snapshot('hourly')

                # ── SWING ENGINE (weekly scan + daily entry checks) ──

                # Swing weekly scan: Monday 7 AM or if stale (>5 days since last scan)
                if self._swing_enabled:
                    _scan_stale = False
                    if self._swing_last_scan:
                        try:
                            _last_scan_dt = datetime.strptime(self._swing_last_scan, '%Y-%m-%d')
                            _scan_stale = (now.replace(tzinfo=None) - _last_scan_dt).days > 5
                        except ValueError:
                            _scan_stale = True
                    else:
                        _scan_stale = True

                    if ((now.weekday() == 0 and now.hour == 7 and self._swing_last_scan != today)
                            or _scan_stale):
                        try:
                            await self._run_swing_scan()
                        except Exception as e:
                            logger.error("Swing scan error: %s", e, exc_info=True)

                    # Swing daily entry check (10:00 AM - 3:00 PM)
                    _market_open = (now.hour > 9 or (now.hour == 9 and now.minute >= 30))
                    if _market_open and 10 <= now.hour < 15:
                        try:
                            await self._check_swing_entries()
                        except Exception as e:
                            logger.error("Swing entry check error: %s", e, exc_info=True)

                    # Swing exit monitoring (during market hours)
                    if _market_open and now.hour < 16:
                        try:
                            await self._check_swing_exits()
                        except Exception as e:
                            logger.error("Swing exit check error: %s", e, exc_info=True)

                # ── SAFETY NETS (always active, LLM cannot override) ──

                # Before pre-market (before 7 AM) — sleep
                if now.hour < 7:
                    self.status = 'waiting'
                    await broadcast({'type': 'live_status', 'status': 'waiting'})
                    await asyncio.sleep(60)  # Check every minute before 7 AM
                    continue

                # Weekend / holiday check — sleep until next market day
                is_market, next_open = self._is_market_day(now)
                if not is_market:
                    self.status = 'waiting'
                    await broadcast({'type': 'live_status', 'status': 'waiting'})
                    self._add_message('info',
                        f'Market closed ({now.strftime("%A")}). '
                        f'Next open: {next_open.strftime("%a %b %d %H:%M")}')
                    # Sleep in 5-minute chunks (long sleeps drift)
                    await asyncio.sleep(300)
                    continue

                # Close-on-open: liquidate positions that failed to close yesterday
                _market_is_open = (now.hour > 9 or (now.hour == 9 and now.minute >= 30))
                if _market_is_open and not _did_close_on_open:
                    coo_syms = [sym for sym, pos in self.engine.positions.items()
                                if pos.close_on_open]
                    if coo_syms:
                        logger.info(f"Close-on-open: liquidating {len(coo_syms)} overnight positions: {coo_syms}")
                        self._add_message('system',
                            f'Close-on-open: liquidating {len(coo_syms)} positions from yesterday: {coo_syms}')
                        for sym in coo_syms:
                          try:
                            async with self._position_lock:
                                pos = self.engine.positions.get(sym)
                                if pos is None:
                                    continue
                                # Get current price
                                price = 0.0
                                try:
                                    snap_prices = await self._broker_get_prices([sym])
                                    price = snap_prices.get(sym, 0.0)
                                except Exception:
                                    pass
                                if price <= 0:
                                    price = pos.entry_price
                                exit_signal = {'reason': 'eod', 'shares': pos.remaining_shares,
                                               'is_full_close': True, 'trigger_price': price}
                                trade = await self._execute_exit(sym, exit_signal, price)
                            if trade:
                                self._add_message('exit',
                                    f'Close-on-open: {sym} closed @ ${trade.exit_price:.2f} '
                                    f'P&L: ${trade.pnl:+,.2f}')
                                await broadcast({'type': 'trade', 'trades': [asdict(trade)]})
                            else:
                                # Last resort: broker close position API
                                result = await self._broker_close_position(sym)
                                if 'error' not in result:
                                    logger.info(f"Close-on-open fallback: {sym} closed via broker API")
                                    pos = self.engine.positions.get(sym)
                                    if pos:
                                        fill_price = float(result.get('filled_avg_price', 0)) or price
                                        trade = self.engine.confirm_exit(
                                            sym, pos.remaining_shares, fill_price, 'eod', now)
                                        if trade:
                                            self._add_message('exit',
                                                f'Close-on-open fallback: {sym} @ ${fill_price:.2f} '
                                                f'P&L: ${trade.pnl:+,.2f}')
                                else:
                                    logger.error(f"Close-on-open FAILED for {sym}: {result.get('error')}")
                                    self._add_message('error', f'Close-on-open FAILED for {sym} — manual action needed')
                          except Exception as e:
                            logger.error(f"Close-on-open exception for {sym}: {e}")
                            self._add_message('error', f'Close-on-open exception for {sym}: {e}')
                        _did_close_on_open = True
                        self._save_state()
                    else:
                        _did_close_on_open = True  # nothing to close

                # EOD close is handled by independent _eod_watchdog task.
                # Trading loop just respects the circuit breaker flag.
                if self._trading_halted:
                    if self.engine.positions:
                        # Watchdog is handling close — yield control
                        await asyncio.sleep(5)
                        continue
                    # No positions, halted — fall through to after-hours sleep

                # After hours (4 PM+) — save state, sleep until next morning
                if now.hour >= 16:
                    # Reset circuit breaker for next day
                    self._trading_halted = False

                    # If watchdog somehow missed positions, last-resort close
                    if self.engine.positions:
                        logger.error("EOD WATCHDOG FAILURE: positions still open at 4 PM — emergency close")
                        self._add_message('error', 'WATCHDOG FAILURE: Positions open after hours — force closing')
                        await self.alerter.send('EOD WATCHDOG FAILURE',
                            f'Positions still open at {now.strftime("%H:%M")} after watchdog should have closed them.\n'
                            f'Symbols: {list(self.engine.positions.keys())}',
                            level='error')
                        await self._eod_close()

                    # Send daily P&L summary (Telegram + Email)
                    stats = self.engine.daily_stats
                    today_trades = [t for t in self.engine.all_trade_log
                                    if hasattr(t, 'exit_time') and t.exit_time
                                    and t.exit_time.startswith(today)]
                    wins = sum(1 for t in today_trades if t.pnl > 0)
                    losses = len(today_trades) - wins
                    wr = wins / len(today_trades) * 100 if today_trades else 0

                    # Use RudraAlerter's daily_summary if available
                    if hasattr(self.alerter, 'daily_summary'):
                        swing_positions = [s for s, p in self.engine.positions.items()
                                           if getattr(p, 'strategy_id', '') == 'swing_stage2']
                        try:
                            await self.alerter.daily_summary(
                                trades=len(today_trades),
                                pnl=stats.pnl,
                                equity=self.engine.equity,
                                win_rate=wr,
                                positions=swing_positions,
                            )
                        except Exception as e:
                            logger.warning(f"Daily summary alert failed: {e}")
                    else:
                        # Fallback to basic alert
                        trade_details = ', '.join(
                            f'{t.symbol} {"+" if t.pnl >= 0 else ""}${t.pnl:.0f}'
                            for t in today_trades[:10])
                        await self.alerter.send(
                            f'Daily Summary \u2014 {now.strftime("%a %b %d")}',
                            f'Equity: ${self.engine.equity:,.2f}\n'
                            f'Today: {"+" if stats.pnl >= 0 else ""}${stats.pnl:.2f} ({wins}W/{losses}L)\n'
                            f'Trades: {trade_details or "none"}',
                            level='summary')

                    # Store today's closing bars for the full universe
                    # so tomorrow's gap scanner can use prev_close from DB
                    await self._store_eod_bars(today)

                    # Weekly model maintenance (Friday after hours)
                    if now.weekday() == 4:
                        await self._weekly_model_maintenance()

                    self._save_state()
                    self.engine.reset_daily()
                    self.event_detector.reset_daily()
                    self.status = 'waiting'
                    await broadcast({'type': 'live_status', 'status': 'waiting'})
                    self._add_message('info', 'After hours — sleeping until 7:00 AM ET')
                    # Sleep in 5-minute chunks (long sleeps drift/stall)
                    await asyncio.sleep(300)
                    continue

                # ── LLM SUPERVISOR MODE ──
                if self.llm_supervisor and self.llm_supervisor.is_available():
                    # Update lessons learned from trade history
                    self.llm_supervisor.lessons_context = self._build_lessons_learned()

                    # Morning briefing (once per day, after first scan)
                    if (self._morning_briefing_done != today
                            and (self.candidates or now.hour >= 9)):
                        state = self._build_llm_state(now)
                        briefing = await self.llm_supervisor.morning_briefing(
                            state, event_queue=self._event_bus)
                        if briefing:
                            self._morning_briefing_done = today
                            self._add_message('conversation',
                                f'BOT: Morning briefing | RUDRA: {briefing}')
                            await broadcast({'type': 'conversation',
                                'speaker': 'rudra', 'text': briefing})

                    # Tier 4: Human escalation — Telegram alert + standdown
                    tier4_events = [e for e in self._event_bus._queue if e.tier >= 4]
                    if tier4_events:
                        for t4 in tier4_events:
                            await self.alerter.send(
                                f'HUMAN ESCALATION: {t4.event_type}',
                                f'{t4.description}\n'
                                f'Equity: ${self.engine.equity:,.2f}, '
                                f'Daily P&L: ${self.engine.daily_stats.pnl:+,.2f}',
                                level='error', throttle_key=f'tier4:{t4.event_type}')
                            self.journal.log('action', 'event_detector',
                                f'TIER 4 ESCALATION: {t4.description}',
                                data=t4.data)
                        self._add_message('error',
                            f'HUMAN ESCALATION: {tier4_events[0].description} — '
                            f'Telegram alert sent, entering standdown')

                    # Tier 3+ urgent event — immediate LLM consultation
                    if self._event_bus.has_urgent() or self._urgent_llm_event:
                        self._urgent_llm_event = False
                        # Peek at urgent events for prompt context
                        urgent_texts = [e.as_text() for e in self._event_bus._queue if e.tier >= 3][-3:]
                        if not urgent_texts:
                            urgent_texts = [e.as_text() for e in self._event_bus._queue][-3:]
                        state = self._build_llm_state(now)
                        urgent_prompt = (
                            f"Urgent situation. {' '.join(urgent_texts)}\n"
                            f"Current equity: ${state['equity']:,.2f}, "
                            f"daily P&L: ${state['daily_pnl']:+,.2f}, "
                            f"consecutive losses: {state['consecutive_losses']}.\n"
                            f"What's your read? Analyze the situation — is this a pattern of losses or isolated? "
                            f"Should we stand down, tighten up, or keep trading?\n\n"
                            f"Share your assessment, then end with JSON: {self.llm_supervisor._ACTION_SCHEMA}"
                        )
                        system_prompt = self.llm_supervisor._SYSTEM_PROMPT
                        if self.llm_supervisor.lessons_context:
                            system_prompt += '\n\n' + self.llm_supervisor.lessons_context
                        self.journal.log('observation', 'event_detector',
                            f'Urgent event triggered LLM consultation: {"; ".join(urgent_texts)}')
                        raw = await self.llm_supervisor._call_llm(
                            system_prompt, urgent_prompt,
                            use_memory=True, record_exchange=True,
                            conversation_role='urgent_event',
                            event_queue=self._event_bus)
                        if raw:
                            self._add_message('conversation',
                                f'BOT: Urgent event | RUDRA: {raw}')
                            await broadcast({'type': 'conversation',
                                'speaker': 'rudra', 'text': raw})
                            self.journal.log('reasoning', 'llm_rudra',
                                raw[:500], llm_call=True)
                            # Parse action if present
                            parsed = self.llm_supervisor._parse_json(raw)
                            if isinstance(parsed, dict) and parsed.get('action') == 'standdown':
                                standdown_min = parsed.get('standdown_minutes', 15)
                                self.status = 'standdown'
                                await broadcast({'type': 'live_status', 'status': 'standdown'})
                                self._add_message('llm', f'Standing down {standdown_min}m after urgent event')
                                self.journal.log('action', 'llm_rudra',
                                    f'Standing down {standdown_min}m after urgent event')
                                await asyncio.sleep(min(standdown_min * 60, 900))
                                self.status = 'scanning'
                                await broadcast({'type': 'live_status', 'status': 'scanning'})
                                continue

                    state = self._build_llm_state(now)

                    # ── THROTTLE: skip decide_action if nothing changed ──
                    _now_mono = _time.monotonic()
                    _state_hash = (f"{len(self.engine.positions)}|"
                                   f"{state.get('candidates_count', 0)}|"
                                   f"{state['wins']}|{state['losses']}|"
                                   f"{self.status}")
                    _state_changed = (_state_hash != self._last_llm_state_hash)
                    _time_elapsed = (_now_mono - self._last_llm_decide >= self._LLM_DECIDE_INTERVAL)
                    _has_events = bool(self._event_bus)

                    if _state_changed or _time_elapsed or _has_events:
                        # Ask Rudra — something meaningful changed or enough time passed
                        self._last_llm_decide = _now_mono
                        self._last_llm_state_hash = _state_hash

                        decision = await self.llm_supervisor.decide_action(
                            state, event_queue=self._event_bus)
                        action = decision.get('action', 'monitor')
                        reasoning = decision.get('reasoning', '')
                        # Use full analysis text if available, fall back to JSON reasoning
                        rudra_analysis = decision.get('_analysis', reasoning)
                        rudra_display = rudra_analysis if rudra_analysis else reasoning

                        # ── MECHANICAL GUARD: no entries before market open ──
                        _market_open = (now.hour > 9 or (now.hour == 9 and now.minute >= 30))
                        if action == 'enter' and not _market_open:
                            self._add_message('conversation',
                                f'BOT: What should we do? | RUDRA: Enter — but market not open yet '
                                f'({now.strftime("%H:%M")} ET), overriding to wait')
                            action = 'wait'
                            reasoning = 'Pre-market: waiting for 9:30 AM open'
                            rudra_display = reasoning

                        # Show bot<->Rudra exchange in activity feed
                        _bot_context = (f'{len(self.engine.positions)} positions, '
                                        f'{state.get("candidates_count", 0)} candidates'
                                        if self.engine.positions or state.get('candidates_count')
                                        else state['status'])
                        self._add_message('conversation',
                            f'BOT: {_bot_context} | RUDRA: [{action}] {rudra_display}')
                        await broadcast({'type': 'conversation',
                            'speaker': 'rudra',
                            'text': f'[{action}] {rudra_display}'})
                        # Journal: log LLM decision
                        _jtype = 'action' if action in ('enter', 'scan', 'standdown') else 'no_action'
                        self.journal.log(_jtype, 'llm_rudra',
                            f'[{action}] {rudra_display[:200]}', llm_call=True)
                    else:
                        # Nothing changed — silently continue with last action
                        action = 'monitor'

                    if action == 'scan':
                        await self._run_scan()
                        await asyncio.sleep(15)
                    elif action == 'enter':
                        llm_symbols = decision.get('enter_symbols')
                        size_mult = decision.get('position_size_mult', 1.0)
                        await self._enter_positions(llm_symbols=llm_symbols, size_mult=size_mult)
                        await asyncio.sleep(15)
                    elif action == 'standdown':
                        standdown_min = decision.get('standdown_minutes', 30)
                        self.status = 'standdown'
                        await broadcast({'type': 'live_status', 'status': 'standdown'})
                        self._add_message('llm', f'Standing down for {standdown_min} minutes')
                        await asyncio.sleep(min(standdown_min * 60, 1800))
                        self.status = 'scanning'
                        await broadcast({'type': 'live_status', 'status': 'scanning'})
                    elif action == 'wait':
                        new_status = 'trading' if self.engine.positions else 'scanning'
                        if self.status != new_status:
                            self.status = new_status
                            await broadcast({'type': 'live_status', 'status': new_status})
                        # Intraday scanning during wait (LLM mode)
                        if (self.config.intraday_enabled and self._intraday_strategies
                                and (now.hour, now.minute) >= (9, 45)
                                and (now.hour, now.minute) <= (15, 30)):
                            await self._intraday_scan_and_enter()
                        await asyncio.sleep(30)
                    else:  # monitor
                        if self.engine.positions:
                            if self.status != 'trading':
                                self.status = 'trading'
                                await broadcast({'type': 'live_status', 'status': 'trading'})
                            await self._check_positions()
                            # Pyramid check (add to winners)
                            if self.config.pyramid_enabled and self.engine.positions:
                                await self._check_pyramid_opportunities()
                            if _time.monotonic() - self._last_reconcile > self.RECONCILE_INTERVAL:
                                await self._reconcile_with_broker()
                            # Autonomous review: periodic portfolio self-check
                            await self._execute_scheduled_reflection()
                        else:
                            if self.status != 'scanning':
                                self.status = 'scanning'
                                await broadcast({'type': 'live_status', 'status': 'scanning'})
                        # Intraday scanning during monitor (LLM mode)
                        if (self.config.intraday_enabled and self._intraday_strategies
                                and (now.hour, now.minute) >= (9, 45)
                                and (now.hour, now.minute) <= (15, 30)):
                            await self._intraday_scan_and_enter()
                        await asyncio.sleep(15)
                    continue

                # ── FALLBACK: original schedule (LLM disabled or circuit open) ──
                if self.llm_supervisor and not self.llm_supervisor.is_available():
                    self._add_message('llm_fallback', 'Rudra unavailable (circuit breaker), using rules schedule')
                    await self.alerter.send('Rudra Circuit Breaker',
                        f'Rudra unavailable — falling back to rules schedule\n'
                        f'Failures: {self.llm_supervisor._failure_count}/{self.llm_supervisor._max_failures}',
                        level='warning', throttle_key='llm_circuit')

                # Pre-market scan (7:00+ AM, once per day)
                if 7 <= now.hour < 9 and not _did_scan_7am:
                    _did_scan_7am = True
                    # Verify yesterday's daily bars before scanning
                    await self._verify_daily_bars()
                    await self._run_scan()
                    await asyncio.sleep(30)
                    continue

                # Re-scan at 9:25+ AM (once per day, refine candidates)
                if now.hour == 9 and now.minute >= 25 and not _did_scan_925:
                    _did_scan_925 = True
                    # Also verify daily bars here in case bot started after 9 AM
                    if not _did_scan_7am:
                        _did_scan_7am = True
                        await self._verify_daily_bars()
                    await self._run_scan()
                    # Subscribe candidates to tick streamer for exhaustion entry
                    # (needs VWAP/RSI data from indicator engine before entry)
                    if self.candidates and self.streamer:
                        cand_syms = [c.symbol for c in self.candidates[:15]]
                        await self.streamer.add_symbols(
                            cand_syms,
                            priority_symbols=set(cand_syms))
                        logger.info(f"Subscribed {len(cand_syms)} candidates to tick streamer for exhaustion monitoring")
                    elif self.candidates and not self.streamer:
                        # Start streamer with candidates
                        cand_syms = [c.symbol for c in self.candidates[:15]]
                        self.streamer = self._broker_make_streamer(cand_syms, on_tick=self._on_tick)
                        await self.streamer.start()
                        logger.info(f"Started tick streamer for {len(cand_syms)} candidates")
                    # Fast-poll until entry window opens
                    _ew = self.strategy.get_entry_window() if self.strategy else None
                    _ew_min = _ew[1] if _ew else 31
                    _seconds_to_entry = max(0, (_ew_min - now.minute) * 60 - now.second)
                    if _seconds_to_entry > 0:
                        self._add_message('info', f'Scan done — waiting {_seconds_to_entry}s for 9:{_ew_min:02d} entry')
                        await asyncio.sleep(min(_seconds_to_entry, 5))
                    continue

                # Market open — enter positions (strategy controls entry window)
                _entry_window = self.strategy.get_entry_window() if self.strategy else None
                if _entry_window:
                    _entry_start_h, _entry_start_m, _cutoff_h, _cutoff_m = _entry_window
                else:
                    _entry_start_h, _entry_start_m = 9, 31
                    _cutoff_h = self.config.entry_cutoff_hour
                    _cutoff_m = self.config.entry_cutoff_min
                _before_cutoff = (now.hour < _cutoff_h or
                                  (now.hour == _cutoff_h and now.minute < _cutoff_m))
                _after_entry_start = (now.hour > _entry_start_h or
                                      (now.hour == _entry_start_h and now.minute >= _entry_start_m))
                if _after_entry_start and _before_cutoff:
                    if self.status in ('scanning', 'waiting', 'trading'):
                        # If no candidates (e.g. mid-day restart), scan first
                        if not self.candidates:
                            self._add_message('scan', 'No candidates cached — running fresh scan before entry')
                            await self._run_scan()

                        # Build Opening Range (9:30-9:45)
                        if now.hour == 9 and now.minute < 45:
                            self._build_opening_ranges()

                        # Exhaustion entry scan (9:45 onward, continuous)
                        if now.hour > 9 or (now.hour == 9 and now.minute >= 45):
                            self._build_opening_ranges()  # finalize OR
                            await self._exhaustion_entry_scan()
                            if self.engine.positions:
                                self.status = 'trading'
                                await broadcast({'type': 'live_status', 'status': 'trading'})

                        await asyncio.sleep(15)  # Check every 15 seconds
                        continue

                # During trading hours — monitor every 15 seconds
                if 9 <= now.hour < 16 and self.status in ('trading', 'scanning'):
                    if self.engine.positions:
                        if self.status != 'trading':
                            self.status = 'trading'
                            await broadcast({'type': 'live_status', 'status': 'trading'})
                        await self._check_positions()
                        # Pyramid check (add to winners)
                        if self.config.pyramid_enabled and self.engine.positions:
                            await self._check_pyramid_opportunities()
                        if _time.monotonic() - self._last_reconcile > self.RECONCILE_INTERVAL:
                            await self._reconcile_with_broker()
                        await self._execute_scheduled_reflection()
                    else:
                        # No positions — make sure we're in 'scanning' state
                        if self.status != 'scanning':
                            self.status = 'scanning'
                            await broadcast({'type': 'live_status', 'status': 'scanning'})
                    # Intraday scanning during market hours (fallback schedule)
                    if (self.config.intraday_enabled and self._intraday_strategies
                            and (now.hour, now.minute) >= (9, 45)
                            and (now.hour, now.minute) <= (15, 30)):
                        await self._intraday_scan_and_enter()
                    await asyncio.sleep(15)
                    continue

                # Intraday scanning during idle periods (after gap cutoff, no positions)
                if (self.config.intraday_enabled and self._intraday_strategies
                        and (now.hour, now.minute) >= (9, 45)
                        and (now.hour, now.minute) <= (15, 30)
                        and self.status not in ('stopped', 'standdown')):
                    await self._intraday_scan_and_enter()

                # Waiting for next event
                await asyncio.sleep(30)

              except asyncio.CancelledError:
                raise
              except Exception as e:
                logger.error(f"Trading loop iteration error: {e}\n{traceback.format_exc()}")
                self._add_message('error', f'Loop error (retrying): {e}')
                await asyncio.sleep(15)  # backoff before retrying

        except asyncio.CancelledError:
            raise
        except Exception as e:
            logger.error(f"Trading loop fatal error: {e}\n{traceback.format_exc()}")
            self._add_message('error', f'Trading loop fatal error: {e}')
            await self.alerter.send('Trading Loop Error',
                f'{type(e).__name__}: {e}', level='error')

    async def _run_scan(self):
        """Run the pre-market scanner (non-blocking)."""
        self._add_message('scan', 'Running pre-market scan...')
        await broadcast({'type': 'live_status', 'status': 'scanning'})

        self.candidates, universe_size = await asyncio.to_thread(self.scanner.scan_premarket)
        self.last_scan_time = datetime.now(ET).strftime('%H:%M:%S')

        # Catalyst detection — classify gaps before ranking
        if self.config.catalyst_enabled and self.candidates:
            try:
                await detect_catalysts(self.candidates, self.config)
                self._apply_catalyst_scores()
                self.candidates.sort(key=lambda c: c.score, reverse=True)
                cat_counts = defaultdict(int)
                for c in self.candidates:
                    cat_counts[c.catalyst or 'noise'] += 1
                self._add_message('catalyst', f'Catalyst scan: {dict(cat_counts)}')
            except Exception as e:
                logger.warning(f"Catalyst detection failed (non-fatal): {e}")

        # Strategy plugin: filter and re-score candidates
        if self.strategy and self.candidates:
            pre_count = len(self.candidates)
            filtered = []
            for c in self.candidates:
                ok, reason = self.strategy.filter_candidate(asdict(c))
                if ok:
                    # Strategy scoring override
                    new_score = self.strategy.score_candidate(asdict(c))
                    if new_score is not None:
                        c.score = new_score
                    filtered.append(c)
                else:
                    _log_rejected_candidate(c, 'strategy_filter', reason,
                                            self.config.active_strategy)
                    logger.debug(f"Strategy filtered {c.symbol}: {reason}")
            if len(filtered) < pre_count:
                self._add_message('strategy',
                    f'{self.strategy.name}: filtered {pre_count - len(filtered)} candidates '
                    f'({len(filtered)} remain)')
            self.candidates = filtered
            self.candidates.sort(key=lambda c: c.score, reverse=True)

        self._add_message('scan', f'Found {len(self.candidates)} candidates from {universe_size} symbols', {
            'candidates': [asdict(c) for c in self.candidates[:10]]
        })
        await broadcast({
            'type': 'scan_results',
            'candidates': [asdict(c) for c in self.candidates[:10]],
            'scan_time': self.last_scan_time,
            'universe_size': universe_size,
        })

        # LLM candidate evaluation (non-fatal, best-effort)
        if self.llm_supervisor and self.llm_supervisor.is_available() and self.candidates:
            try:
                regime_info = None
                try:
                    regime = await fetch_market_regime_live(self.config)
                    if regime:
                        regime_info = {'spy_gap_pct': regime.spy_gap_pct, 'vix_level': regime.vix_level}
                except Exception:
                    pass
                evals = await self.llm_supervisor.evaluate_candidates(
                    [asdict(c) for c in self.candidates[:15]], regime=regime_info)
                if evals:
                    skip_syms = {e['symbol'] for e in evals
                                 if isinstance(e, dict) and e.get('action') == 'skip'}
                    trade_syms = [e for e in evals
                                  if isinstance(e, dict) and e.get('action') == 'trade']
                    # Build conversation summary
                    trade_names = ', '.join(e['symbol'] for e in trade_syms[:5]) if trade_syms else 'none'
                    skip_names = ', '.join(list(skip_syms)[:5]) if skip_syms else 'none'
                    self._add_message('conversation',
                        f'BOT: {len(self.candidates)} candidates from scan | '
                        f'RUDRA: Trade {trade_names}; skip {skip_names}')
                    await broadcast({'type': 'conversation',
                        'speaker': 'rudra',
                        'text': f'Candidates: trade {trade_names}, skip {skip_names}'})
                    if skip_syms:
                        before = len(self.candidates)
                        for c in self.candidates:
                            if c.symbol in skip_syms:
                                _log_rejected_candidate(c, 'llm_skip', 'LLM supervisor skip',
                                                        self.config.active_strategy)
                        self.candidates = [c for c in self.candidates if c.symbol not in skip_syms]
            except Exception as e:
                logger.warning(f"Rudra candidate evaluation failed (non-fatal): {e}")

    def _apply_catalyst_scores(self):
        """Adjust candidate scores based on catalyst classification.

        Earnings handling: if catalyst_skip_earnings=True, hard-skip (score=-999).
        Otherwise, apply a heavy penalty (catalyst_earnings_penalty, default 40).
        This lets high-scoring candidates survive even with an earnings tag,
        which is important because yfinance earnings data is often inaccurate.
        """
        filtered = []
        for c in self.candidates:
            if c.catalyst == 'earnings':
                if self.config.catalyst_skip_earnings:
                    c.score = -999
                    _log_rejected_candidate(c, 'catalyst',
                        f'earnings gap: {c.catalyst_detail}', self.config.active_strategy)
                    self._add_message('catalyst',
                        f'{c.symbol}: SKIP — earnings gap ({c.catalyst_detail})')
                    continue
                else:
                    penalty = self.config.catalyst_earnings_penalty
                    c.score -= penalty
                    self._add_message('catalyst',
                        f'{c.symbol}: -{penalty} penalty (earnings: {c.catalyst_detail})')
            elif c.catalyst == 'ma':
                c.score = -999
                _log_rejected_candidate(c, 'catalyst',
                    f'M&A gap: {c.catalyst_detail}', self.config.active_strategy)
                self._add_message('catalyst',
                    f'{c.symbol}: SKIP — M&A gap ({c.catalyst_detail})')
                continue
            elif c.catalyst == 'fda':
                c.score -= 20
                self._add_message('catalyst',
                    f'{c.symbol}: -20 penalty (FDA: {c.catalyst_detail})')
            elif c.catalyst in ('upgrade', 'downgrade'):
                c.score -= self.config.catalyst_news_penalty
                self._add_message('catalyst',
                    f'{c.symbol}: -{self.config.catalyst_news_penalty} penalty '
                    f'({c.catalyst}: {c.catalyst_detail})')
            elif c.catalyst == 'offering':
                c.score += self.config.catalyst_noise_bonus
                self._add_message('catalyst',
                    f'{c.symbol}: +{self.config.catalyst_noise_bonus} bonus '
                    f'(offering = bearish catalyst)')
            else:
                # No catalyst = clean noise gap
                c.score += self.config.catalyst_noise_bonus
            filtered.append(c)
        self.candidates = filtered

    # -------------------------------------------------------------------------
    # Entry Flow — with fill verification
    # -------------------------------------------------------------------------

    def _build_opening_ranges(self):
        """Build Opening Range for each gap candidate.

        Uses multiple data sources:
        1. Tick streamer latest_prices (if subscribed)
        2. Indicator engine bar history (if available)
        3. Candidate's premarket_price as fallback (from scan snapshot)

        After 9:45, marks all ranges as 'built' even if only using snapshot data.
        The OR high is the key level — stop goes above it.
        """
        if not self.candidates:
            return

        now = datetime.now(ET)
        is_or_complete = now.hour > 9 or (now.hour == 9 and now.minute >= 45)

        for cand in self.candidates:
            sym = cand.symbol
            if sym in self._opening_ranges and self._opening_ranges[sym].get('built'):
                continue

            # Try to get price from streamer
            price = 0.0
            if self.streamer and hasattr(self.streamer, 'latest_prices'):
                price = self.streamer.latest_prices.get(sym, 0)

            # Try indicator engine for bar history
            tick_data = self.indicator_engine.get_data(sym) if self.indicator_engine else None
            if tick_data:
                bar_history = tick_data.get('bar_history', [])
                for bar in bar_history:
                    h = getattr(bar, 'high', 0) if hasattr(bar, 'high') else 0
                    l = getattr(bar, 'low', 0) if hasattr(bar, 'low') else 0
                    if h > 0:
                        if sym not in self._opening_ranges:
                            self._opening_ranges[sym] = {'high': h, 'low': l or h, 'built': False}
                        else:
                            self._opening_ranges[sym]['high'] = max(self._opening_ranges[sym]['high'], h)
                            if l > 0:
                                self._opening_ranges[sym]['low'] = min(self._opening_ranges[sym]['low'], l)

            # Use streamer price to update OR
            if price > 0:
                if sym not in self._opening_ranges:
                    self._opening_ranges[sym] = {'high': price, 'low': price, 'built': False}
                else:
                    self._opening_ranges[sym]['high'] = max(self._opening_ranges[sym]['high'], price)
                    self._opening_ranges[sym]['low'] = min(self._opening_ranges[sym]['low'], price)

            # Fallback: use candidate's premarket price (from scan snapshot)
            if sym not in self._opening_ranges and cand.premarket_price > 0:
                # Use the gap open as the OR high (conservative — actual high is likely higher)
                self._opening_ranges[sym] = {
                    'high': cand.premarket_price * 1.005,  # assume 0.5% spike from open
                    'low': cand.premarket_price * 0.995,
                    'built': False,
                }

            # Mark as built after 9:45
            if is_or_complete and sym in self._opening_ranges:
                self._opening_ranges[sym]['built'] = True

    def _check_exhaustion_signal(self, symbol: str) -> Optional[dict]:
        """Check if a gap candidate shows entry signal.

        Matches the backtested logic exactly:
            1. Price < Opening Range High (momentum fading)
            2. Price < gap open price (gap is fading)

        No VWAP/RSI dependency — uses snapshot prices only.
        This is EXACTLY what produced PF 1.71 over 5 years.
        """
        # Check for sweep signal first (higher quality)
        if self.config.sweep_entry_enabled:
            sweep = self._check_sweep_signal(symbol)
            if sweep:
                return sweep

        if symbol in self._exhaustion_entered:
            return None
        if symbol not in self._opening_ranges:
            return None

        or_data = self._opening_ranges[symbol]
        or_high = or_data['high']

        # Get price from latest snapshot (stored by _exhaustion_entry_scan)
        price = 0.0
        if self.streamer and hasattr(self.streamer, 'latest_prices'):
            price = self.streamer.latest_prices.get(symbol, 0)
        if price <= 0:
            return None

        # Find the candidate
        cand = next((c for c in self.candidates if c.symbol == symbol), None)
        if not cand:
            return None

        gap_open = cand.premarket_price
        now = datetime.now(ET)

        # THE TWO CONDITIONS (matching backtest exactly):
        # 1. Price below OR high (initial spike has faded)
        below_or_high = price < or_high

        # 2. Price below the gap open (gap is actually fading)
        price_fading = price < gap_open

        if below_or_high and price_fading:
            return {
                'type': 'exhaustion',
                'or_high': or_high,
                'price': price,
                'gap_open': gap_open,
                'fade_pct': (gap_open - price) / gap_open if gap_open > 0 else 0,
                'time': now.strftime('%H:%M:%S'),
            }

        return None

    def _check_sweep_signal(self, symbol: str) -> Optional[dict]:
        """Detect liquidity sweep above OR high and return entry signal on recovery.

        Sweep pattern (for SHORT gap-up fade):
        1. Price spikes ABOVE the Opening Range high (sweep)
        2. Price fails to hold — drops back BELOW OR high within sweep_max_time_bars checks
        3. This is the BEST short entry — stops above the sweep high

        The stop goes above the SWEEP high (not just OR high),
        which is harder to hunt again since institutions already got
        their liquidity there.

        For LONG gap-down fades: sweep is below OR low, recovery back above.
        """
        if not self.config.sweep_entry_enabled:
            return None
        if symbol in self._exhaustion_entered:
            return None
        if symbol not in self._opening_ranges:
            return None

        sweep = self._sweep_data.get(symbol)
        if sweep is None or not sweep.get('recovered') or sweep.get('entry_triggered'):
            return None

        # Recovery must happen within max_time_bars
        if sweep.get('bars_since', 0) > self.config.sweep_max_time_bars:
            return None

        or_data = self._opening_ranges[symbol]
        or_high = or_data['high']

        # Get current price
        price = 0.0
        if self.streamer and hasattr(self.streamer, 'latest_prices'):
            price = self.streamer.latest_prices.get(symbol, 0)
        if price <= 0:
            return None

        sweep_high = sweep['sweep_high']

        # Determine direction from candidate
        cand = next((c for c in self.candidates if c.symbol == symbol), None)
        direction = cand.direction if cand else 'short'

        if direction == 'short':
            # Sweep was above OR high; price must now be below OR high
            if price >= or_high:
                return None
            # Recovery must be meaningful: price dropped sweep_min_recovery_pct from sweep_high
            recovery_pct = (sweep_high - price) / sweep_high if sweep_high > 0 else 0
            if recovery_pct < self.config.sweep_min_recovery_pct:
                return None
            # Stop above the sweep high (harder to hunt again)
            stop_price = round(sweep_high * 1.002, 2)
        else:
            # LONG: sweep was below OR low; price must now be above OR low
            or_low = or_data.get('low', 0)
            if or_low <= 0 or price <= or_low:
                return None
            sweep_low = sweep['sweep_high']  # stored as the extreme (lowest price for longs)
            recovery_pct = (price - sweep_low) / sweep_low if sweep_low > 0 else 0
            if recovery_pct < self.config.sweep_min_recovery_pct:
                return None
            stop_price = round(sweep_low * 0.998, 2)

        now = datetime.now(ET)
        return {
            'type': 'sweep',
            'or_high': or_high,
            'sweep_high': sweep_high,
            'sweep_time': sweep.get('sweep_time', ''),
            'vwap': 0,
            'rsi': 0,
            'price': price,
            'stop_price': stop_price,
            'time': now.strftime('%H:%M:%S'),
        }

    def _update_sweep_tracking(self, symbol: str, price: float, direction: str = 'short'):
        """Update sweep tracking data for a symbol on every price check.

        Called during exhaustion entry scan to track potential liquidity sweeps.
        """
        if not self.config.sweep_entry_enabled:
            return
        if symbol not in self._opening_ranges:
            return

        or_data = self._opening_ranges[symbol]
        or_high = or_data['high']
        or_low = or_data.get('low', 0)
        now = datetime.now(ET)

        if direction == 'short':
            # Track if price sweeps ABOVE OR high
            if price > or_high:
                if symbol not in self._sweep_data:
                    self._sweep_data[symbol] = {
                        'sweep_high': price,
                        'sweep_time': now.strftime('%H:%M:%S'),
                        'bars_since': 0,
                        'recovered': False,
                        'entry_triggered': False,
                    }
                else:
                    sd = self._sweep_data[symbol]
                    sd['sweep_high'] = max(sd['sweep_high'], price)
                    if not sd['recovered']:
                        sd['bars_since'] += 1
            elif symbol in self._sweep_data:
                sd = self._sweep_data[symbol]
                if not sd['recovered']:
                    # Price came back below OR high — recovery detected
                    sd['recovered'] = True
                    sd['bars_since'] += 1
                elif not sd['entry_triggered']:
                    sd['bars_since'] += 1
        else:
            # LONG: track if price sweeps BELOW OR low
            if or_low > 0 and price < or_low:
                if symbol not in self._sweep_data:
                    self._sweep_data[symbol] = {
                        'sweep_high': price,  # actually sweep_low for longs
                        'sweep_time': now.strftime('%H:%M:%S'),
                        'bars_since': 0,
                        'recovered': False,
                        'entry_triggered': False,
                    }
                else:
                    sd = self._sweep_data[symbol]
                    sd['sweep_high'] = min(sd['sweep_high'], price)  # track lowest
                    if not sd['recovered']:
                        sd['bars_since'] += 1
            elif symbol in self._sweep_data:
                sd = self._sweep_data[symbol]
                if not sd['recovered']:
                    sd['recovered'] = True
                    sd['bars_since'] += 1
                elif not sd['entry_triggered']:
                    sd['bars_since'] += 1

    async def _check_pyramid_opportunities(self):
        """Check open positions for pyramid (add-to-winner) opportunities.

        Called every 30 seconds during market hours when positions exist.

        Rules:
        1. Position must be profitable (>= pyramid_min_profit_pct from avg entry)
        2. Current price > last pyramid entry * (1 + min_profit_pct) (distance from last add)
        3. Max pyramid_max_adds adds per position
        4. EMA(9) > EMA(21) must still be aligned (trend valid) — when indicator data available
        5. Volume above average (confirming momentum) — when indicator data available
        6. After each add: move stop to breakeven of the combined position
        7. Each add size = original_shares * (pyramid_size_decay ^ (pyramid_count + 1))

        For SHORTS: profitable means price BELOW entry, pyramid on new lows.
        For LONGS: profitable means price ABOVE entry, pyramid on new highs.
        """
        if self._trading_halted:
            return
        if not self.config.pyramid_enabled:
            return

        now = datetime.now(ET)
        now_mono = _time.monotonic()

        # Throttle: check every 30 seconds
        if now_mono - self._last_pyramid_check < 30:
            return
        self._last_pyramid_check = now_mono

        # Get prices: prefer streamer, fall back to REST
        prices: dict = {}
        if self.streamer and hasattr(self.streamer, 'latest_prices'):
            prices = dict(self.streamer.latest_prices)
        if not prices and self.engine.positions:
            try:
                syms = list(self.engine.positions.keys())
                prices = await self._broker_get_prices(syms)
            except Exception as e:
                logger.warning(f"Pyramid price fetch failed: {e}")
                return

        for sym in list(self.engine.positions.keys()):
            price = prices.get(sym)
            if not price or price <= 0:
                continue

            async with self._position_lock:
                pos = self.engine.positions.get(sym)
                if not pos:
                    continue

                # Skip non-gap-fade positions (swing, intraday)
                if pos.source != 'gap_fade':
                    continue
                # Skip positions being closed
                if pos.closing:
                    continue
                # Max adds reached
                if pos.pyramid_count >= self.config.pyramid_max_adds:
                    continue

                # Calculate current P&L %
                if pos.direction == 'short':
                    pnl_pct = (pos.entry_price - price) / pos.entry_price if pos.entry_price > 0 else 0
                else:
                    pnl_pct = (price - pos.entry_price) / pos.entry_price if pos.entry_price > 0 else 0

                # Must be profitable enough
                if pnl_pct < self.config.pyramid_min_profit_pct:
                    continue

                # Check distance from last pyramid entry
                last_entry_price = pos.entry_price  # default to avg entry
                if pos.pyramid_entries:
                    try:
                        entries = json.loads(pos.pyramid_entries)
                        if entries:
                            last_entry_price = entries[-1]['price']
                    except (json.JSONDecodeError, KeyError, IndexError):
                        pass

                if pos.direction == 'short':
                    # For shorts, price must be sufficiently below last add
                    distance = (last_entry_price - price) / last_entry_price if last_entry_price > 0 else 0
                else:
                    # For longs, price must be sufficiently above last add
                    distance = (price - last_entry_price) / last_entry_price if last_entry_price > 0 else 0

                if distance < self.config.pyramid_min_profit_pct:
                    continue

                # EMA trend check (when indicator data available)
                if self.indicator_engine:
                    tick_data = self.indicator_engine.get_data(sym)
                    if tick_data:
                        ema9 = tick_data.get('ema9', 0)
                        ema21 = tick_data.get('ema21', 0)
                        if ema9 > 0 and ema21 > 0:
                            if pos.direction == 'short' and ema9 > ema21:
                                # Short: EMA9 above EMA21 means uptrend — skip pyramid
                                continue
                            elif pos.direction == 'long' and ema9 < ema21:
                                # Long: EMA9 below EMA21 means downtrend — skip pyramid
                                continue

                        # Volume check: prefer above-average volume
                        vol_surge = tick_data.get('volume_surge_ratio', 1.0)
                        if vol_surge < 0.8:
                            continue  # below-average volume — skip

                # Calculate add size: original_shares * decay^(count+1)
                add_shares = int(pos.original_shares * (
                    self.config.pyramid_size_decay ** (pos.pyramid_count + 1)))
                if add_shares <= 0:
                    continue

                # Cap notional (respect max_notional)
                add_notional = add_shares * price
                existing_notional = pos.remaining_shares * price
                if existing_notional + add_notional > self.config.max_notional:
                    add_shares = max(0, int((self.config.max_notional - existing_notional) / price))
                    if add_shares <= 0:
                        continue

            # Submit pyramid order (outside lock to avoid holding during I/O)
            entry_side = 'buy' if pos.direction == 'long' else 'sell'
            side_label = 'LONG' if pos.direction == 'long' else 'SHORT'

            if self.config.limit_orders_only:
                if pos.direction == 'long':
                    limit_px = round(price * (1 + self.config.limit_offset_pct), 2)
                else:
                    limit_px = round(price * (1 - self.config.limit_offset_pct), 2)
                order_type = 'limit'
            else:
                limit_px = None
                order_type = 'market'

            try:
                fill = await self._broker_submit(
                    sym, add_shares, entry_side,
                    order_type=order_type, limit_price=limit_px,
                    timeout_sec=60.0 if order_type == 'limit' else 30.0,
                )
            except Exception as e:
                logger.warning(f"Pyramid order failed for {sym}: {e}")
                continue

            if not fill.is_filled:
                logger.info(f"Pyramid order not filled for {sym}: {fill.status}")
                continue

            # Update position under lock
            async with self._position_lock:
                pos = self.engine.positions.get(sym)
                if not pos:
                    continue

                fill_price = fill.filled_avg_price if fill.filled_avg_price > 0 else price
                filled_qty = fill.filled_qty if fill.filled_qty > 0 else add_shares

                # Record pyramid entry
                try:
                    entries = json.loads(pos.pyramid_entries) if pos.pyramid_entries else []
                except (json.JSONDecodeError, ValueError):
                    entries = []
                entries.append({
                    'price': fill_price,
                    'shares': filled_qty,
                    'time': now.strftime('%H:%M:%S'),
                })
                pos.pyramid_entries = json.dumps(entries)

                # Recalculate weighted average entry price
                old_total_cost = pos.entry_price * pos.remaining_shares
                new_total_cost = fill_price * filled_qty
                new_total_shares = pos.remaining_shares + filled_qty
                new_avg_entry = (old_total_cost + new_total_cost) / new_total_shares if new_total_shares > 0 else pos.entry_price

                pos.entry_price = new_avg_entry
                pos.shares = new_total_shares
                pos.remaining_shares = new_total_shares
                pos.pyramid_count += 1

                # Move stop to breakeven of combined position
                new_stop = None
                if self.config.pyramid_move_stop:
                    if pos.direction == 'short':
                        # Breakeven for shorts: avg entry + small buffer
                        new_stop = round(new_avg_entry * 1.001, 2)
                    else:
                        # Breakeven for longs: avg entry - small buffer
                        new_stop = round(new_avg_entry * 0.999, 2)
                    pos.stop_price = new_stop

                    # Replace broker-side stop
                    if pos.stop_order_id:
                        try:
                            await self._broker_cancel(pos.stop_order_id)
                        except Exception as e:
                            logger.warning(f"Cancel old stop for pyramid {sym}: {e}")

                    try:
                        stop_result = await self._broker_place_stop(
                            sym, pos.remaining_shares, new_stop,
                            0.003, pos.direction)
                        if 'error' not in stop_result:
                            pos.stop_order_id = stop_result.get('id', '')
                    except Exception as e:
                        logger.warning(f"Broker stop failed for pyramid {sym}: {e}")

            # Log and alert
            stop_msg = f', stop moved to ${new_stop:.2f} (breakeven)' if new_stop else ''
            msg = (f'PYRAMID #{pos.pyramid_count} {side_label} +{filled_qty} {sym} '
                   f'@ ${fill_price:.2f} (avg entry ${new_avg_entry:.2f}, '
                   f'total {new_total_shares} shares{stop_msg})')
            self._add_message('pyramid', msg)
            self.journal.log('action', 'pyramid_add', msg, symbol=sym)
            logger.info(msg)

            await self.alerter.send(
                f'Pyramid Add — {side_label} {sym}',
                f'Add #{pos.pyramid_count}: +{filled_qty} shares @ ${fill_price:.2f}\n'
                f'Avg entry: ${new_avg_entry:.2f}\n'
                f'Total shares: {new_total_shares}\n'
                f'P&L: {pnl_pct*100:.1f}%{stop_msg}',
                level='info', throttle_key=f'pyramid_{sym}')

    async def _exhaustion_entry_scan(self):
        """Scan all candidates for entry signals and enter positions.

        Uses Alpaca REST snapshots for prices — no tick stream dependency.
        Called every 15 seconds between 9:45 and entry_cutoff.
        """
        if self._trading_halted or not self.candidates:
            return

        now = datetime.now(ET)

        # Only scan between 9:45 and entry cutoff
        if now.hour == 9 and now.minute < 45:
            return
        if now.hour > self.config.entry_cutoff_hour or \
           (now.hour == self.config.entry_cutoff_hour and now.minute >= self.config.entry_cutoff_min):
            return

        eff_max = self.engine.effective_max_positions(len(self.candidates))

        # Fetch LIVE prices for all candidates in one batch REST call
        cand_syms = [c.symbol for c in self.candidates
                     if c.symbol not in self._exhaustion_entered
                     and c.symbol not in self.engine.positions][:30]
        if not cand_syms:
            return

        try:
            live_prices = await self._broker_get_prices(cand_syms)
        except Exception as e:
            logger.warning(f"Exhaustion scan: price fetch failed: {e}")
            return

        if not live_prices:
            return

        for cand in self.candidates:
            sym = cand.symbol

            # Get live price from batch fetch
            price = live_prices.get(sym, 0)
            if price <= 0:
                continue

            # Update sweep tracking
            if self.config.sweep_entry_enabled and sym in self._opening_ranges:
                self._update_sweep_tracking(sym, price, cand.direction)

            if sym in self._exhaustion_entered:
                continue
            if len(self.engine.positions) >= eff_max:
                break
            if sym in self.engine.positions:
                continue

            # Store price for signal check
            if self.streamer and hasattr(self.streamer, 'latest_prices'):
                self.streamer.latest_prices[sym] = price

            signal = self._check_exhaustion_signal(sym)
            if signal is None:
                continue

            # Signal triggered — enter position
            is_sweep = signal['type'] == 'sweep'
            or_high = signal['or_high']
            entry_price = signal['price']

            if is_sweep:
                self._add_message('entry',
                    f'SWEEP ENTRY: {sym} @ ${entry_price:.2f} '
                    f'(sweep high=${signal["sweep_high"]:.2f}, OR high=${or_high:.2f})')
            else:
                self._add_message('entry',
                    f'EXHAUSTION {signal["type"]}: {sym} @ ${entry_price:.2f} '
                    f'(OR high=${or_high:.2f}, VWAP=${signal["vwap"]:.2f}, RSI={signal["rsi"]:.1f})')

            # Set stop: sweep uses sweep_high-based stop, exhaustion uses OR-high-based
            if is_sweep:
                stop_price = signal['stop_price']
            else:
                # Structural stop: 0.2% above OR high
                stop_price = or_high * 1.002
            stop_pct = (stop_price - entry_price) / entry_price if entry_price > 0 else 0.03
            if stop_pct < 0.005:
                stop_pct = 0.005
                stop_price = entry_price * (1 + stop_pct)

            # Open position in engine
            async with self._position_lock:
                ok, reason = self.engine.should_enter(cand)
                if not ok:
                    self._add_message('skip', f'{"Sweep" if is_sweep else "Exhaustion"} skip {sym}: {reason}')
                    continue

                entry_time = now.strftime('%Y-%m-%d %H:%M')
                pos = self.engine.open_position(cand, entry_price, entry_time)
                if pos is None:
                    continue

                # Override stop with structural stop
                pos.stop_price = stop_price
                pos.strategy_id = 'sweep_gap_fade' if is_sweep else 'exhaustion_gap_fade'

            # Submit order
            direction = cand.direction
            entry_side = 'buy' if direction == 'long' else 'sell'
            side_label = 'LONG' if direction == 'long' else 'SHORT'

            if self.config.limit_orders_only:
                if direction == 'long':
                    limit_px = round(entry_price * (1 + self.config.limit_offset_pct), 2)
                else:
                    limit_px = round(entry_price * (1 - self.config.limit_offset_pct), 2)
                order_type = 'limit'
            else:
                limit_px = None
                order_type = 'market'

            fill = await self._broker_submit(
                sym, pos.shares, entry_side,
                order_type=order_type, limit_price=limit_px,
                timeout_sec=120.0 if order_type == 'limit' else 30.0,
            )

            async with self._position_lock:
                pos = self.engine.positions.get(sym)
                if not pos:
                    continue

                if fill.is_filled:
                    # Use the actual fill price, not the snapshot/limit price
                    fill_price = fill.filled_avg_price
                    # Safety: if fill price seems wrong (0 or same as snapshot), re-check
                    if fill_price <= 0 or abs(fill_price - entry_price) < 0.001:
                        try:
                            order_data = await self._broker_get_order(fill.order_id)
                            if order_data and order_data.get('filled_avg_price'):
                                fill_price = float(order_data['filled_avg_price'])
                        except Exception:
                            pass
                    pos.entry_fill_price = fill_price
                    pos.entry_order_id = fill.order_id
                    if fill_price > 0:
                        pos.entry_price = fill_price
                        if is_sweep:
                            # Sweep: keep stop above sweep high
                            sweep_high_val = signal.get('sweep_high', or_high)
                            pos.stop_price = round(sweep_high_val * 1.002, 2)
                            if (pos.stop_price - fill.filled_avg_price) / fill.filled_avg_price < 0.005:
                                pos.stop_price = fill.filled_avg_price * 1.005
                        else:
                            # Exhaustion: stop above OR high
                            pos.stop_price = or_high * 1.002
                            if (pos.stop_price - fill.filled_avg_price) / fill.filled_avg_price < 0.005:
                                pos.stop_price = fill.filled_avg_price * 1.005

                    # Place broker-side GTC stop
                    try:
                        stop_result = await self._broker_place_stop(
                            sym, fill.filled_qty, pos.stop_price,
                            0.003, direction)
                        if 'error' not in stop_result:
                            pos.stop_order_id = stop_result.get('id', '')
                    except Exception as e:
                        logger.warning(f"Broker stop failed for {'sweep' if is_sweep else 'exhaustion'} {sym}: {e}")

                    # Subscribe to tick stream
                    if self.streamer:
                        await self.streamer.add_symbols(
                            [sym], priority_symbols=set(self.engine.positions.keys()))

                    self._exhaustion_entered.add(sym)

                    # Mark sweep as entry_triggered
                    if is_sweep and sym in self._sweep_data:
                        self._sweep_data[sym]['entry_triggered'] = True

                    entry_type_label = 'SWEEP' if is_sweep else 'EXHAUSTION'
                    self._add_message('entry',
                        f'FILLED {side_label} {fill.filled_qty} {sym} @ ${fill.filled_avg_price:.2f} '
                        f'({"sweep" if is_sweep else "structural"} stop ${pos.stop_price:.2f})')

                    action_label = 'sweep_entry' if is_sweep else 'exhaustion_entry'
                    self.journal.log('action', action_label,
                        f'ENTRY {side_label} {fill.filled_qty} {sym} '
                        f'@ ${fill.filled_avg_price:.2f} (OR high=${or_high:.2f})',
                        symbol=sym)

                    # Send sweep-specific Telegram alert
                    if is_sweep:
                        sweep_high_val = signal.get('sweep_high', or_high)
                        await self.alerter.send(
                            f'SWEEP ENTRY \u2014 {side_label} {sym}',
                            f'Sweep high: ${sweep_high_val:.2f} (stop hunters triggered)\n'
                            f'Recovery: price back to ${fill.filled_avg_price:.2f}\n'
                            f'Entry: ${fill.filled_avg_price:.2f}\n'
                            f'Stop: ${pos.stop_price:.2f} (above sweep \u2014 safe)\n'
                            f'OR high was: ${or_high:.2f}\n'
                            f'Better R:R than plain exhaustion entry',
                            level='info', throttle_key=f'sweep_{sym}')

                    self._save_state()
                elif fill.status == 'pending':
                    pos.entry_order_id = fill.order_id
                    self._exhaustion_entered.add(sym)
                else:
                    self._add_message('error', f'{"Sweep" if is_sweep else "Exhaustion"} entry FAILED {sym}: {fill.error}')
                    if sym in self.engine.positions:
                        del self.engine.positions[sym]

    async def _enter_positions(self, llm_symbols=None, size_mult=1.0):
        """Enter positions on top candidates with fill verification.

        Args:
            llm_symbols: if set, only enter these symbols (LLM-selected, in order)
            size_mult: scale position size by this factor (0.5-1.0, LLM confidence)
        """
        # Circuit breaker: EOD watchdog has halted trading
        if self._trading_halted:
            self._add_message('system', 'Entry blocked — EOD circuit breaker active')
            logger.info("_enter_positions blocked by EOD circuit breaker")
            return

        self.status = 'trading'
        await broadcast({'type': 'live_status', 'status': 'trading'})

        # Market regime filter (live)
        regime = await fetch_market_regime_live(self.config)
        if regime and regime.position_reduction == -999:
            self._add_message('regime', f'BLOCKED: {regime.note}')
            await broadcast({'type': 'live_status', 'status': 'regime_blocked'})
            self.status = 'scanning'
            return
        if regime and regime.position_reduction == -1:
            self._add_message('regime', f'HALVED: {regime.note}')

        # Apply LLM symbol filter if provided
        candidates_to_trade = self.candidates
        if llm_symbols:
            sym_set = set(llm_symbols)
            candidates_to_trade = [c for c in self.candidates if c.symbol in sym_set]
            sym_order = {s: i for i, s in enumerate(llm_symbols)}
            candidates_to_trade.sort(key=lambda c: sym_order.get(c.symbol, 999))
            self._add_message('llm', f'Rudra selected {len(candidates_to_trade)} symbols: {llm_symbols}')

        # Thin day logic: if fewer candidates than threshold, trade all of them
        eff_max = self.engine.effective_max_positions(len(candidates_to_trade))
        if regime and regime.position_reduction == -1:
            eff_max = max(1, eff_max // 2)
        self.engine._effective_max_positions = eff_max
        self._add_message('entry',
            f'{len(candidates_to_trade)} candidates, trading top {eff_max}'
            + (' (thin day — trading all)' if eff_max > self.config.max_positions else '')
            + (f' ({regime.note})' if regime and regime.note else '')
            + (f' (size x{size_mult:.1f})' if size_mult != 1.0 else ''))

        symbols_entered = []
        for candidate in candidates_to_trade[:eff_max]:
            async with self._position_lock:
                ok, reason = self.engine.should_enter(candidate)
                if not ok:
                    _log_rejected_candidate(candidate, 'entry', reason,
                                            self.config.active_strategy)
                    self._add_message('skip', f'Skipping {candidate.symbol}: {reason}')
                    if 'halted' in reason or 'daily loss' in reason or 'drawdown' in reason:
                        await self.alerter.send('Circuit Breaker',
                            f'Entries blocked: {reason}',
                            level='warning', throttle_key='circuit_breaker')
                    continue

                # Strategy plugin: should_enter_now gate
                if self.strategy:
                    tick_data = self.indicator_engine.get_data(candidate.symbol) if self.indicator_engine else None
                    strat_ok, strat_reason = self.strategy.should_enter_now(
                        asdict(candidate), candidate.premarket_price, tick_data, datetime.now(ET))
                    if not strat_ok:
                        _log_rejected_candidate(candidate, 'strategy_gate', strat_reason,
                                                self.config.active_strategy)
                        self._add_message('strategy',
                            f'Strategy skip {candidate.symbol}: {strat_reason}')
                        continue

                entry_price = candidate.premarket_price
                entry_time = datetime.now(ET).strftime('%Y-%m-%d %H:%M')
                pos = self.engine.open_position(candidate, entry_price, entry_time)
                if pos is None:
                    continue

                # Tag position with strategy
                pos.strategy_id = self.config.active_strategy

                # LLM size adjustment
                if size_mult != 1.0 and pos.shares > 1:
                    pos.shares = max(1, int(pos.shares * size_mult))
                    pos.remaining_shares = pos.shares

            # Submit order and wait for fill (outside lock to not block other ops)
            direction = candidate.direction
            entry_side = 'buy' if direction == 'long' else 'sell'
            side_label = 'LONG' if direction == 'long' else 'SHORT'

            if self.config.limit_orders_only:
                if direction == 'long':
                    limit_px = round(entry_price * (1 + self.config.limit_offset_pct), 2)
                else:
                    limit_px = round(entry_price * (1 - self.config.limit_offset_pct), 2)
                order_type = 'limit'
                order_label = f'LIMIT @ ${limit_px:.2f}'
            else:
                limit_px = None
                order_type = 'market'
                order_label = 'MARKET'

            self._add_message('entry',
                f'Submitting {side_label} {pos.shares} {candidate.symbol} {order_label}...')

            fill = await self._broker_submit(
                candidate.symbol, pos.shares, entry_side,
                order_type=order_type, limit_price=limit_px,
                timeout_sec=120.0 if order_type == 'limit' else 30.0,
            )

            async with self._position_lock:
                if fill.is_filled:
                    # P0-3: Use actual fill price for position tracking
                    pos.entry_fill_price = fill.filled_avg_price
                    pos.entry_order_id = fill.order_id
                    # Recalculate stops/targets based on actual fill price
                    if fill.filled_avg_price > 0:
                        eff_stop_pct = compute_adaptive_stop_pct(self.config, candidate.gap_pct)
                        pos.entry_price = fill.filled_avg_price
                        if direction == 'long':
                            pos.stop_price = fill.filled_avg_price * (1 - eff_stop_pct)
                        else:
                            pos.stop_price = fill.filled_avg_price * (1 + eff_stop_pct)
                        pos.half_target = (fill.filled_avg_price + candidate.prev_close) / 2

                        # Strategy plugin: override stop and targets
                        if self.strategy:
                            tick_data = self.indicator_engine.get_data(candidate.symbol) if self.indicator_engine else None
                            strat_stop = self.strategy.compute_stop_price(
                                fill.filled_avg_price, asdict(candidate), tick_data)
                            if strat_stop is not None:
                                pos.stop_price = strat_stop
                            strat_targets = self.strategy.compute_targets(
                                fill.filled_avg_price, asdict(candidate), tick_data)
                            if strat_targets is not None:
                                pos.half_target, pos.full_target = strat_targets

                    # Place broker-side stop order immediately
                    stop_result = await self._broker_place_stop(
                        candidate.symbol, fill.filled_qty, pos.stop_price,
                        0.003, direction)
                    if 'error' not in stop_result:
                        pos.stop_order_id = stop_result.get('id', '')
                        self._add_message('entry',
                            f'Broker stop set: {candidate.symbol} @ ${pos.stop_price:.2f}')
                    else:
                        logger.warning(f"Broker stop failed for {candidate.symbol}: "
                                      f"{stop_result['error']} — using software stop")

                    symbols_entered.append(candidate.symbol)
                    self._add_message('entry',
                        f'FILLED {side_label} {fill.filled_qty} {candidate.symbol} '
                        f'@ ${fill.filled_avg_price:.2f} {order_label} '
                        f'(gap {candidate.gap_pct:.1%}, score {candidate.score:.0f})', {
                        'symbol': candidate.symbol,
                        'shares': fill.filled_qty,
                        'entry_price': fill.filled_avg_price,
                        'stop': pos.stop_price,
                        'target': pos.full_target,
                    })
                    await self.alerter.send('Entry Fill',
                        f'{side_label} {fill.filled_qty} {candidate.symbol} @ ${fill.filled_avg_price:.2f}\n'
                        f'Gap: {candidate.gap_pct:.1%} | Stop: ${pos.stop_price:.2f}',
                        level='trade')
                    # Inject entry event into LLM conversation (Tier 2 — batched)
                    self._add_event(
                        f'Entered {candidate.symbol} {direction} {fill.filled_qty} shares '
                        f'@ ${fill.filled_avg_price:.2f} (gap {candidate.gap_pct:.1%})',
                        tier=2)
                    # Journal: log entry action
                    self.journal.log('action', 'rules_engine',
                        f'ENTRY {side_label} {fill.filled_qty} {candidate.symbol} '
                        f'@ ${fill.filled_avg_price:.2f} (gap {candidate.gap_pct:.1%})',
                        symbol=candidate.symbol, data={
                            'direction': direction, 'shares': fill.filled_qty,
                            'fill_price': fill.filled_avg_price,
                            'gap_pct': candidate.gap_pct, 'stop': pos.stop_price})
                elif fill.status == 'partially_filled' and fill.filled_qty > 0:
                    # Partial fill — adjust position to actual filled quantity
                    pos.shares = fill.filled_qty
                    pos.remaining_shares = fill.filled_qty
                    pos.entry_fill_price = fill.filled_avg_price
                    pos.entry_order_id = fill.order_id
                    if fill.filled_avg_price > 0:
                        eff_stop_pct = compute_adaptive_stop_pct(self.config, candidate.gap_pct)
                        pos.entry_price = fill.filled_avg_price
                        if direction == 'long':
                            pos.stop_price = fill.filled_avg_price * (1 - eff_stop_pct)
                        else:
                            pos.stop_price = fill.filled_avg_price * (1 + eff_stop_pct)
                        pos.half_target = (fill.filled_avg_price + candidate.prev_close) / 2

                    # Place broker-side stop for partial fill too
                    stop_result = await self._broker_place_stop(
                        candidate.symbol, fill.filled_qty, pos.stop_price,
                        0.003, direction)
                    if 'error' not in stop_result:
                        pos.stop_order_id = stop_result.get('id', '')

                    symbols_entered.append(candidate.symbol)
                    self._add_message('warning',
                        f'PARTIAL FILL {fill.filled_qty}/{pos.shares} {candidate.symbol} '
                        f'@ ${fill.filled_avg_price:.2f}')
                elif fill.status == 'pending' and order_type == 'limit':
                    # Limit order still open after polling timeout — it's
                    # still live on the broker. Track the order_id so we can
                    # reconcile when it fills (via WebSocket or next poll).
                    pos.entry_order_id = fill.order_id
                    self._add_message('info',
                        f'{candidate.symbol} limit order still open, holding '
                        f'(id={fill.order_id})')
                    symbols_entered.append(candidate.symbol)
                elif fill.status == 'timeout' and order_type == 'limit':
                    # Legacy path: only reached if cancel_on_timeout=True
                    self._add_message('warning',
                        f'{candidate.symbol} limit cancelled after timeout, retrying MARKET...')
                    fill = await self._broker_submit(
                        candidate.symbol, pos.shares, entry_side,
                        order_type='market', timeout_sec=30.0,
                    )
                    if fill.is_filled:
                        pos.entry_fill_price = fill.filled_avg_price
                        pos.entry_order_id = fill.order_id
                        if fill.filled_avg_price > 0:
                            eff_stop_pct = compute_adaptive_stop_pct(self.config, candidate.gap_pct)
                            pos.entry_price = fill.filled_avg_price
                            if direction == 'long':
                                pos.stop_price = fill.filled_avg_price * (1 - eff_stop_pct)
                            else:
                                pos.stop_price = fill.filled_avg_price * (1 + eff_stop_pct)
                            pos.half_target = (fill.filled_avg_price + candidate.prev_close) / 2
                        stop_result = await self._broker_place_stop(
                            candidate.symbol, fill.filled_qty, pos.stop_price,
                            0.003, direction)
                        if 'error' not in stop_result:
                            pos.stop_order_id = stop_result.get('id', '')
                            self._add_message('entry',
                                f'Broker stop set: {candidate.symbol} @ ${pos.stop_price:.2f}')
                        symbols_entered.append(candidate.symbol)
                        self._add_message('entry',
                            f'FILLED {side_label} {fill.filled_qty} {candidate.symbol} '
                            f'@ ${fill.filled_avg_price:.2f} MARKET (retry) '
                            f'(gap {candidate.gap_pct:.1%}, score {candidate.score:.0f})')
                    else:
                        self._add_message('error',
                            f'Entry MARKET retry also FAILED for {candidate.symbol}: {fill.error}')
                        if candidate.symbol in self.engine.positions:
                            del self.engine.positions[candidate.symbol]
                else:
                    # Order failed/rejected — remove position from internal state
                    self._add_message('error',
                        f'Entry order FAILED for {candidate.symbol}: {fill.error}')
                    if candidate.symbol in self.engine.positions:
                        del self.engine.positions[candidate.symbol]

        # Start or reuse tick streamer for entered symbols
        if symbols_entered:
            if self.streamer and self.streamer.connected:
                # Reuse existing connection — dynamically subscribe to new symbols
                await self.streamer.add_symbols(
                    symbols_entered,
                    priority_symbols=set(self.engine.positions.keys()))
            else:
                # No active streamer — stop stale one if any, then create new
                if self.streamer:
                    await self.streamer.stop()
                self.streamer = self._broker_make_streamer(symbols_entered, on_tick=self._on_tick)
                await self.streamer.start()

        # If no entries succeeded, reset status so the bot isn't stuck in 'trading'
        # with no positions (which blocks further scanning in fallback mode)
        if not symbols_entered and not self.engine.positions:
            self.status = 'scanning'
            await broadcast({'type': 'live_status', 'status': 'scanning'})
            logger.warning("No entries succeeded and no open positions — status reset to 'scanning'")

        await broadcast({
            'type': 'positions_update',
            'positions': {s: asdict(p) for s, p in self.engine.positions.items()},
        })
        self._save_state()

    # -------------------------------------------------------------------------
    # Exit Flow — evaluate → place order → confirm fill → update state
    # -------------------------------------------------------------------------

    async def _execute_exit(self, symbol: str, exit_signal: dict, price: float) -> Optional[TradeRecord]:
        """Execute a single exit: cancel broker stop, place cover order, wait for fill, confirm.

        Must be called with _position_lock already held.
        Returns the TradeRecord if successful, None if order failed.
        """
        pos = self.engine.positions.get(symbol)
        if pos is None or pos.closing:
            return None

        reason = exit_signal['reason']
        shares = exit_signal['shares']
        is_eod = reason == 'eod'
        is_stop = reason == 'stop'

        # Mark position as closing to prevent re-entry
        pos.closing = True

        # Cancel ALL open orders for this symbol before placing the cover order.
        # Alpaca holds shares for pending orders (including stops), which causes
        # "insufficient qty available" if we submit a cover while orders are active.
        # Skip only for stop exits where the broker stop triggered the exit.
        if not is_stop:
            if self._use_ibkr:
                # IBKR: cancel stop order directly if we have one
                pos = self.engine.positions.get(symbol)
                _cancelled = 0
                if pos and pos.stop_order_id:
                    if await self._broker_cancel(pos.stop_order_id):
                        _cancelled = 1
                        pos.stop_order_id = ''
            else:
                _cancelled = await asyncio.to_thread(
                    alpaca_cancel_open_orders_for_symbol, symbol)
            if _cancelled > 0:
                logger.info(f"Cancelled {_cancelled} open orders for {symbol} before cover")
                # Poll until Alpaca confirms no open orders remain for this symbol
                for _wait in range(8):
                    await asyncio.sleep(0.5)
                    _remaining = await asyncio.to_thread(
                        _alpaca_open_order_count, symbol)
                    if _remaining == 0:
                        break
                else:
                    logger.warning(f"{symbol}: open orders still present after 4s, proceeding anyway")
            pos.stop_order_id = ''

        # Direction-aware exit side: sell to close longs, buy to cover shorts
        direction = pos.direction
        exit_side = 'sell' if direction == 'long' else 'buy'

        # Choose order type: EOD always market for guaranteed execution
        if is_eod:
            order_type = 'market'
            limit_px = None
        elif self.config.limit_orders_only:
            if direction == 'long':
                limit_px = round(price * (1 - self.config.limit_offset_pct), 2)
            else:
                limit_px = round(price * (1 + self.config.limit_offset_pct), 2)
            order_type = 'limit'
        else:
            order_type = 'market'
            limit_px = None

        fill = await self._broker_submit(
            symbol, shares, exit_side,
            order_type=order_type, limit_price=limit_px,
            timeout_sec=60.0 if order_type == 'limit' else 30.0,
            cancel_on_timeout=True,  # exits MUST fill — cancel and retry
        )

        # Market fallback: if limit cover timed out, retry with market order
        if fill.status == 'timeout' and order_type == 'limit':
            self._add_message('warning',
                f'{symbol} limit cover timed out after 60s, retrying MARKET...')
            await asyncio.sleep(1)  # brief pause for broker to clear the cancel hold
            fill = await self._broker_submit(
                symbol, shares, exit_side,
                order_type='market', timeout_sec=30.0,
            )

        if fill.is_filled:
            now = datetime.now(ET)
            trade = self.engine.confirm_exit(
                symbol, fill.filled_qty, fill.filled_avg_price, reason, now
            )
            if trade:
                self._add_message('exit',
                    f'{reason.upper()} {fill.filled_qty} {symbol} '
                    f'@ ${fill.filled_avg_price:.2f} P&L: ${trade.pnl:.2f} ({trade.pnl_pct:.1%})')
                # Invalidate lessons cache so next LLM call includes this trade
                self._lessons_cache = None
                # Inject event into LLM conversation
                event_tier = 3 if is_stop and trade.pnl < 0 else 2
                self._add_event(
                    f'{symbol} {reason}: {fill.filled_qty} shares @ ${fill.filled_avg_price:.2f}, '
                    f'P&L ${trade.pnl:+,.2f} ({trade.pnl_pct:+.1%})',
                    tier=event_tier)
                pnl_sign = '+' if trade.pnl >= 0 else ''
                await self.alerter.send(f'Exit: {symbol}',
                    f'{reason.upper()} {fill.filled_qty} {symbol} @ ${fill.filled_avg_price:.2f}\n'
                    f'P&L: {pnl_sign}${trade.pnl:.2f} ({trade.pnl_pct:+.1%})',
                    level='trade')
                # Journal: log exit action
                self.journal.log('action', 'rules_engine',
                    f'EXIT {reason}: {fill.filled_qty} {symbol} @ ${fill.filled_avg_price:.2f}, '
                    f'P&L ${trade.pnl:+,.2f} ({trade.pnl_pct:+.1%})',
                    symbol=symbol, data={'pnl': trade.pnl, 'reason': reason,
                        'fill_price': fill.filled_avg_price, 'shares': fill.filled_qty})

            # If partial profit exit, replace broker stop at breakeven
            if reason == 'partial' and symbol in self.engine.positions:
                new_pos = self.engine.positions[symbol]
                new_stop_result = await alpaca_replace_stop_order(
                    '', symbol, new_pos.remaining_shares, new_pos.stop_price
                )
                if 'error' not in new_stop_result:
                    new_pos.stop_order_id = new_stop_result.get('id', '')
                    self._add_message('info',
                        f'Stop moved to breakeven: {symbol} @ ${new_pos.stop_price:.2f}')

            return trade

        elif fill.status == 'partially_filled' and fill.filled_qty > 0:
            now = datetime.now(ET)
            trade = self.engine.confirm_exit(
                symbol, fill.filled_qty, fill.filled_avg_price, reason, now
            )
            # confirm_exit sets closing=False, but we still have remaining shares
            # with a potentially live order — keep closing=True to prevent over-sell
            remaining_pos = self.engine.positions.get(symbol)
            if remaining_pos:
                remaining_pos.closing = True
            if trade:
                self._add_message('warning',
                    f'PARTIAL COVER {fill.filled_qty}/{shares} {symbol} '
                    f'@ ${fill.filled_avg_price:.2f}')
            return trade

        else:
            # Order failed — clear closing flag so we can retry
            if symbol in self.engine.positions:
                self.engine.positions[symbol].closing = False
            self._add_message('error',
                f'Cover order FAILED for {symbol}: {fill.error} — will retry')
            logger.error(f"Cover order failed: {symbol} {shares} shares: {fill.error}")
            return None

    async def _execute_scheduled_reflection(self):
        """Run periodic LLM reflection with enriched context. Replaces autonomous_review.

        Triggers on:
        - Time interval (900s / 15 min)
        - Event accumulation (3+ pending events)
        Both subject to LLM call budget.
        """
        if not self.llm_supervisor or not self.llm_supervisor.is_available():
            return
        if not self.engine.positions:
            return

        now_mono = _time.monotonic()
        _time_trigger = (now_mono - self._last_autonomous_review >= self._AUTONOMOUS_REVIEW_INTERVAL)
        _event_trigger = (self._event_bus.pending_count() >= 3)
        if not _time_trigger and not _event_trigger:
            return

        self._last_autonomous_review = now_mono

        now = datetime.now(ET)
        state = self._build_llm_state(now)

        # Enrich state with indicator snapshot
        indicator_snapshot = ''
        if self.indicator_engine and self.engine.positions:
            lines = []
            for sym in self.engine.positions:
                td = self.indicator_engine.get_data(sym)
                if td:
                    vwap = td.get('vwap', 0)
                    ema = td.get('ema', 0)
                    px = self.streamer.latest_prices.get(sym, 0) if self.streamer else 0
                    if vwap or ema:
                        lines.append(f'{sym}: price=${px:.2f} VWAP=${vwap:.2f} EMA=${ema:.2f}')
            if lines:
                indicator_snapshot = '\nIndicators:\n' + '\n'.join(lines)

        # Enrich with journal summary
        journal_summary = self.journal.get_summary(minutes=20)

        state['indicator_snapshot'] = indicator_snapshot
        state['journal_summary'] = journal_summary

        trigger_reason = 'event_accumulation' if _event_trigger else 'scheduled_interval'
        logger.info(f"Scheduled reflection starting ({len(self.engine.positions)} positions, "
                    f"trigger={trigger_reason})")
        self.journal.log('observation', 'scheduled_reflection',
            f'Reflection triggered ({trigger_reason}), {len(self.engine.positions)} positions')

        try:
            review = await self.llm_supervisor.autonomous_review(
                state, event_queue=self._event_bus)
        except Exception as e:
            logger.warning(f"Scheduled reflection failed: {e}")
            return

        actions = review.get('actions', [])

        # Show the review exchange in activity feed
        n_pos = len(self.engine.positions)
        review_analysis = review.get('_analysis', '')

        # Parse ReAct response for journal
        react = self.llm_supervisor._parse_react_response(review_analysis)
        if react['observe']:
            self.journal.log('observation', 'llm_rudra', react['observe'], llm_call=True)
        if react['think']:
            self.journal.log('reasoning', 'llm_rudra', react['think'], llm_call=True)

        if actions:
            action_summary = ', '.join(
                f"{a.get('action', '?')} {a.get('symbol', '')}" for a in actions[:3])
            rudra_text = review_analysis if review_analysis else action_summary
            self._add_message('conversation',
                f'BOT: Reflection ({n_pos} positions) | RUDRA: [{action_summary}] {rudra_text}')
            await broadcast({'type': 'conversation',
                'speaker': 'rudra', 'text': f'[{action_summary}] {rudra_text}'})
            self.journal.log('action', 'llm_rudra',
                f'Reflection actions: {action_summary}', llm_call=True)
        else:
            rudra_text = review_analysis if review_analysis else 'All looks good, no changes needed.'
            self._add_message('conversation',
                f'BOT: Reflection ({n_pos} positions) | RUDRA: {rudra_text}')
            self.journal.log('no_action', 'llm_rudra',
                f'Reflection: {rudra_text[:200]}', llm_call=True)
            logger.info("Scheduled reflection: no actions recommended")
            return

        executed = []
        for rec in actions:
            action = rec.get('action', 'none')
            symbol = rec.get('symbol', '').upper()
            reasoning = rec.get('reasoning', '')

            if action == 'close' and symbol:
                pos = self.engine.positions.get(symbol)
                if pos and not pos.closing:
                    # Get current price
                    price = 0.0
                    if self.streamer and self.streamer.latest_prices:
                        price = self.streamer.latest_prices.get(symbol, 0.0)
                    if price <= 0:
                        price = pos.entry_price
                    exit_signal = {
                        'reason': 'llm_profit',
                        'shares': pos.remaining_shares,
                        'is_full_close': True,
                        'trigger_price': price,
                    }
                    async with self._position_lock:
                        trade = await self._execute_exit(symbol, exit_signal, price)
                    if trade:
                        self._add_message('llm_review',
                            f'AUTO-CLOSE {symbol}: ${trade.pnl:+,.2f} — {reasoning}')
                        executed.append(f'close {symbol}')
                        await broadcast({'type': 'trade', 'trades': [asdict(trade)]})

            elif action == 'tighten_stop' and symbol:
                new_stop = rec.get('new_stop')
                if new_stop:
                    pos = self.engine.positions.get(symbol)
                    if pos:
                        old_stop = pos.stop_price
                        async with self._position_lock:
                            pos = self.engine.positions.get(symbol)
                            if pos:
                                pos.stop_price = float(new_stop)
                                # Update broker stop
                                if pos.stop_order_id:
                                    try:
                                        await self._broker_cancel(pos.stop_order_id)
                                        stop_result = await self._broker_place_stop(
                                            symbol, pos.remaining_shares, float(new_stop),
                                            0.003, pos.direction)
                                        if 'error' not in stop_result:
                                            pos.stop_order_id = stop_result.get('id', '')
                                    except Exception as e:
                                        logger.warning(f"Broker stop update failed: {e}")
                        self._add_message('llm_review',
                            f'AUTO-TIGHTEN {symbol} stop: ${old_stop:.2f} → ${new_stop:.2f} — {reasoning}')
                        executed.append(f'tighten {symbol}')

            elif action == 'adjust_config':
                key = rec.get('config_key')
                value = rec.get('config_value')
                if key and value is not None:
                    validated, errors = validate_config({key: value})
                    if validated:
                        old_val = getattr(self.config, key)
                        setattr(self.config, key, validated[key])
                        self._add_message('llm_review',
                            f'AUTO-CONFIG {key}: {old_val} → {validated[key]} — {reasoning}')
                        executed.append(f'config {key}')
                    elif errors:
                        logger.warning(f"LLM config rejected: {errors}")

        if executed:
            self._save_state()
            logger.info(f"Autonomous review executed: {', '.join(executed)}")
            await broadcast({
                'type': 'positions_update',
                'positions': {s: asdict(p) for s, p in self.engine.positions.items()},
                'stats': asdict(self.engine.daily_stats),
                'equity': self.engine.equity,
            })

    async def _check_broker_stops(self):
        """Check if any broker-side stop orders have been filled.

        This is the primary stop-loss mechanism — Alpaca triggers the stop
        server-side with zero latency. We just need to detect the fill and
        update internal state.
        """
        for sym in list(self.engine.positions.keys()):
            pos = self.engine.positions.get(sym)
            if not pos or not pos.stop_order_id or pos.closing:
                continue

            order_data = await self._broker_get_order(pos.stop_order_id)
            if order_data is None:
                continue

            status = order_data.get('status', '')

            if status == 'filled':
                fill_qty = int(order_data.get('filled_qty', pos.remaining_shares))
                fill_price = float(order_data.get('filled_avg_price', pos.stop_price))

                logger.info(f"Broker stop FILLED: {sym} {fill_qty} shares @ ${fill_price:.2f}")
                async with self._position_lock:
                    # Re-check position still exists after acquiring lock
                    pos = self.engine.positions.get(sym)
                    if not pos:
                        logger.warning(f"Broker stop fill for {sym} but position already gone")
                        continue
                    now = datetime.now(ET)
                    trade = self.engine.confirm_exit(sym, fill_qty, fill_price, 'stop', now)
                    pos_ref = self.engine.positions.get(sym)
                    if pos_ref:
                        pos_ref.stop_order_id = ''

                if trade:
                    self._add_message('exit',
                        f'STOP (broker) {fill_qty} {sym} '
                        f'@ ${fill_price:.2f} P&L: ${trade.pnl:.2f} ({trade.pnl_pct:.1%})')
                    await broadcast({'type': 'trade', 'trades': [asdict(trade)]})
                    await broadcast({
                        'type': 'positions_update',
                        'positions': {s: asdict(p) for s, p in self.engine.positions.items()},
                    })
                    self._save_state()

    async def _on_tick(self, symbol: str, price: float, size: int = 0):
        """Tick callback from Alpaca stream — evaluate non-stop exits under lock.

        Stop losses are handled by broker-side stop orders (zero latency).
        This only evaluates: partial target, full target, time exit,
        and strategy-specific exits (EMA cross, trailing stop).
        Also broadcasts tracker_tick for the position tracker UI.
        """
        # Feed indicator engine (if active)
        if self.indicator_engine and size > 0:
            self.indicator_engine.on_tick(symbol, price, size)

        # Broadcast to position tracker (even when trading is paused)
        if symbol in _tracker_watchlist:
            await broadcast({
                'type': 'tracker_tick',
                'symbol': symbol,
                'price': price,
                'timestamp': _time.time(),
            })

        # Broadcast to intraday SSE (throttled 1/sec per symbol)
        if symbol in self._intraday_watchlist and _intraday_sse_queues:
            _now_mono = _time.monotonic()
            if _now_mono - self._last_sse_tick.get(symbol, 0) >= 1.0:
                self._last_sse_tick[symbol] = _now_mono
                _td = self.indicator_engine.get_data(symbol) if self.indicator_engine else {}
                _intraday_sse_broadcast({
                    'type': 'tick',
                    'symbol': symbol,
                    'price': price,
                    'rsi': round(_td.get('rsi', 0), 2) if _td else 0,
                    'vwap': round(_td.get('vwap', 0), 2) if _td else 0,
                    'volume_surge': round(_td.get('volume_surge', 0), 2) if _td else 0,
                })

        if self.status not in ('trading', 'standdown'):
            return

        async with self._position_lock:
            if symbol not in self.engine.positions:
                return

            pos = self.engine.positions[symbol]

            # Skip exit evaluation for positions with pending (unfilled) entry orders
            if pos.entry_fill_price == 0.0 and pos.entry_order_id:
                logger.debug(f"Skipping tick exit eval for {symbol}: entry order pending")
                return

            now = datetime.now(ET)
            pos.update_tracking(price, now.strftime('%H:%M:%S'))

            # Broadcast updated positions to UI (throttled 1/sec)
            if connected_websockets:
                _now_mono = _time.monotonic()
                if _now_mono - self._last_pos_broadcast >= 1.0:
                    self._last_pos_broadcast = _now_mono
                    await broadcast({
                        'type': 'positions_update',
                        'positions': {s: asdict(p) for s, p in self.engine.positions.items()},
                    })

            # Event detection (pure arithmetic, <1ms)
            _tick_data = self.indicator_engine.get_data(symbol) if self.indicator_engine else None
            tick_events = self.event_detector.detect_tick_events(
                symbol, price, size, asdict(pos), _tick_data)
            if tick_events:
                self._event_bus.push_many(tick_events)
                for te in tick_events:
                    self.journal.log('observation', 'event_detector',
                        te.description, symbol=te.symbol, data=te.data)

            # Determine which strategy to use for this position
            _intraday_strat = self._intraday_strategies.get(pos.strategy_id)
            _active_strat = _intraday_strat or self.strategy

            # Strategy-specific trailing stop update
            if _active_strat:
                tick_data = self.indicator_engine.get_data(symbol) if self.indicator_engine else None
                new_stop = _active_strat.update_trailing_stop(
                    asdict(pos), price, tick_data, now)
                if new_stop is not None:
                    old_stop = pos.stop_price
                    pos.stop_price = new_stop
                    if abs(new_stop - old_stop) > 0.001:
                        self._add_message('strategy',
                            f'Trailing stop {symbol}: ${old_stop:.2f} -> ${new_stop:.2f}')
                        # Update broker stop if we have one
                        if pos.stop_order_id:
                            try:
                                await self._broker_cancel(pos.stop_order_id)
                                stop_result = await self._broker_place_stop(
                                    symbol, pos.remaining_shares, new_stop,
                                    0.003, pos.direction)
                                if 'error' not in stop_result:
                                    pos.stop_order_id = stop_result.get('id', '')
                            except Exception as e:
                                logger.warning(f"Broker trailing stop update failed for {symbol}: {e}")

            # Strategy-specific exit check (before engine exits)
            exit_signal = None
            if _active_strat:
                tick_data = self.indicator_engine.get_data(symbol) if self.indicator_engine else None
                strat_exit = _active_strat.evaluate_exit(
                    asdict(pos), price, tick_data, now)
                if strat_exit is not None:
                    exit_signal = {
                        'reason': strat_exit.reason,
                        'shares': strat_exit.shares or pos.remaining_shares,
                        'is_full_close': True,
                        'trigger_price': price,
                    }

            # Engine exit check (stop, partial, full target, time)
            # Save old stop to detect if trailing stop tightened
            _old_stop = pos.stop_price
            if exit_signal is None:
                exit_signal = self.engine.evaluate_exit(symbol, price, price, now)

            # Sync broker stop if the engine's smart exit tightened it
            if pos.stop_price != _old_stop and pos.stop_order_id and exit_signal is None:
                try:
                    await self._broker_cancel(pos.stop_order_id)
                    stop_result = await self._broker_place_stop(
                        symbol, pos.remaining_shares, pos.stop_price,
                        0.003, pos.direction)
                    if 'error' not in stop_result:
                        pos.stop_order_id = stop_result.get('id', '')
                        self._add_message('exit',
                            f'Trailing stop synced to broker: {symbol} ${_old_stop:.2f} → ${pos.stop_price:.2f}')
                except Exception as e:
                    logger.warning(f"Broker stop sync failed for {symbol}: {e}")

            if exit_signal is None:
                return

            # Skip stop signals — broker handles those
            if exit_signal['reason'] == 'stop' and pos.stop_order_id:
                return

            trade = await self._execute_exit(symbol, exit_signal, price)

        if trade:
            await broadcast({
                'type': 'trade',
                'trades': [asdict(trade)],
            })
            await broadcast({
                'type': 'positions_update',
                'positions': {s: asdict(p) for s, p in self.engine.positions.items()},
            })
            self._save_state()

    _spy_cache: Tuple[float, float] = (0.0, 0.0)  # (timestamp, change_pct)
    _SPY_CACHE_TTL = 60.0  # refresh SPY every 60 seconds
    _LLM_PROFIT_INTERVAL = 60.0  # seconds between LLM profit evals per position

    async def _get_spy_change(self) -> float:
        """Get SPY intraday change %. Cached for 60s."""
        now_mono = _time.monotonic()
        if now_mono - self._spy_cache[0] < self._SPY_CACHE_TTL:
            return self._spy_cache[1]
        try:
            if self._use_ibkr:
                # IBKR: get current price from snapshot, prev close from DB
                snap_prices = await self._broker_get_prices(['SPY'])
                spy_price = snap_prices.get('SPY', 0.0)
                if spy_price > 0:
                    db = get_price_db()
                    cur = db._conn.cursor()
                    cur.execute(
                        "SELECT close FROM daily_bars WHERE symbol='SPY' "
                        "ORDER BY date DESC LIMIT 1")
                    row = cur.fetchone()
                    if row and row[0] > 0:
                        change = (spy_price - row[0]) / row[0]
                        self._spy_cache = (now_mono, change)
                        return change
            else:
                snaps = await asyncio.to_thread(fetch_alpaca_snapshots, ['SPY'])
                spy = snaps.get('SPY', {})
                daily = spy.get('dailyBar', {})
                prev = spy.get('prevDailyBar', {})
                if daily.get('c') and prev.get('c'):
                    change = (daily['c'] - prev['c']) / prev['c']
                    self._spy_cache = (now_mono, change)
                    return change
        except Exception:
            pass
        return self._spy_cache[1]

    async def _check_positions(self):
        """Periodic position check: poll broker stops + evaluate non-stop exits + LLM profit."""
        if not self.engine.positions:
            return

        # Check if any broker-side stop orders have filled
        await self._check_broker_stops()

        now = datetime.now(ET)
        now_str = now.strftime('%H:%M:%S')
        now_mono = _time.monotonic()
        trades_executed = []

        # Fetch SPY once per cycle (cached)
        spy_change = 0.0
        if self.llm_supervisor and self.llm_supervisor.is_available():
            spy_change = await self._get_spy_change()

        # Get prices: prefer streamer, fall back to REST snapshots
        prices: dict = {}
        if self.streamer and self.streamer.latest_prices:
            prices = dict(self.streamer.latest_prices)
        if not prices and self.engine.positions:
            # REST fallback when WebSocket/streamer is down
            try:
                syms = list(self.engine.positions.keys())
                snap_prices = await self._broker_get_prices(syms)
                prices.update(snap_prices)
                if prices:
                    logger.debug(f"Using REST snapshot prices for {len(prices)} positions")
            except Exception as e:
                logger.warning(f"REST snapshot fallback failed: {e}")

        if prices:
            for sym in list(self.engine.positions.keys()):
                price = prices.get(sym)
                if not price:
                    continue

                # Phase 1: Fast checks under lock — trailing stop, strategy/engine exit
                trade = None
                exit_signal = None
                need_llm_profit = False
                need_llm_exit = False
                pos_snapshot = None
                llm_exit_signal = None

                async with self._position_lock:
                    pos = self.engine.positions.get(sym)
                    if not pos:
                        continue

                    # Skip exit evaluation for positions with pending (unfilled) entry orders
                    if pos.entry_fill_price == 0.0 and pos.entry_order_id:
                        logger.debug(f"Skipping exit eval for {sym}: entry order pending")
                        continue

                    # Skip swing positions — they use their own exit logic (_check_swing_exits)
                    if getattr(pos, 'strategy_id', '') == 'swing_stage2':
                        pos.update_tracking(price, now_str)
                        continue

                    pos.update_tracking(price, now_str)

                    # Determine which strategy to use for this position
                    _intraday_strat = self._intraday_strategies.get(pos.strategy_id)
                    _active_strat = _intraday_strat or self.strategy

                    # Strategy plugin: trailing stop update
                    if _active_strat and self.indicator_engine:
                        tick_data = self.indicator_engine.get_data(sym)
                        new_stop = _active_strat.update_trailing_stop(
                            asdict(pos), price, tick_data, now)
                        if new_stop is not None:
                            old_stop = pos.stop_price
                            pos.stop_price = new_stop
                            if abs(new_stop - old_stop) > 0.001:
                                self._add_message('strategy',
                                    f'Trailing stop {sym}: ${old_stop:.2f} -> ${new_stop:.2f}')
                                if pos.stop_order_id:
                                    try:
                                        await self._broker_cancel(pos.stop_order_id)
                                        stop_result = await self._broker_place_stop(
                                            sym, pos.remaining_shares, new_stop,
                                            0.003, pos.direction)
                                        if 'error' not in stop_result:
                                            pos.stop_order_id = stop_result.get('id', '')
                                    except Exception as e:
                                        logger.warning(f"Broker trailing stop update failed for {sym}: {e}")

                    # Strategy plugin: evaluate exit (before engine)
                    if _active_strat and self.indicator_engine:
                        tick_data = self.indicator_engine.get_data(sym)
                        strat_exit = _active_strat.evaluate_exit(
                            asdict(pos), price, tick_data, now)
                        if strat_exit is not None:
                            exit_signal = {
                                'reason': strat_exit.reason,
                                'shares': strat_exit.shares or pos.remaining_shares,
                                'is_full_close': True,
                                'trigger_price': price,
                            }

                    # Engine exit check (stop, partial, full target, time)
                    if exit_signal is None:
                        exit_signal = self.engine.evaluate_exit(sym, price, price, now)

                    # No exit signal from rules — check if LLM profit check needed
                    if exit_signal is None:
                        if (self.llm_supervisor and self.llm_supervisor.is_available()
                                and not pos.closing
                                and now_mono - pos.last_llm_profit_check >= self._LLM_PROFIT_INTERVAL):
                            _skip_llm_profit = False
                            try:
                                _entry_dt = datetime.strptime(pos.entry_time, '%Y-%m-%d %H:%M')
                                if now.tzinfo and not _entry_dt.tzinfo:
                                    _entry_dt = _entry_dt.replace(tzinfo=now.tzinfo)
                                _held_min = (now - _entry_dt).total_seconds() / 60
                                if _held_min < self.config.min_hold_minutes:
                                    _skip_llm_profit = True
                            except (ValueError, TypeError):
                                pass

                            if not _skip_llm_profit:
                                if pos.direction == 'short':
                                    _pnl_pct = (pos.entry_price - price) / pos.entry_price if pos.entry_price > 0 else 0
                                else:
                                    _pnl_pct = (price - pos.entry_price) / pos.entry_price if pos.entry_price > 0 else 0
                                _gap_fill = pos.gap_fill_pct(price)
                                if _pnl_pct < self.config.min_profit_take_pct and _gap_fill < self.config.min_gap_fill_pct:
                                    _skip_llm_profit = True

                            if pos.direction == 'short':
                                in_profit = price < pos.entry_price
                            else:
                                in_profit = price > pos.entry_price
                            if in_profit and not _skip_llm_profit:
                                pos.last_llm_profit_check = now_mono
                                need_llm_profit = True
                                pos_snapshot = asdict(pos)

                    # Check if LLM exit override needed for software stops
                    if (exit_signal is not None
                            and exit_signal['reason'] == 'stop'
                            and not (pos.stop_order_id)
                            and self.llm_supervisor and self.llm_supervisor.is_available()
                            and pos.llm_hold_overrides < self.config.llm_max_hold_overrides):
                        need_llm_exit = True
                        pos_snapshot = asdict(pos)
                        llm_exit_signal = dict(exit_signal)

                    # Fast path: non-LLM exits execute immediately under lock
                    if exit_signal is not None and not need_llm_exit:
                        if exit_signal['reason'] == 'stop' and pos.stop_order_id:
                            pass  # broker handles
                        else:
                            trade = await self._execute_exit(sym, exit_signal, price)

                # Phase 2: LLM calls OUTSIDE the lock (5-30s each)
                if need_llm_profit:
                    llm_profit = await self.llm_supervisor.evaluate_profit(
                        pos_snapshot, price, spy_change,
                        self.engine.daily_stats.pnl)
                    action = llm_profit.get('action', 'hold')
                    reasoning = llm_profit.get('reasoning', '')

                    # Phase 3: Re-acquire lock to apply LLM profit decision
                    async with self._position_lock:
                        pos = self.engine.positions.get(sym)
                        if pos and not pos.closing:
                            if action == 'close':
                                pnl_pct = pos.gap_fill_pct(price)
                                self._add_message('conversation',
                                    f'BOT: {sym} profit check ({pnl_pct:.0%} fill) | '
                                    f'RUDRA: Take profit — {reasoning}')
                                exit_signal = {
                                    'action': 'close', 'reason': 'llm_profit',
                                    'shares': pos.remaining_shares,
                                }
                                trade = await self._execute_exit(sym, exit_signal, price)
                            elif action == 'tighten_stop':
                                new_stop = llm_profit.get('new_stop', pos.stop_price)
                                if new_stop and new_stop != pos.stop_price:
                                    old_stop = pos.stop_price
                                    pos.stop_price = new_stop
                                    self._add_message('conversation',
                                        f'BOT: {sym} profit check | '
                                        f'RUDRA: Tighten stop ${old_stop:.2f} → ${new_stop:.2f} — {reasoning}')
                                    if pos.stop_order_id:
                                        try:
                                            await self._broker_cancel(pos.stop_order_id)
                                            stop_result = await self._broker_place_stop(
                                                sym, pos.remaining_shares, new_stop,
                                                0.003, pos.direction)
                                            if 'error' not in stop_result:
                                                pos.stop_order_id = stop_result.get('id', '')
                                        except Exception as e:
                                            logger.warning(f"Broker stop update failed for {sym}: {e}")

                elif need_llm_exit:
                    llm_exit = await self.llm_supervisor.evaluate_exit(
                        pos_snapshot, price, llm_exit_signal)
                    llm_action = llm_exit.get('action', 'close')

                    # Re-acquire lock to apply LLM exit decision
                    async with self._position_lock:
                        pos = self.engine.positions.get(sym)
                        if pos and not pos.closing:
                            if llm_action == 'hold':
                                pos.llm_hold_overrides += 1
                                self._add_message('conversation',
                                    f'BOT: {sym} hitting stop | '
                                    f'RUDRA: Hold ({pos.llm_hold_overrides}/'
                                    f'{self.config.llm_max_hold_overrides}) — '
                                    f'{llm_exit.get("reasoning", "")}')
                            elif llm_action == 'tighten':
                                pos.llm_hold_overrides += 1
                                new_stop = llm_exit.get('new_stop', pos.stop_price)
                                self._add_message('conversation',
                                    f'BOT: {sym} hitting stop | '
                                    f'RUDRA: Tighten ${pos.stop_price:.2f} → ${new_stop:.2f} '
                                    f'({pos.llm_hold_overrides}/{self.config.llm_max_hold_overrides}) — '
                                    f'{llm_exit.get("reasoning", "")}')
                                pos.stop_price = new_stop
                            else:
                                trade = await self._execute_exit(sym, llm_exit_signal, price)

                if trade:
                    trades_executed.append(trade)

        if trades_executed:
            await broadcast({
                'type': 'trade',
                'trades': [asdict(t) for t in trades_executed],
            })
            self._save_state()

        # Portfolio-level event detection (every 15s cycle)
        pos_dicts = {s: asdict(p) for s, p in self.engine.positions.items()}
        portfolio_events = self.event_detector.detect_position_events(
            pos_dicts, self.engine.daily_stats, self.engine.equity, prices or {})
        if portfolio_events:
            self._event_bus.push_many(portfolio_events)
            for pe in portfolio_events:
                self.journal.log('observation', 'event_detector',
                    pe.description, symbol=pe.symbol, data=pe.data)

        # Check for re-entry opportunities on stopped-out symbols
        if self.config.reentry_enabled and self.engine._stopped_today:
            now = datetime.now(ET)
            for sym, rec in list(self.engine._stopped_today.items()):
                if sym in self.engine.positions:
                    continue  # already in position
                price = prices.get(sym) if prices else None
                if not price:
                    continue
                ok_re, reason_re = self.engine.can_reenter(sym, price, now)
                if not ok_re:
                    continue
                # Build a candidate for re-entry
                re_dir = rec.direction
                re_candidate = GapCandidate(
                    symbol=sym, gap_pct=rec.gap_pct, prev_close=rec.prev_close,
                    premarket_price=price, avg_vol_20d=rec.avg_vol_20d,
                    vol_ratio=1.0, shortable=True, easy_to_borrow=True,
                    direction=re_dir,
                )
                async with self._position_lock:
                    ok, reason = self.engine.should_enter(re_candidate)
                    if not ok:
                        continue
                    re_time = now.strftime('%Y-%m-%d %H:%M')
                    re_pos = self.engine.open_position(re_candidate, price, re_time)
                    if re_pos is None:
                        continue
                    # Use tighter re-entry stop
                    if re_dir == 'long':
                        re_pos.stop_price = price * (1 - self.config.reentry_stop_pct)
                    else:
                        re_pos.stop_price = price * (1 + self.config.reentry_stop_pct)
                    rec.reentry_count += 1

                # Submit re-entry order
                re_entry_side = 'buy' if re_dir == 'long' else 'sell'
                re_side_label = 'LONG' if re_dir == 'long' else 'SHORT'
                self._add_message('entry',
                    f'RE-ENTRY {re_side_label} {re_pos.shares} {sym} @ ${price:.2f} '
                    f'(stop ${re_pos.stop_price:.2f}, {self.config.reentry_stop_pct:.1%})')

                if self.config.limit_orders_only:
                    if re_dir == 'long':
                        re_limit_px = round(price * (1 + self.config.limit_offset_pct), 2)
                    else:
                        re_limit_px = round(price * (1 - self.config.limit_offset_pct), 2)
                else:
                    re_limit_px = None

                fill = await self._broker_submit(
                    sym, re_pos.shares, re_entry_side,
                    order_type='limit' if self.config.limit_orders_only else 'market',
                    limit_price=re_limit_px,
                    timeout_sec=120.0,
                )
                async with self._position_lock:
                    if fill.is_filled:
                        re_pos.entry_fill_price = fill.filled_avg_price
                        re_pos.entry_order_id = fill.order_id
                        if fill.filled_avg_price > 0:
                            re_pos.entry_price = fill.filled_avg_price
                            if re_dir == 'long':
                                re_pos.stop_price = fill.filled_avg_price * (1 - self.config.reentry_stop_pct)
                            else:
                                re_pos.stop_price = fill.filled_avg_price * (1 + self.config.reentry_stop_pct)
                        stop_result = await self._broker_place_stop(
                            sym, fill.filled_qty, re_pos.stop_price,
                            0.003, re_dir)
                        if 'error' not in stop_result:
                            re_pos.stop_order_id = stop_result.get('id', '')
                        self._add_message('entry',
                            f'RE-ENTRY FILLED {fill.filled_qty} {sym} @ ${fill.filled_avg_price:.2f}')
                    elif fill.status == 'pending' and self.config.limit_orders_only:
                        re_pos.entry_order_id = fill.order_id
                        self._add_message('info',
                            f'RE-ENTRY {sym} limit order still open, holding (id={fill.order_id})')
                    else:
                        self._add_message('error', f'RE-ENTRY FAILED {sym}: {fill.error}')
                        if sym in self.engine.positions:
                            del self.engine.positions[sym]

        await broadcast({
            'type': 'positions_update',
            'positions': {s: asdict(p) for s, p in self.engine.positions.items()},
            'stats': asdict(self.engine.daily_stats),
            'equity': self.engine.equity,
        })

    # -------------------------------------------------------------------------
    # Swing Engine — Weekly scan + daily entry checks
    # -------------------------------------------------------------------------

    async def _run_swing_scan(self) -> None:
        """Weekly swing scan: classify universe, detect tight bases, rank candidates."""
        now = datetime.now(ET)
        today = now.strftime('%Y-%m-%d')
        logger.info("Swing scan starting for %s", today)
        self._add_message('system', f'Swing weekly scan starting ({today})')

        try:
            loader = SwingDataLoader()
            lookback_start = (now - timedelta(days=400)).strftime('%Y-%m-%d')

            # 1. Load SPY daily and aggregate to weekly for kill switch
            spy_daily = await asyncio.to_thread(
                loader.load_daily, ['SPY'], lookback_start, today)
            if spy_daily.empty:
                logger.warning("Swing scan: no SPY data")
                self._add_message('error', 'Swing scan failed: no SPY data')
                return
            spy_weekly = aggregate_to_weekly(spy_daily)

            # 2. Kill switch check
            active, reason = self._swing_kill_switch.is_active(spy_weekly)
            self._swing_kill_switch_status = {'active': active, 'reason': reason}
            logger.info("Swing kill switch: active=%s, reason=%s", active, reason)

            if not active:
                self._swing_watchlist = []
                self._swing_candidates = []
                self._swing_last_scan = today
                self._add_message('system', f'Swing scan: KILL SWITCH OFF — {reason}')
                await broadcast({'type': 'swing_scan', 'status': 'halted', 'reason': reason})
                return

            # 3. Get liquid symbols
            liquid_symbols = await asyncio.to_thread(
                loader.get_liquid_symbols,
                as_of_date=today,
                min_avg_volume=500_000,
                min_price=10.0,
                max_symbols=1500,
            )
            logger.info("Swing scan: %d liquid symbols", len(liquid_symbols))

            # 4. Load daily data for universe
            all_daily = await asyncio.to_thread(
                loader.load_daily, liquid_symbols, lookback_start, today, 0, 0)

            # 5. Classify into Weinstein stages
            stage2_syms = []
            stage_counts = {"STAGE_1": 0, "STAGE_2": 0, "STAGE_3": 0, "STAGE_4": 0, "UNCLEAR": 0}

            symbol_daily_map = {}
            symbol_weekly_map = {}
            for sym, grp in all_daily.groupby("symbol"):
                sym_str = str(sym)
                df = grp.reset_index(drop=True)
                symbol_daily_map[sym_str] = df
                if len(df) >= 40:
                    wk = aggregate_to_weekly(df)
                    symbol_weekly_map[sym_str] = wk
                    if len(wk) >= 34:
                        stage = self._swing_classifier.classify(sym_str, wk)
                        stage_counts[stage] = stage_counts.get(stage, 0) + 1
                        if stage == "STAGE_2":
                            stage2_syms.append(sym_str)

            logger.info("Swing scan: Stage 2 = %d, total classified = %d",
                        len(stage2_syms), sum(stage_counts.values()))

            # 6. Detect tight bases among Stage 2 stocks
            candidates = []
            for sym in stage2_syms:
                df = symbol_daily_map.get(sym)
                if df is None or len(df) < 40:
                    continue
                setup = self._swing_base_detector.detect(sym, df)
                if setup is not None:
                    vol_state = self._swing_volume.classify(sym, df)
                    setup['vol_state'] = vol_state
                    # Store the bias check result for entry filtering
                    sym_wk = symbol_weekly_map.get(sym)
                    bias_result = self._swing_bias.check_bias(sym, df, spy_weekly, sym_wk)
                    setup['bias'] = bias_result
                    candidates.append(setup)

            # 7. Rank by score, take top 15
            candidates.sort(key=lambda x: x['score'], reverse=True)
            self._swing_watchlist = candidates[:15]
            self._swing_candidates = candidates
            self._swing_last_scan = today

            # Reset weekly trade counter if new week
            week_key = now.isocalendar()[:2]
            wk_str = f"{week_key[0]}-W{week_key[1]}"
            if wk_str != self._swing_week_key:
                self._swing_week_key = wk_str
                self._swing_weekly_trades = 0

            syms_list = [c['symbol'] for c in self._swing_watchlist]
            self._add_message('system',
                f'Swing scan complete: {len(stage2_syms)} Stage 2 stocks, '
                f'{len(candidates)} tight bases, top 15: {syms_list}')
            logger.info("Swing scan complete: watchlist=%s", syms_list)

            await broadcast({
                'type': 'swing_scan',
                'status': 'complete',
                'stage2_count': len(stage2_syms),
                'candidates': len(candidates),
                'watchlist': syms_list,
                'stage_counts': stage_counts,
            })

        except Exception as e:
            logger.error("Swing scan failed: %s", e, exc_info=True)
            self._add_message('error', f'Swing scan failed: {e}')

    async def _check_swing_entries(self) -> None:
        """Check swing watchlist for entry signals during market hours."""
        if not self._swing_enabled or not self._swing_watchlist:
            return
        if self._trading_halted:
            return

        now = datetime.now(ET)
        now_mono = _time.monotonic()

        # Throttle: check every 5 minutes
        if now_mono - self._swing_last_entry_check < 300:
            return
        self._swing_last_entry_check = now_mono

        # Only enter 10 AM - 3 PM
        if now.hour < 10 or now.hour >= 15:
            return

        # Weekly trade limit
        if self._swing_weekly_trades >= self.config.swing_max_weekly_trades:
            return

        # Count current swing positions
        swing_positions = {sym: pos for sym, pos in self.engine.positions.items()
                          if getattr(pos, 'strategy_id', '') == 'swing_stage2'}
        if len(swing_positions) >= self.config.swing_max_positions:
            return

        # Combined max positions check
        total_positions = len(self.engine.positions)
        combined_max = self.config.max_positions + self.config.swing_max_positions
        if total_positions >= combined_max:
            return

        held_symbols = set(self.engine.positions.keys())

        # Get snapshot prices for all watchlist symbols
        watchlist_syms = [c['symbol'] for c in self._swing_watchlist
                         if c['symbol'] not in held_symbols]
        if not watchlist_syms:
            return

        try:
            prices = await self._broker_get_prices(watchlist_syms)
        except Exception as e:
            logger.warning("Swing entry check: failed to get prices: %s", e)
            return

        # Load daily bars for EMA calculations
        loader = SwingDataLoader()
        lookback_start = (now - timedelta(days=200)).strftime('%Y-%m-%d')
        today = now.strftime('%Y-%m-%d')

        for cand in self._swing_watchlist:
            if self._swing_weekly_trades >= self.config.swing_max_weekly_trades:
                break
            if len(swing_positions) >= self.config.swing_max_positions:
                break

            sym = cand['symbol']
            if sym in held_symbols:
                continue

            price = prices.get(sym, 0.0)
            if price <= 0:
                continue

            # Check bias — if stored from scan, use it; otherwise skip
            bias = cand.get('bias', {})
            if not bias.get('all_pass', False):
                continue

            # Load daily bars for EMA zone check
            try:
                sym_daily = await asyncio.to_thread(
                    loader.load_daily, [sym], lookback_start, today)
                if sym_daily.empty or len(sym_daily) < 50:
                    continue
            except Exception:
                continue

            closes = sym_daily['close'].astype(float)
            volumes = sym_daily['volume'].astype(float)

            # EMA zone check: price in 9-21 EMA zone
            # swing_ema imported at module level
            ema9 = float(swing_ema(closes, 9).iloc[-1])
            ema21 = float(swing_ema(closes, 21).iloc[-1])
            ema_low = min(ema9, ema21)
            ema_high = max(ema9, ema21)

            if not (ema_low * 0.99 <= price <= ema_high * 1.01):
                continue

            # Volume check: current volume below average (healthy pullback)
            if len(volumes) >= 20:
                vol_avg = volumes.iloc[-20:].mean()
                if vol_avg > 0 and volumes.iloc[-1] / vol_avg > 0.80:
                    continue

            # Stop = swing low of last 10 bars
            swing_low = float(sym_daily['low'].astype(float).iloc[-10:].min())
            stop_price = swing_low * 0.995  # tiny buffer below swing low
            risk_per_share = price - stop_price
            if risk_per_share <= 0 or risk_per_share / price > 0.08:
                continue

            # Position sizing: equity * risk_pct / risk_per_share
            risk_amount = self.engine.equity * self.config.swing_risk_pct
            shares = int(risk_amount / risk_per_share)
            if shares <= 0:
                continue

            # Max 25% of equity per position
            cost = shares * price
            if cost > self.engine.equity * 0.25:
                shares = int(self.engine.equity * 0.25 / price)
                if shares <= 0:
                    continue

            # LLM Pre-Entry Debate (optional — uses local Ollama)
            llm_approved = True
            try:
                from pre_entry_debate import PreEntryDebate
                debate = PreEntryDebate()
                if debate.enabled:
                    result = await debate.evaluate(sym, {
                        'direction': 'long',
                        'strategy_id': 'swing_stage2',
                        'entry_price': price,
                        'stop_price': stop_price,
                        'target_price': price + 2 * risk_per_share,
                        'rr_ratio': round(2 * risk_per_share / risk_per_share, 1) if risk_per_share > 0 else 0,
                        'ema9': ema9,
                        'ema21': ema21,
                        'stage': cand.get('stage', 'STAGE_2'),
                        'tight_base_score': cand.get('score', 0),
                        'volume_state': 'pullback_low',
                    })
                    llm_approved = result.approved
                    self._add_message('system',
                        f'Swing LLM debate {sym}: {"PROCEED" if result.approved else "REJECT"} '
                        f'({result.confidence:.0%}) — {result.verdict[:80]}')
                    if not result.approved:
                        logger.info(f"Swing entry REJECTED by LLM: {sym} — {result.verdict}")
                        continue
            except ImportError:
                pass  # pre_entry_debate not available, skip
            except Exception as e:
                logger.debug(f"Swing LLM debate error for {sym}: {e}")
                # On error, proceed (don't block on LLM failure)

            # Submit entry order via broker
            logger.info("Swing entry: %s %d shares @ ~$%.2f, stop $%.2f",
                        sym, shares, price, stop_price)
            self._add_message('system',
                f'Swing entry signal: {sym} {shares} shares @ ~${price:.2f}, stop ${stop_price:.2f}')

            try:
                async with self._position_lock:
                    fill = await self._broker_submit(sym, shares, 'buy',
                                                     order_type='market')
                    if fill and not fill.error:
                        entry_price = fill.avg_price or price
                        target_price = entry_price + 2 * risk_per_share

                        pos = GapPosition(
                            symbol=sym,
                            shares=shares,
                            entry_price=entry_price,
                            stop_price=stop_price,
                            half_target=target_price,
                            full_target=target_price,
                            prev_close=float(closes.iloc[-1]),
                            entry_time=now.strftime('%Y-%m-%d %H:%M'),
                            remaining_shares=shares,
                            entry_order_id=fill.order_id or '',
                            entry_fill_price=entry_price,
                            direction='long',
                            strategy_id='swing_stage2',
                            source='swing',
                        )
                        self.engine.positions[sym] = pos
                        held_symbols.add(sym)
                        swing_positions[sym] = pos
                        self._swing_weekly_trades += 1
                        self._save_state()

                        self._add_message('entry',
                            f'SWING ENTRY: {sym} {shares} shares LONG @ ${entry_price:.2f}, '
                            f'stop ${stop_price:.2f}, target ${target_price:.2f}')
                        logger.info("Swing entry filled: %s %d @ $%.2f", sym, shares, entry_price)

                        # Place broker-side stop
                        try:
                            stop_result = await self._broker_place_stop(
                                sym, shares, stop_price, 0.003, 'long')
                            if 'error' not in stop_result:
                                pos.stop_order_id = stop_result.get('id', '')
                        except Exception as e:
                            logger.warning("Swing stop placement failed for %s: %s", sym, e)

                        await broadcast({
                            'type': 'positions_update',
                            'positions': {s: asdict(p) for s, p in self.engine.positions.items()},
                            'stats': asdict(self.engine.daily_stats),
                            'equity': self.engine.equity,
                        })
                    else:
                        err_msg = fill.error if fill else 'No fill returned'
                        self._add_message('error', f'Swing entry FAILED {sym}: {err_msg}')
                        logger.warning("Swing entry failed for %s: %s", sym, err_msg)

            except Exception as e:
                logger.error("Swing entry exception for %s: %s", sym, e, exc_info=True)
                self._add_message('error', f'Swing entry exception {sym}: {e}')

    async def _check_swing_exits(self) -> None:
        """Check swing positions for exit signals.

        Exit rules (different from gap fade):
        1. At +1R: move stop to breakeven
        2. At +2R: exit 50%, trail rest below 21 EMA
        3. Close < 50 EMA: exit all
        4. 3 consecutive non-higher daily closes + volume declining: exit
        """
        swing_positions = {sym: pos for sym, pos in self.engine.positions.items()
                          if getattr(pos, 'strategy_id', '') == 'swing_stage2'}
        if not swing_positions:
            return

        now = datetime.now(ET)
        loader = SwingDataLoader()
        lookback_start = (now - timedelta(days=200)).strftime('%Y-%m-%d')
        today = now.strftime('%Y-%m-%d')

        # Get current prices
        try:
            prices = await self._broker_get_prices(list(swing_positions.keys()))
        except Exception:
            return

        for sym, pos in list(swing_positions.items()):
            price = prices.get(sym, 0.0)
            if price <= 0:
                continue

            risk_per_share = pos.entry_price - pos.stop_price if not pos.stop_at_breakeven else pos.initial_risk if hasattr(pos, 'initial_risk') else (pos.entry_price - pos.stop_price)
            # Use the original risk from entry
            # GapPosition doesn't have initial_risk, so compute from gap_pct or original stop
            if pos.entry_fill_price > 0 and pos.entry_price > 0:
                # We store original stop in stop_price initially
                # After breakeven move, we need original risk
                # Approximate: half_target = entry + 2R, so R = (half_target - entry) / 2
                initial_risk = (pos.half_target - pos.entry_price) / 2.0 if pos.half_target > pos.entry_price else pos.entry_price * 0.02
            else:
                initial_risk = pos.entry_price * 0.02

            if initial_risk <= 0:
                continue

            pnl_per_share = price - pos.entry_price  # long position
            r_multiple = pnl_per_share / initial_risk

            # 1. At +1R: move stop to breakeven
            if r_multiple >= 1.0 and pos.stop_price < pos.entry_price:
                new_stop = pos.entry_price + 0.01
                logger.info("Swing %s: +1R reached, moving stop to breakeven $%.2f", sym, new_stop)
                self._add_message('system', f'Swing {sym}: +1R — stop moved to breakeven ${new_stop:.2f}')
                async with self._position_lock:
                    p = self.engine.positions.get(sym)
                    if p:
                        p.stop_price = new_stop
                        # Update broker stop
                        if p.stop_order_id:
                            try:
                                await self._broker_cancel(p.stop_order_id)
                                stop_result = await self._broker_place_stop(sym, p.remaining_shares, new_stop, 0.003, 'long')
                                if 'error' not in stop_result:
                                    p.stop_order_id = stop_result.get('id', '')
                            except Exception as e:
                                logger.warning("Swing breakeven stop update failed for %s: %s", sym, e)

            # 2. At +2R: exit 50% if not already partial
            if r_multiple >= 2.0 and not pos.partial_filled:
                exit_shares = pos.remaining_shares // 2
                if exit_shares > 0:
                    logger.info("Swing %s: +2R, exiting %d shares (50%%)", sym, exit_shares)
                    try:
                        async with self._position_lock:
                            p = self.engine.positions.get(sym)
                            if p and not p.partial_filled:
                                exit_signal = {
                                    'reason': 'swing_partial_2R',
                                    'shares': exit_shares,
                                    'is_full_close': False,
                                    'trigger_price': price,
                                }
                                trade = await self._execute_exit(sym, exit_signal, price)
                                if trade:
                                    self._add_message('exit',
                                        f'SWING PARTIAL {sym}: {exit_shares} shares @ ${price:.2f} (+2R), '
                                        f'P&L ${trade.pnl:+,.2f}')
                    except Exception as e:
                        logger.error("Swing partial exit failed for %s: %s", sym, e)

            # Trail remaining below 21 EMA after partial
            if pos.partial_filled:
                try:
                    sym_daily = await asyncio.to_thread(
                        loader.load_daily, [sym], lookback_start, today)
                    if not sym_daily.empty and len(sym_daily) >= 21:
                        # swing_ema imported at module level
                        ema21_val = float(swing_ema(sym_daily['close'].astype(float), 21).iloc[-1])
                        new_stop = ema21_val * 0.995
                        if new_stop > pos.stop_price:
                            async with self._position_lock:
                                p = self.engine.positions.get(sym)
                                if p:
                                    old_stop = p.stop_price
                                    p.stop_price = new_stop
                                    self._add_message('system',
                                        f'Swing {sym}: trailing stop ${old_stop:.2f} -> ${new_stop:.2f} (21 EMA)')
                                    if p.stop_order_id:
                                        try:
                                            await self._broker_cancel(p.stop_order_id)
                                            stop_result = await self._broker_place_stop(sym, p.remaining_shares, new_stop, 0.003, 'long')
                                            if 'error' not in stop_result:
                                                p.stop_order_id = stop_result.get('id', '')
                                        except Exception as e:
                                            logger.warning("Swing 21 EMA trail update failed for %s: %s", sym, e)
                except Exception:
                    pass

            # 3. Close < 50 EMA: exit all
            try:
                sym_daily = await asyncio.to_thread(
                    loader.load_daily, [sym], lookback_start, today)
                if not sym_daily.empty and len(sym_daily) >= 50:
                    # swing_ema imported at module level
                    ema50_val = float(swing_ema(sym_daily['close'].astype(float), 50).iloc[-1])
                    if price < ema50_val:
                        logger.info("Swing %s: price $%.2f < 50 EMA $%.2f — exiting", sym, price, ema50_val)
                        self._add_message('system', f'Swing {sym}: below 50 EMA (${ema50_val:.2f}) — closing')
                        async with self._position_lock:
                            p = self.engine.positions.get(sym)
                            if p:
                                exit_signal = {
                                    'reason': 'swing_below_50ema',
                                    'shares': p.remaining_shares,
                                    'is_full_close': True,
                                    'trigger_price': price,
                                }
                                trade = await self._execute_exit(sym, exit_signal, price)
                                if trade:
                                    self._add_message('exit',
                                        f'SWING EXIT {sym}: below 50 EMA @ ${price:.2f}, '
                                        f'P&L ${trade.pnl:+,.2f}')
                        continue

                    # 4. 3 consecutive non-higher closes + declining volume
                    if len(sym_daily) >= 4:
                        recent = sym_daily.iloc[-4:]
                        recent_closes = recent['close'].astype(float).values
                        recent_vols = recent['volume'].astype(float).values
                        non_higher = all(recent_closes[i] <= recent_closes[i - 1] for i in range(1, 4))
                        vol_declining = all(recent_vols[i] <= recent_vols[i - 1] for i in range(1, 4))
                        if non_higher and vol_declining:
                            logger.info("Swing %s: stall exit (3 non-higher closes + declining vol)", sym)
                            self._add_message('system', f'Swing {sym}: stall pattern — closing')
                            async with self._position_lock:
                                p = self.engine.positions.get(sym)
                                if p:
                                    exit_signal = {
                                        'reason': 'swing_stall',
                                        'shares': p.remaining_shares,
                                        'is_full_close': True,
                                        'trigger_price': price,
                                    }
                                    trade = await self._execute_exit(sym, exit_signal, price)
                                    if trade:
                                        self._add_message('exit',
                                            f'SWING EXIT {sym}: stall pattern @ ${price:.2f}, '
                                            f'P&L ${trade.pnl:+,.2f}')
            except Exception as e:
                logger.warning("Swing exit check failed for %s: %s", sym, e)

    async def _swing_classify_symbol(self, symbol: str) -> dict:
        """Classify a single stock's Weinstein stage and return full analysis."""
        loader = SwingDataLoader()
        today = datetime.now(ET).strftime('%Y-%m-%d')
        lookback_start = (datetime.now(ET) - timedelta(days=600)).strftime('%Y-%m-%d')

        sym_daily = await asyncio.to_thread(
            loader.load_daily, [symbol], lookback_start, today)
        spy_daily = await asyncio.to_thread(
            loader.load_daily, ['SPY'], lookback_start, today)

        if sym_daily.empty:
            return {'error': f'No data found for {symbol}'}

        sym_weekly = aggregate_to_weekly(sym_daily)
        spy_weekly = aggregate_to_weekly(spy_daily)

        stage = self._swing_classifier.classify(symbol, sym_weekly)
        vol_state = self._swing_volume.classify(symbol, sym_daily)
        trend = self._swing_volume.trend_health(symbol, sym_daily)
        bias_result = self._swing_bias.check_bias(symbol, sym_daily, spy_weekly, sym_weekly)

        last_close = float(sym_daily['close'].iloc[-1])
        last_date = str(sym_daily['date'].iloc[-1])

        result = {
            'symbol': symbol,
            'last_close': last_close,
            'last_date': last_date,
            'stage': stage,
            'volume_state': vol_state,
            'trend_health': trend,
            'bias': bias_result,
        }

        # Tight base detection
        setup = self._swing_base_detector.detect(symbol, sym_daily)
        if setup:
            result['tight_base'] = setup
        else:
            result['tight_base'] = None

        return result

    # -------------------------------------------------------------------------
    # P0-5: EOD Close — retry loop with broker verification
    # -------------------------------------------------------------------------

    async def _eod_close(self):
        """Force close all positions at end of day with retry and verification.

        Swing positions (strategy_id='swing_stage2') are SKIPPED — they hold
        overnight for days/weeks. Only gap fade and intraday positions are closed.
        """
        self._add_message('system', 'EOD — closing all positions (with verification)')
        logger.info("EOD close initiated")

        # Cancel ALL open orders for each position symbol (stops, pending entries, etc.)
        # This ensures shares are not held_for_orders when we submit the cover.
        # Skip swing positions — they hold overnight.
        symbols_with_positions = [
            sym for sym in self.engine.positions.keys()
            if getattr(self.engine.positions[sym], 'strategy_id', '') != 'swing_stage2'
        ]
        _swing_held = [
            sym for sym in self.engine.positions.keys()
            if getattr(self.engine.positions[sym], 'strategy_id', '') == 'swing_stage2'
        ]
        if _swing_held:
            logger.info("EOD: skipping %d swing positions (hold overnight): %s", len(_swing_held), _swing_held)
            self._add_message('system', f'EOD: holding {len(_swing_held)} swing positions overnight: {_swing_held}')
        _total_cancelled = 0
        for sym in symbols_with_positions:
            if self._use_ibkr:
                pos = self.engine.positions.get(sym)
                if pos and pos.stop_order_id:
                    if await self._broker_cancel(pos.stop_order_id):
                        _total_cancelled += 1
            else:
                n = await asyncio.to_thread(alpaca_cancel_open_orders_for_symbol, sym)
                _total_cancelled += n
            pos = self.engine.positions.get(sym)
            if pos:
                pos.stop_order_id = ''
        if _total_cancelled > 0:
            logger.info(f"EOD: cancelled {_total_cancelled} open orders, waiting for release")
            await asyncio.sleep(2)  # let Alpaca release held shares

        max_retries = 3
        for attempt in range(max_retries):
            # Check if only swing positions remain (they don't need closing)
            non_swing = [sym for sym in self.engine.positions.keys()
                        if getattr(self.engine.positions[sym], 'strategy_id', '') != 'swing_stage2']
            if not non_swing:
                break

            symbols_to_close = non_swing

            # On retry, cancel any new open orders that may have appeared
            if attempt > 0:
                for sym in symbols_to_close:
                    if self._use_ibkr:
                        pos = self.engine.positions.get(sym)
                        if pos and pos.stop_order_id:
                            await self._broker_cancel(pos.stop_order_id)
                    else:
                        await asyncio.to_thread(alpaca_cancel_open_orders_for_symbol, sym)
                await asyncio.sleep(2)

            for sym in symbols_to_close:
                async with self._position_lock:
                    pos = self.engine.positions.get(sym)
                    if pos is None or pos.closing:
                        continue

                    price = 0.0
                    if self.streamer and self.streamer.latest_prices:
                        price = self.streamer.latest_prices.get(sym, 0.0)
                    if price <= 0:
                        try:
                            snap_prices = await self._broker_get_prices([sym])
                            price = snap_prices.get(sym, 0.0)
                        except Exception:
                            pass
                    if price <= 0:
                        price = pos.entry_price  # fallback

                    exit_signal = {'reason': 'eod', 'shares': pos.remaining_shares,
                                   'is_full_close': True, 'trigger_price': price}
                    trade = await self._execute_exit(sym, exit_signal, price)

                if trade:
                    await broadcast({'type': 'trade', 'trades': [asdict(trade)]})

            # Verify with broker that positions are actually closed
            await asyncio.sleep(2)  # give broker time to settle
            broker_positions = await self._broker_get_positions()
            tracked_syms = set(self.engine.positions.keys())
            broker_remaining = [p for p in broker_positions
                                if p.get('symbol') in tracked_syms]

            if not broker_remaining:
                logger.info("EOD close verified: no broker positions remaining")
                self._add_message('system', 'EOD close verified — all positions closed')
                break

            remaining = [p['symbol'] for p in broker_remaining]
            logger.warning(f"EOD close attempt {attempt + 1}/{max_retries}: "
                          f"broker still has positions: {remaining}")
            self._add_message('warning',
                f'EOD retry {attempt + 1}: {len(remaining)} positions still on broker: {remaining}')

            # Clear closing flags for retry
            async with self._position_lock:
                for sym in remaining:
                    if sym in self.engine.positions:
                        self.engine.positions[sym].closing = False

            if attempt < max_retries - 1:
                await asyncio.sleep(3)  # wait before retry

        # Final safety: use broker close-position API as last resort
        broker_positions = await self._broker_get_positions()
        tracked_syms = set(self.engine.positions.keys())
        broker_remaining = [p for p in broker_positions
                            if p.get('symbol') in tracked_syms]
        if broker_remaining:
            remaining_syms = [p['symbol'] for p in broker_remaining]
            logger.warning(f"EOD: using broker close-position API for stubborn positions: {remaining_syms}")
            self._add_message('warning', f'EOD fallback: using broker liquidation API for {remaining_syms}')
            for sym in remaining_syms:
                # Cancel any remaining orders first
                if not self._use_ibkr:
                    await asyncio.to_thread(alpaca_cancel_open_orders_for_symbol, sym)
                await asyncio.sleep(1)
                result = await self._broker_close_position(sym)
                if 'error' not in result:
                    logger.info(f"EOD fallback: {sym} closed via broker API")
                    # Reconcile engine state
                    pos = self.engine.positions.get(sym)
                    if pos:
                        fill_price = float(result.get('filled_avg_price', 0)) or pos.entry_price
                        now = datetime.now(ET)
                        trade = self.engine.confirm_exit(sym, pos.remaining_shares, fill_price, 'eod', now)
                        if trade:
                            self._add_message('exit',
                                f'EOD FALLBACK {sym} @ ${fill_price:.2f} P&L: ${trade.pnl:.2f}')
                            await broadcast({'type': 'trade', 'trades': [asdict(trade)]})
                else:
                    logger.error(f"EOD fallback FAILED for {sym}: {result['error']}")

            # Final verification
            await asyncio.sleep(2)
            broker_positions = await self._broker_get_positions()
            broker_remaining = [p for p in broker_positions
                                if p.get('symbol') in tracked_syms]
            if broker_remaining:
                remaining = [(p['symbol'], p.get('qty')) for p in broker_remaining]
                logger.error(f"CRITICAL: EOD close FAILED after all retries + fallback! "
                            f"Remaining broker positions: {remaining}")
                # Mark surviving positions for close-on-open next trading day
                for sym, _qty in remaining:
                    if sym in self.engine.positions:
                        self.engine.positions[sym].close_on_open = True
                        self.engine.positions[sym].closing = False
                        logger.info(f"Marked {sym} for close-on-open")
                self._save_state()
                self._add_message('error',
                    f'EOD close failed — {len(remaining)} positions marked for close at next market open: '
                    f'{[s for s, _ in remaining]}')
                await self.alerter.send('EOD CLOSE FAILED — will retry at open',
                    f'Positions marked for close-on-open:\n'
                    f'{remaining}\nWill auto-close when market opens.',
                    level='error')

        if self.streamer:
            await self.streamer.stop()
            self.streamer = None

        # Clean up any remaining internal positions (broker is truth)
        async with self._position_lock:
            if not broker_remaining:
                for sym in list(self.engine.positions.keys()):
                    del self.engine.positions[sym]

        self._save_state()

    # -------------------------------------------------------------------------
    # EOD Watchdog — independent task guaranteeing position close
    # -------------------------------------------------------------------------

    async def _eod_watchdog(self) -> None:
        """Independent EOD guardian task. Runs as a separate asyncio.Task.

        Architecture: This task is completely independent of the trading loop.
        It cannot be blocked by LLM calls, standdown sleeps, or any other
        trading loop operation. It fires on a wall-clock schedule.

        Timeline (all times Eastern):
            3:45 PM — Circuit breaker: block new entries
            3:50 PM — EOD close: cancel stops, close all positions
            3:55 PM — Force close: retry any remaining positions
            4:00 PM — Emergency liquidation: Alpaca DELETE API
            4:05 PM — Final audit: alert if anything remains

        SLA: 100% execution rate. Zero tolerance for missed deadlines.
        """
        logger.info("EOD watchdog started — independent guardian task active")
        _last_date = ''
        _did_primary_close = False
        _did_force_close = False
        _did_emergency = False
        _did_audit = False

        while True:
            try:
                now = datetime.now(ET)
                today = now.strftime('%Y-%m-%d')

                # Reset for new day
                if today != _last_date:
                    _last_date = today
                    self._trading_halted = False
                    _did_primary_close = False
                    _did_force_close = False
                    _did_emergency = False
                    _did_audit = False

                # Only run on weekdays
                if now.weekday() >= 5:
                    # Weekend — sleep until Monday 6 AM
                    days_until_monday = 7 - now.weekday()
                    monday_6am = (now + timedelta(days=days_until_monday)).replace(
                        hour=6, minute=0, second=0, microsecond=0)
                    await asyncio.sleep(max(1, (monday_6am - now).total_seconds()))
                    continue

                # ── PHASE 1: Wait until 3:45 PM ET ──
                target_345 = now.replace(hour=15, minute=45, second=0, microsecond=0)
                if now < target_345:
                    sleep_sec = (target_345 - now).total_seconds()
                    # Sleep in 60s chunks so we don't miss day transitions
                    await asyncio.sleep(min(sleep_sec, 60))
                    continue

                # ── PHASE 2: 3:45 PM — Circuit Breaker ──
                if not self._trading_halted and now.hour == 15 and now.minute >= 45:
                    self._trading_halted = True
                    logger.info("EOD WATCHDOG [3:45 PM]: Circuit breaker ENGAGED — new entries blocked")
                    self._add_message('system',
                        'EOD circuit breaker active — no new entries allowed')
                    await self.alerter.send('EOD Circuit Breaker',
                        'Trading halted at 3:45 PM. EOD close sequence starting in 5 minutes.',
                        level='info', throttle_key='eod_cb')
                    await broadcast({'type': 'live_status', 'status': 'eod_closing'})

                # ── PHASE 3: 3:50 PM — Primary EOD Close ──
                target_350 = now.replace(hour=15, minute=50, second=0, microsecond=0)
                if now >= target_350 and now.hour == 15 and now.minute >= 50 and not _did_primary_close:
                    _did_primary_close = True
                    if self.engine.positions:
                        n_pos = len(self.engine.positions)
                        symbols = list(self.engine.positions.keys())
                        logger.info(f"EOD WATCHDOG [3:50 PM]: Closing {n_pos} positions: {symbols}")
                        self._add_message('system',
                            f'EOD watchdog: closing {n_pos} positions: {symbols}')

                        # Performance snapshot before close
                        self._record_performance_snapshot('eod')

                        # Execute close with 60-second hard timeout
                        try:
                            await asyncio.wait_for(self._eod_close(), timeout=60)
                            logger.info("EOD WATCHDOG [3:50 PM]: _eod_close completed")
                        except asyncio.TimeoutError:
                            logger.error("EOD WATCHDOG: _eod_close TIMED OUT after 60s — "
                                        "escalating to force close")
                            self._add_message('error',
                                'EOD close timed out after 60s — escalating')
                            await self.alerter.send('EOD Close Timeout',
                                f'_eod_close did not complete in 60s. '
                                f'Remaining: {list(self.engine.positions.keys())}',
                                level='error')
                    else:
                        logger.info("EOD WATCHDOG [3:50 PM]: No positions to close")
                        self._record_performance_snapshot('eod')

                    # Run LLM debrief (non-critical, 15s timeout, fire-and-forget)
                    try:
                        if self.llm_supervisor and self.llm_supervisor.is_available():
                            state = self._build_llm_state(datetime.now(ET))
                            debrief = await asyncio.wait_for(
                                self.llm_supervisor.eod_debrief(
                                    state, event_queue=self._event_bus),
                                timeout=15)
                            if debrief:
                                self._add_message('conversation',
                                    f'BOT: Day wrap-up | RUDRA: {debrief}')
                                await broadcast({'type': 'conversation',
                                    'speaker': 'rudra', 'text': debrief})
                    except (asyncio.TimeoutError, Exception) as e:
                        logger.warning(f"EOD debrief skipped: {e}")

                    # Wait for force-close window
                    await asyncio.sleep(5)

                # ── PHASE 4: 3:55 PM — Force Close (retry remaining) ──
                target_355 = now.replace(hour=15, minute=55, second=0, microsecond=0)
                now = datetime.now(ET)  # refresh
                if now >= target_355 and now.hour == 15 and now.minute >= 55 and not _did_force_close:
                    _did_force_close = True
                    # Skip swing positions — they hold overnight
                    remaining = [sym for sym in self.engine.positions.keys()
                                if getattr(self.engine.positions[sym], 'strategy_id', '') != 'swing_stage2']
                    if remaining:
                        logger.error(f"EOD WATCHDOG [3:55 PM]: FORCE CLOSE — "
                                    f"{len(remaining)} positions still open: {remaining}")
                        self._add_message('error',
                            f'EOD force close: {remaining} still open after primary close')
                        await self.alerter.send('EOD FORCE CLOSE',
                            f'Positions still open at 3:55 PM after primary close.\n'
                            f'Symbols: {remaining}\nForce closing via Alpaca API.',
                            level='error')

                        # Use broker close-position API directly
                        for sym in remaining:
                            try:
                                if not self._use_ibkr:
                                    await asyncio.to_thread(
                                        alpaca_cancel_open_orders_for_symbol, sym)
                                await asyncio.sleep(1)
                                result = await self._broker_close_position(sym)
                                if 'error' not in result:
                                    logger.info(f"EOD WATCHDOG: {sym} force-closed via API")
                                    pos = self.engine.positions.get(sym)
                                    if pos:
                                        fill = float(result.get('filled_avg_price', 0)
                                                     ) or pos.entry_price
                                        trade = self.engine.confirm_exit(
                                            sym, pos.remaining_shares, fill, 'eod_force',
                                            datetime.now(ET))
                                        if trade:
                                            self._add_message('exit',
                                                f'FORCE CLOSE {sym} @ ${fill:.2f} '
                                                f'P&L: ${trade.pnl:+,.2f}')
                                            await broadcast({
                                                'type': 'trade',
                                                'trades': [asdict(trade)]})
                                else:
                                    logger.error(f"EOD WATCHDOG: force close FAILED "
                                                f"for {sym}: {result.get('error')}")
                            except Exception as e:
                                logger.error(f"EOD WATCHDOG: force close exception "
                                            f"for {sym}: {e}")

                # ── PHASE 5: 4:00 PM — Emergency Liquidation ──
                now = datetime.now(ET)
                # Skip swing positions — they hold overnight
                _emergency_remaining = [sym for sym in self.engine.positions.keys()
                                       if getattr(self.engine.positions[sym], 'strategy_id', '') != 'swing_stage2']
                if now.hour >= 16 and _emergency_remaining and not _did_emergency:
                    _did_emergency = True
                    remaining = _emergency_remaining
                    logger.error(f"EOD WATCHDOG [4:00 PM]: EMERGENCY — "
                                f"{len(remaining)} positions STILL open after all attempts")
                    self._add_message('error',
                        f'EMERGENCY: {remaining} open after 4 PM — marking for close-on-open')
                    await self.alerter.send('EMERGENCY: Positions Open After Hours',
                        f'All EOD close attempts failed.\n'
                        f'Positions: {remaining}\n'
                        f'Marked for close-on-open next trading day.\n'
                        f'MANUAL INTERVENTION MAY BE REQUIRED.',
                        level='error')

                    # Mark for close-on-open (not swing positions)
                    for sym in remaining:
                        if sym in self.engine.positions:
                            self.engine.positions[sym].close_on_open = True
                            self.engine.positions[sym].closing = False
                    self._save_state()

                # ── PHASE 6: 4:05 PM — Final Audit ──
                now = datetime.now(ET)
                if now.hour >= 16 and now.minute >= 5 and not _did_audit:
                    _did_audit = True
                    # Verify with broker directly
                    try:
                        broker_positions = await self._broker_get_positions()
                        if broker_positions:
                            broker_syms = [p.get('symbol') for p in broker_positions]
                            logger.error(f"EOD WATCHDOG AUDIT: Broker still has "
                                        f"positions: {broker_syms}")
                            await self.alerter.send('EOD Audit: Broker Positions Remain',
                                f'After all close attempts, broker reports:\n'
                                f'{broker_syms}\nManual action required.',
                                level='error')
                        else:
                            logger.info("EOD WATCHDOG AUDIT: Broker confirms zero positions")
                    except Exception as e:
                        logger.error(f"EOD WATCHDOG AUDIT: Could not verify broker: {e}")

                    # Done for today — sleep until tomorrow 6 AM
                    tomorrow_6am = (now + timedelta(days=1)).replace(
                        hour=6, minute=0, second=0, microsecond=0)
                    sleep_sec = max(60, (tomorrow_6am - now).total_seconds())
                    logger.info(f"EOD watchdog: day complete, sleeping until "
                               f"{tomorrow_6am.strftime('%Y-%m-%d %H:%M')} ET")
                    await asyncio.sleep(sleep_sec)
                    continue

                # Between phases — short sleep to stay responsive
                await asyncio.sleep(5)

            except asyncio.CancelledError:
                logger.info("EOD watchdog cancelled")
                raise
            except Exception as e:
                logger.error(f"EOD WATCHDOG ERROR (will retry in 10s): {e}",
                            exc_info=True)
                self._add_message('error', f'EOD watchdog error: {e}')
                await self.alerter.send('EOD Watchdog Error',
                    f'EOD watchdog encountered error: {e}\nWill retry in 10s.',
                    level='error')
                await asyncio.sleep(10)

    # -------------------------------------------------------------------------
    # EOD bar storage — store today's closing prices for next-day gap scan
    # -------------------------------------------------------------------------

    async def _verify_daily_bars(self):
        """Pre-market check: ensure yesterday's daily bars are complete.

        If yesterday has < 10,000 symbols, trigger a full backfill from Alpaca.
        This prevents the gap scanner from missing candidates when the EOD bar
        storage failed (bot crash, partial run, etc.).
        """
        MIN_SYMBOLS = 10000
        try:
            db = get_price_db()
            cur = db._conn.cursor()

            # Find the last 3 trading days in the DB
            cur.execute(
                "SELECT date, COUNT(*) AS cnt FROM daily_bars "
                "WHERE date::date >= CURRENT_DATE - INTERVAL '7 days' "
                "GROUP BY date ORDER BY date DESC LIMIT 5")
            rows = cur.fetchall()

            dates_to_fix = []
            for date_val, cnt in rows:
                if cnt < MIN_SYMBOLS:
                    dates_to_fix.append((str(date_val), cnt))

            if not dates_to_fix:
                return

            for date_str, cnt in dates_to_fix:
                logger.warning(f"Daily bars incomplete: {date_str} has {cnt} symbols "
                              f"(need {MIN_SYMBOLS}+) — backfilling")
                self._add_message('system',
                    f'Backfilling daily bars for {date_str} ({cnt} → full universe)')

            # Fetch all active tradeable symbols from Alpaca
            cfg = _get_alpaca_config()
            if cfg is None:
                logger.error("Cannot backfill daily bars: no Alpaca config")
                return
            headers = _alpaca_headers(cfg)

            resp = await asyncio.to_thread(
                requests.get, 'https://api.alpaca.markets/v2/assets',
                headers=headers,
                params={'status': 'active', 'asset_class': 'us_equity'},
                timeout=60)
            if resp.status_code != 200:
                logger.error(f"Assets API failed: {resp.status_code}")
                return
            valid_exchanges = {'NYSE', 'NASDAQ', 'ARCA', 'AMEX', 'BATS', 'NYSEARCA'}
            symbols = [a['symbol'] for a in resp.json()
                       if a.get('tradable') and a.get('exchange') in valid_exchanges]
            logger.info(f"Daily bar backfill: {len(symbols)} tradeable symbols")

            # Determine date range to backfill
            earliest = min(d for d, _ in dates_to_fix)
            latest_date = datetime.now(ET).strftime('%Y-%m-%d')

            # Fetch bars in batches
            batch_size = 1500
            total_stored = 0
            for i in range(0, len(symbols), batch_size):
                batch = symbols[i:i + batch_size]
                params = {
                    'symbols': ','.join(batch),
                    'timeframe': '1Day',
                    'start': earliest,
                    'end': latest_date,
                    'limit': '10000',
                    'feed': 'sip',
                    'adjustment': 'raw',
                }
                try:
                    resp = await asyncio.to_thread(
                        requests.get,
                        f'{cfg["data_url"]}/v2/stocks/bars',
                        headers=headers, params=params, timeout=30)
                    if resp.status_code == 200:
                        bars_data = resp.json().get('bars', {})
                        for sym, bars in bars_data.items():
                            for bar in bars:
                                date = bar['t'][:10]
                                cur.execute(
                                    'INSERT INTO daily_bars (symbol, date, open, high, low, close, volume) '
                                    'VALUES (%s, %s, %s, %s, %s, %s, %s) '
                                    'ON CONFLICT (symbol, date) DO NOTHING',
                                    (sym, date, bar['o'], bar['h'], bar['l'], bar['c'], bar['v']))
                                total_stored += 1
                        db._conn.commit()
                except Exception as e:
                    logger.warning(f"Daily bar batch {i // batch_size} failed: {e}")
                    try:
                        db._conn.rollback()
                    except Exception:
                        pass

            logger.info(f"Daily bar backfill complete: {total_stored} bars stored")
            self._add_message('system', f'Daily bar backfill: {total_stored} bars stored')

        except Exception as e:
            logger.error(f"Daily bar verification failed: {e}")
            try:
                db._conn.rollback()
            except Exception:
                pass

    async def _store_eod_bars(self, today: str):
        """Fetch and store today's daily bars for the full universe.

        Called once after market close so tomorrow's gap scanner can use
        prev_close directly from the DB instead of re-fetching from the API.
        """
        try:
            universe = self.scanner._resolve_universe()
            db = get_price_db()

            # Check which symbols already have today's bar
            existing = set()
            cur = db._conn.cursor()
            cur.execute(
                'SELECT symbol FROM daily_bars WHERE date = %s', (today,)
            )
            existing = {row[0] for row in cur.fetchall()}

            need_fetch = [s for s in universe if s not in existing]
            if not need_fetch:
                logger.info(f"EOD bars: all {len(universe)} symbols already have {today} data")
                return

            logger.info(f"EOD bars: fetching {len(need_fetch)}/{len(universe)} symbols for {today}")
            t0 = _time.monotonic()

            dfs = await asyncio.to_thread(
                _fetch_bars_multi_parallel, need_fetch, today, today, '1Day', 'sip'
            )

            stored = 0
            if dfs:
                db.upsert_bars_batch(dfs)
                stored = len(dfs)

            elapsed = _time.monotonic() - t0
            logger.info(f"EOD bars: stored {stored} symbols in {elapsed:.1f}s")
        except Exception as e:
            logger.warning(f"EOD bar storage failed (non-critical): {e}")

    # State Persistence — PostgreSQL
    # -------------------------------------------------------------------------

    def _save_state(self):
        """Persist state to PostgreSQL with validation and retry."""
        now_str = datetime.now(ET).strftime('%Y-%m-%d %H:%M:%S')
        state = {
            'status': self.status,
            'equity': self.engine.equity,
            'peak_equity': self.engine.peak_equity,
            'positions': {s: asdict(p) for s, p in self.engine.positions.items()},
            'daily_stats': asdict(self.engine.daily_stats),
            'config': asdict(self.config),
            'trade_log': [asdict(t) for t in self.engine.all_trade_log[-500:]],
            'messages': self.messages[-50:],
            'last_model_rebuild': self._last_model_rebuild,
            'saved_at': now_str,
            'last_updated': now_str,
            'active_strategy': self.config.active_strategy,
            'strategy_config': self._strategy_config,
            'conversation_history': self.llm_supervisor.memory.to_dict() if self.llm_supervisor else {},
            'event_bus_pending': self._event_bus.pending_count(),
            'journal_entries_today': len(self.journal._entries),
        }
        # Validate with Pydantic (log errors but don't block save)
        try:
            from state_schema import TraderStateSchema
            TraderStateSchema(**state)
        except Exception as ve:
            logger.warning(f"State validation warning: {ve}")

        # Save with 1 retry
        for attempt in range(2):
            try:
                db = get_price_db()
                db.save_trader_state(state, key=self.STATE_KEY)
                self._last_state_save_time = _time.monotonic()
                return
            except Exception as e:
                if attempt == 0:
                    logger.warning(f"State save failed (retrying): {e}")
                    try:
                        db._conn.rollback()
                    except Exception:
                        pass
                    _time.sleep(0.5)
                else:
                    logger.error(f"State save FAILED after retry: {e}")
                    try:
                        db._conn.rollback()
                    except Exception:
                        pass

    def _load_state(self):
        """Load persisted state from PostgreSQL."""
        state = None
        try:
            db = get_price_db()
            state = db.load_trader_state(key=self.STATE_KEY)
            if state:
                logger.info("Loaded state from PostgreSQL")
        except Exception as e:
            logger.warning(f"PostgreSQL state load failed: {e}")

        if state is None:
            return

        try:
            self.engine.equity = state.get('equity', self.config.initial_capital)
            self.engine.peak_equity = state.get('peak_equity', self.engine.equity)
            self.messages = state.get('messages', [])

            # Restore positions
            for sym, pd_dict in state.get('positions', {}).items():
                try:
                    self.engine.positions[sym] = GapPosition(**{
                        k: v for k, v in pd_dict.items() if k in GapPosition.__dataclass_fields__
                    })
                except Exception as e:
                    logger.warning(f"Could not restore position {sym}: {e}")

            # Restore trade log — SQLite is source of truth, JSON is fallback
            if not self.engine.all_trade_log:
                loaded_from = 'none'
                try:
                    db = get_price_db()
                    db_trades = db.load_all_trades()
                    if db_trades:
                        for td in db_trades:
                            self.engine.all_trade_log.append(TradeRecord(**{
                                k: v for k, v in td.items() if k in TradeRecord.__dataclass_fields__
                            }))
                        loaded_from = 'sqlite'
                        logger.info(f"Restored {len(db_trades)} trades from SQLite")
                except Exception as e:
                    logger.warning(f"SQLite trade load failed, falling back to JSON: {e}")

                if loaded_from == 'none':
                    # Fall back to JSON
                    json_trades = state.get('trade_log', [])
                    for td in json_trades:
                        self.engine.all_trade_log.append(TradeRecord(**{
                            k: v for k, v in td.items() if k in TradeRecord.__dataclass_fields__
                        }))
                    # Auto-migrate JSON trades into SQLite for future restarts
                    if json_trades:
                        try:
                            db = get_price_db()
                            migrated = 0
                            for td in json_trades:
                                if db.insert_trade(td):
                                    migrated += 1
                            logger.info(f"Auto-migrated {migrated}/{len(json_trades)} trades from JSON to SQLite")
                        except Exception as e:
                            logger.warning(f"Trade migration to SQLite failed (non-fatal): {e}")

            # Restore daily stats (survive mid-day restarts)
            saved_daily = state.get('daily_stats', {})
            today_str = datetime.now(ET).strftime('%Y-%m-%d')
            if saved_daily.get('date') == today_str and saved_daily.get('trades', 0) > 0:
                # Same day with actual data — restore the saved counters
                for key, value in saved_daily.items():
                    if hasattr(self.engine.daily_stats, key) and key in DailyStats.__dataclass_fields__:
                        try:
                            field_type = type(getattr(self.engine.daily_stats, key))
                            setattr(self.engine.daily_stats, key, field_type(value))
                        except (TypeError, ValueError):
                            pass
                logger.info(f"Restored daily stats: {saved_daily.get('trades', 0)} trades, "
                           f"${saved_daily.get('pnl', 0):.2f} P&L")
            else:
                # Zero/stale stats or different day — recalculate from trade log
                self._recalculate_daily_stats(today_str)

            # Restore saved config (user-tuned parameters survive restarts)
            saved_config = state.get('config', {})
            restored_keys = []
            for key, value in saved_config.items():
                if hasattr(self.config, key) and key in GapFadeConfig.__dataclass_fields__:
                    try:
                        field_type = type(getattr(self.config, key))
                        setattr(self.config, key, field_type(value))
                        restored_keys.append(key)
                    except (TypeError, ValueError):
                        pass
            if restored_keys:
                # Sync engine config reference
                self.engine.config = self.config
                logger.info(f"Restored {len(restored_keys)} config parameters from state")

            # Restore model rebuild timestamp
            self._last_model_rebuild = state.get('last_model_rebuild', '')

            # Restore strategy config
            self._strategy_config = state.get('strategy_config', {})
            saved_strategy = state.get('active_strategy', '')
            if saved_strategy:
                self.config.active_strategy = saved_strategy

            # Restore conversation history (only if same trading day)
            self._saved_conversation = state.get('conversation_history', {})

            logger.info(f"Loaded state: equity=${self.engine.equity:.2f}, "
                       f"{len(self.engine.positions)} positions, "
                       f"{len(self.engine.all_trade_log)} historical trades")
        except Exception as e:
            logger.warning(f"State load failed: {e}")

    def _recalculate_daily_stats(self, today_str: str = ''):
        """Recalculate daily stats from trade_log for today.

        Fallback for when daily_stats weren't saved or are from a different day.
        """
        if not today_str:
            today_str = datetime.now(ET).strftime('%Y-%m-%d')
        stats = self.engine.daily_stats
        stats.date = today_str
        stats.trades = 0
        stats.wins = 0
        stats.losses = 0
        stats.pnl = 0.0
        stats.consecutive_losses = 0
        stats.halted = False
        stats.halt_reason = ''

        for t in self.engine.all_trade_log:
            if hasattr(t, 'exit_time') and t.exit_time and t.exit_time.startswith(today_str):
                stats.trades += 1
                stats.pnl += t.pnl
                if t.pnl > 0:
                    stats.wins += 1
                    stats.consecutive_losses = 0
                elif t.pnl < 0:
                    stats.losses += 1
                    stats.consecutive_losses += 1

        stats.peak_equity = self.engine.equity
        if stats.trades > 0:
            logger.info(f"Recalculated daily stats from trade log: {stats.trades} trades, "
                       f"{stats.wins}W/{stats.losses}L, ${stats.pnl:+.2f} P&L")

    def get_state(self) -> dict:
        """Get current state for API response."""
        llm_state = None
        if self.llm_supervisor:
            llm_state = self.llm_supervisor.get_status()
            llm_state['enabled'] = True
        else:
            llm_state = {'enabled': False}
        strategy_state = {
            'active': self.config.active_strategy,
            'name': self.strategy.name if self.strategy else 'none',
            'has_indicators': self.indicator_engine is not None,
        }
        return {
            'status': self.status,
            'equity': round(self.engine.equity, 2),
            'peak_equity': round(self.engine.peak_equity, 2),
            'positions': {s: asdict(p) for s, p in self.engine.positions.items()},
            'daily_stats': asdict(self.engine.daily_stats),
            'candidates': [asdict(c) for c in self.candidates[:10]],
            'last_scan_time': self.last_scan_time,
            'metrics': self.engine.get_metrics(),
            'messages': self.messages[-30:],
            'config': asdict(self.config),
            'today_trades': [asdict(t) for t in self.engine.trade_log],
            'llm': llm_state,
            'strategy': strategy_state,
        }


