@app.post("/api/config")
async def update_config(body: dict):
    """Update strategy configuration with validation."""
    # P0-8: Validate all updates against safe ranges
    validated, errors = validate_config(body)
    if errors:
        logger.warning(f"Config validation errors: {errors}")

    config = live_trader.config
    applied = []
    changes = {}
    for key, value in validated.items():
        old_val = getattr(config, key, None)
        setattr(config, key, value)
        if old_val != value:
            applied.append(f"{key}: {old_val} → {value}")
            changes[key] = {'old': old_val, 'new': value}

    if applied:
        logger.info(f"Config updated: {', '.join(applied)}")

    # Log to config history
    if changes:
        try:
            db = get_price_db()
            _cur = db._conn.cursor()
            _cur.execute(
                'INSERT INTO config_history (timestamp, source, changes_json, config_snapshot) VALUES (%s, %s, %s, %s)',
                (datetime.now(ET).isoformat(), 'ui', json.dumps(changes, default=str), json.dumps(asdict(config), default=str))
            )
            db._conn.commit()
        except Exception as e:
            logger.warning(f"Config history log failed: {e}")

    # Sync capital if changed while idle (no open positions)
    old_capital = live_trader.engine.config.initial_capital
    live_trader.engine.config = config
    if config.initial_capital != old_capital and not live_trader.engine.positions:
        live_trader.engine.equity = config.initial_capital
        live_trader.engine.peak_equity = config.initial_capital
    # Rebuild scanner when universe config changes
    live_trader.scanner = GapScanner(config)
    # Toggle LLM supervisor on/off at runtime, rebuild if config changed
    if config.llm_enabled:
        if live_trader.llm_supervisor is None:
            live_trader.llm_supervisor = LLMSupervisor(config)
            logger.info(f"Rudra enabled: {config.llm_model}")
        else:
            # Rebuild if url/model/timeout changed
            sup = live_trader.llm_supervisor
            if (sup.url != config.llm_url or sup.model != config.llm_model
                    or sup.timeout != config.llm_timeout
                    or sup.provider != config.llm_provider):
                live_trader.llm_supervisor = LLMSupervisor(config)
                logger.info(f"Rudra rebuilt: {config.llm_model} @ {config.llm_url}")
    elif live_trader.llm_supervisor is not None:
        live_trader.llm_supervisor = None
        logger.info("Rudra disabled")
    # Rebuild execution broker if changed
    if 'execution_broker' in changes:
        old_broker = live_trader._execution_broker
        live_trader._execution_broker = _build_execution_broker(config)
        new_label = 'IBKR' if live_trader._use_ibkr else 'Alpaca'
        logger.info(f"Execution broker switched to {new_label}")
        # Disconnect old IBKR if we switched away
        if old_broker is not None and not live_trader._use_ibkr:
            try:
                import asyncio
                asyncio.ensure_future(old_broker.conn.disconnect())
            except Exception:
                pass
    # Cross-validate capital partition percentages
    if config.capital_partition:
        total_pct = config.gap_fade_capital_pct + config.intraday_capital_pct
        if total_pct > 1.0:
            # Auto-normalize to 100%
            config.gap_fade_capital_pct = round(config.gap_fade_capital_pct / total_pct, 2)
            config.intraday_capital_pct = round(1.0 - config.gap_fade_capital_pct, 2)
            errors.append(f"Capital percentages exceeded 100% — auto-normalized to "
                         f"{config.gap_fade_capital_pct:.0%}/{config.intraday_capital_pct:.0%}")

    # Persist config changes immediately (survive restarts)
    live_trader._save_state()

    result = {'config': asdict(config)}
    if errors:
        result['validation_errors'] = errors

    # Broadcast config change via WebSocket
    if changes:
        try:
            import asyncio
            asyncio.ensure_future(broadcast({
                'type': 'config_changed',
                'changes': changes,
                'source': 'ui',
            }))
        except Exception:
            pass

    return result


